package gomplate

import "os"

// tmplctx is the default template context type. It is a map with an Env method.
type tmplctx map[string]interface{}

func NewTmplCtx() *tmplctx {
	m := make(tmplctx)
	return &m
}

func (t *tmplctx) Env() map[string]string {
	out := make(map[string]string)
	for _, kv := range os.Environ() {
		for i := 0; i < len(kv); i++ {
			if kv[i] == '=' {
				out[kv[:i]] = kv[i+1:]
				break
			}
		}
	}
	return out
}

func (t *tmplctx) Set(key string, v interface{}) {
	if t == nil {
		return
	}
	if *t == nil {
		*t = make(tmplctx)
	}
	(*t)[key] = v
}

func (t *tmplctx) Delete(key string) {
	if t == nil || *t == nil {
		return
	}
	delete(*t, key)
}

func (t *tmplctx) Map() map[string]interface{} {
	if t == nil {
		return nil
	}
	return map[string]interface{}(*t)
}

// Clone returns a copy (shallow).
func (t *tmplctx) Clone() *tmplctx {
	n := NewTmplCtx()
	if t != nil {
		for k, v := range *t {
			(*n)[k] = v
		}
	}
	return n
}
EOF
cat > datafs/datafs.go <<'EOF'
package datafs

import (
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type wdFS struct {
	root string
}

func NewWdFS() *wdFS {
	wd, _ := os.Getwd()
	return &wdFS{root: wd}
}

// Abs resolves p to an absolute clean path.
func Abs(p string) string {
	if p == "" {
		return p
	}
	if !filepath.IsAbs(p) {
		wd, _ := os.Getwd()
		p = filepath.Join(wd, p)
	}
	return filepath.Clean(p)
}

func Trimmed(p string) string {
	a := Abs(p)
	return strings.TrimPrefix(a, "/")
}

// PathErrorLike creates an fs.PathError with trimmed path matching original behaviour.
func PathErrorLike(op, p string, err error) error {
	if err == nil {
		return nil
	}
	inner := err
	if pe, ok := err.(*os.PathError); ok {
		inner = pe.Err
	} else if pe, ok := err.(*fs.PathError); ok {
		inner = pe.Err
	}
	return &fs.PathError{Op: op, Path: Trimmed(p), Err: inner}
}

func ReadFile(p string) ([]byte, error) {
	a := Abs(p)
	b, err := os.ReadFile(a)
	if err != nil {
		return nil, PathErrorLike("open", p, err)
	}
	return b, nil
}

func Stat(p string) (os.FileInfo, error) {
	a := Abs(p)
	fi, err := os.Stat(a)
	if err != nil {
		return nil, PathErrorLike("stat", p, err)
	}
	return fi, nil
}

func Exists(p string) bool {
	_, err := Stat(p)
	return err == nil
}

func IsDir(p string) bool {
	fi, err := Stat(p)
	return err == nil && fi.IsDir()
}

func ReadDir(p string) ([]string, error) {
	a := Abs(p)
	entries, err := os.ReadDir(a)
	if err != nil {
		return nil, PathErrorLike("open", p, err)
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		names = append(names, e.Name())
	}
	sort.Strings(names)
	return names, nil
}

func Walk(p string) ([]string, error) {
	a := Abs(p)
	var out []string
	err := filepath.Walk(a, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		out = append(out, path)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

func WriteFile(p string, content []byte, mode os.FileMode) error {
	a := Abs(p)
	dir := filepath.Dir(a)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(a, content, mode)
}

var _ = fmt.Sprintf
var _ io.Reader
EOF
gofmt -w ctx datafs; ls"}

