cat > funcs/helpers.go <<'EOF'
package funcs

import (
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"strconv"
	"strings"
	"time"
)

// conversion helpers -------------------------------------------------------

func toString(v interface{}) string {
	if v == nil {
		return ""
	}
	switch s := v.(type) {
	case string:
		return s
	case []byte:
		return string(s)
	case error:
		return s.Error()
	case fmt.Stringer:
		// avoid calling String on types where fmt %v would differ? Most Stringer ok
		// time.Time etc.
		return s.String()
	default:
		return fmt.Sprintf("%v", v)
	}
}

func toStringE(v interface{}) (string, error) {
	return toString(v), nil
}

// parse numeric string like Go literal: handles 0x, 0o? , leading 0 octal?, exponent
func parseFloatString(s string) (float64, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, strconv.ErrSyntax
	}
	// special values
	switch s {
	case "NaN":
		return math.NaN(), nil
	case "Inf", "+Inf", "Infinity", "+Infinity":
		return math.Inf(1), nil
	case "-Inf", "-Infinity":
		return math.Inf(-1), nil
	}
	// hex float / int
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "0x") || strings.HasPrefix(lower, "-0x") || strings.HasPrefix(lower, "+0x") {
		// try int then float
		if i, err := strconv.ParseInt(s, 0, 64); err == nil {
			return float64(i), nil
		}
		if u, err := strconv.ParseUint(s, 0, 64); err == nil {
			return float64(u), nil
		}
		// hex float like 0x1p-2
		f, err := strconv.ParseFloat(s, 64)
		return f, err
	}
	// leading zero octal for ints, e.g. "02" -> ParseFloat gives 2 anyway
	return strconv.ParseFloat(s, 64)
}

func parseIntString(s string) (int64, error) {
	s0 := s
	s = strings.TrimSpace(s)
	if strings.ContainsAny(s, ".eE") && !strings.HasPrefix(strings.ToLower(s), "0x") {
		// float representation - parse as float then convert? Original uses ParseFloat for conversions in many places
		f, err := parseFloatString(s)
		if err != nil {
			return 0, err
		}
		return int64(f), nil
	}
	// Go literal base detection: ParseInt with base 0 handles 0x and leading 0
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return i, nil
	}
	// fallback float
	f, err := parseFloatString(s)
	if err != nil {
		// return original error from ParseFloat style expected by callers: they wrap with ParseFloat message
		// emulate: try ParseFloat on original
		_, ferr := strconv.ParseFloat(s0, 64)
		if ferr != nil {
			return 0, ferr
		}
		return 0, err
	}
	return int64(f), nil
}

func toFloat64(v interface{}) (float64, error) {
	if v == nil {
		return 0, nil
	}
	switch n := v.(type) {
	case float64:
		return n, nil
	case float32:
		return float64(n), nil
	case int:
		return float64(n), nil
	case int64:
		return float64(n), nil
	case int32:
		return float64(n), nil
	case int16:
		return float64(n), nil
	case int8:
		return float64(n), nil
	case uint:
		return float64(n), nil
	case uint64:
		return float64(n), nil
	case uint32:
		return float64(n), nil
	case uint16:
		return float64(n), nil
	case uint8:
		return float64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	case string:
		return parseFloatString(n)
	case []byte:
		return parseFloatString(string(n))
	case json.Number:
		return n.Float64()
	case time.Duration:
		return float64(n), nil
	default:
		// reflection for named numeric types
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			return float64(rv.Int()), nil
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return float64(rv.Uint()), nil
		case reflect.Float32, reflect.Float64:
			return rv.Float(), nil
		case reflect.String:
			return parseFloatString(rv.String())
		}
		return 0, fmt.Errorf("could not convert %q to float64: strconv.ParseFloat: parsing %q: invalid syntax", fmt.Sprintf("%v", v), fmt.Sprintf("%v", v))
	}
}

func toInt64(v interface{}) (int64, error) {
	if v == nil {
		return 0, nil
	}
	switch n := v.(type) {
	case int64:
		return n, nil
	case int:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case uint:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	case string:
		// original: could not convert "a" to int64: strconv.ParseFloat: parsing "a": invalid syntax
		// so they parse via ParseFloat
		f, err := strconv.ParseFloat(n, 64)
		if err != nil {
			// but hex/octal strings like 0x2, 02 need handling
			if i, ierr := parseIntString(n); ierr == nil {
				return i, nil
			}
			return 0, err
		}
		// if string was hex, ParseFloat in Go handles 0x ? Go ParseFloat accepts hex float only with p exponent, so handle above
		if strings.HasPrefix(strings.ToLower(strings.TrimSpace(n)), "0x") || strings.HasPrefix(strings.ToLower(strings.TrimSpace(n)), "-0x") {
			return parseIntString(n)
		}
		// leading zero octal: ParseFloat "02" =2 fine
		return int64(f), nil
	case []byte:
		return toInt64(string(n))
	case json.Number:
		if i, err := n.Int64(); err == nil {
			return i, nil
		}
		f, err := n.Float64()
		return int64(f), err
	case time.Duration:
		return int64(n), nil
	default:
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			return rv.Int(), nil
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return int64(rv.Uint()), nil
		case reflect.Float32, reflect.Float64:
			return int64(rv.Float()), nil
		case reflect.String:
			return toInt64(rv.String())
		}
		s := fmt.Sprintf("%v", v)
		_, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, err
		}
		return 0, fmt.Errorf("could not convert %q to int64: strconv.ParseFloat: parsing %q: invalid syntax", s, s)
	}
}

func toInt(v interface{}) (int, error) {
	i, err := toInt64(v)
	return int(i), err
}

// isFloatLike / isIntLike detection following docs: string representations etc.
func isFloatValue(v interface{}) bool {
	if v == nil {
		return false
	}
	switch n := v.(type) {
	case float64, float32:
		return true
	case string:
		// If a decimal point is part, consider float, also NaN/Inf? Probe results included NaN as float, Inf ?
		if n == "NaN" || n == "Inf" || n == "+Inf" || n == "-Inf" {
			return true
		}
		// must be parseable as float and contain '.' or 'e'/'E' ??? check
		if _, err := parseFloatString(n); err != nil {
			return false
		}
		// Go float literal detection: contains '.' or exponent, or is NaN/Inf
		return strings.ContainsAny(n, ".eE") || strings.HasPrefix(strings.ToLower(n), "0x") && strings.Contains(strings.ToLower(n), "p")
	case json.Number:
		return strings.ContainsAny(n.String(), ".eE")
	default:
		rv := reflect.ValueOf(v)
		return rv.Kind() == reflect.Float32 || rv.Kind() == reflect.Float64
	}
}

func isIntValue(v interface{}) bool {
	if v == nil {
		return false
	}
	switch n := v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	case string:
		if _, err := parseIntString(n); err == nil {
			// must not be float representation
			if strings.ContainsAny(n, ".") {
				return false
			}
			// exponent like 2e0 is float? probe: IsInt "2e0"?
			return true
		}
		return false
	case json.Number:
		_, err := n.Int64()
		return err == nil
	default:
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return true
		}
		return false
	}
}

func isNumValue(v interface{}) bool {
	return isIntValue(v) || isFloatValue(v) || isNumericType(v)
}

func isNumericType(v interface{}) bool {
	if v == nil {
		return false
	}
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return true
	case string:
		_, err := parseFloatString(v.(string))
		if err == nil {
			return true
