		return float64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	case string:
		return parseFloatString(n)
	case []byte:
		return parseFloatString(string(n))
	case json.Number:
		return n.Float64()
	case time.Duration:
		return float64(n), nil
	default:
		// reflection for named numeric types
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			return float64(rv.Int()), nil
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return float64(rv.Uint()), nil
		case reflect.Float32, reflect.Float64:
			return rv.Float(), nil
		case reflect.String:
			return parseFloatString(rv.String())
		}
		return 0, fmt.Errorf("could not convert %q to float64: strconv.ParseFloat: parsing %q: invalid syntax", fmt.Sprintf("%v", v), fmt.Sprintf("%v", v))
	}
}

func toInt64(v interface{}) (int64, error) {
	if v == nil {
		return 0, nil
	}
	switch n := v.(type) {
	case int64:
		return n, nil
	case int:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case uint:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	case string:
		// original: could not convert "a" to int64: strconv.ParseFloat: parsing "a": invalid syntax
		// so they parse via ParseFloat
		f, err := strconv.ParseFloat(n, 64)
		if err != nil {
			// but hex/octal strings like 0x2, 02 need handling
			if i, ierr := parseIntString(n); ierr == nil {
				return i, nil
			}
			return 0, err
		}
		// if string was hex, ParseFloat in Go handles 0x ? Go ParseFloat accepts hex float only with p exponent, so handle above
		if strings.HasPrefix(strings.ToLower(strings.TrimSpace(n)), "0x") || strings.HasPrefix(strings.ToLower(strings.TrimSpace(n)), "-0x") {
			return parseIntString(n)
		}
		// leading zero octal: ParseFloat "02" =2 fine
		return int64(f), nil
	case []byte:
		return toInt64(string(n))
	case json.Number:
		if i, err := n.Int64(); err == nil {
			return i, nil
		}
		f, err := n.Float64()
		return int64(f), err
	case time.Duration:
		return int64(n), nil
	default:
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			return rv.Int(), nil
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return int64(rv.Uint()), nil
		case reflect.Float32, reflect.Float64:
			return int64(rv.Float()), nil
		case reflect.String:
			return toInt64(rv.String())
		}
		s := fmt.Sprintf("%v", v)
		_, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, err
		}
		return 0, fmt.Errorf("could not convert %q to int64: strconv.ParseFloat: parsing %q: invalid syntax", s, s)
	}
}

func toInt(v interface{}) (int, error) {
	i, err := toInt64(v)
	return int(i), err
}

// isFloatLike / isIntLike detection following docs: string representations etc.
func isFloatValue(v interface{}) bool {
	if v == nil {
		return false
	}
	switch n := v.(type) {
	case float64, float32:
		return true
	case string:
		// If a decimal point is part, consider float, also NaN/Inf? Probe results included NaN as float, Inf ?
		if n == "NaN" || n == "Inf" || n == "+Inf" || n == "-Inf" {
			return true
		}
		// must be parseable as float and contain '.' or 'e'/'E' ??? check
		if _, err := parseFloatString(n); err != nil {
			return false
		}
		// Go float literal detection: contains '.' or exponent, or is NaN/Inf
		return strings.ContainsAny(n, ".eE") || strings.HasPrefix(strings.ToLower(n), "0x") && strings.Contains(strings.ToLower(n), "p")
	case json.Number:
		return strings.ContainsAny(n.String(), ".eE")
	default:
		rv := reflect.ValueOf(v)
		return rv.Kind() == reflect.Float32 || rv.Kind() == reflect.Float64
	}
}

func isIntValue(v interface{}) bool {
	if v == nil {
		return false
	}
	switch n := v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	case string:
		if _, err := parseIntString(n); err == nil {
			// must not be float representation
			if strings.ContainsAny(n, ".") {
				return false
			}
			// exponent like 2e0 is float? probe: IsInt "2e0"?
			return true
		}
		return false
	case json.Number:
		_, err := n.Int64()
		return err == nil
	default:
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return true
		}
		return false
	}
}

func isNumValue(v interface{}) bool {
	return isIntValue(v) || isFloatValue(v) || isNumericType(v)
}

func isNumericType(v interface{}) bool {
	if v == nil {
		return false
	}
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return true
	case string:
		_, err := parseFloatString(v.(string))
		if err == nil {
			return true
		}
		if _, err := parseIntString(v.(string)); err == nil {
			return true
		}
		return v == "NaN" || strings.Contains(v.(string), "Inf")
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
		return true
	}
	return false
}

// reflection helpers to handle slices/maps generically
func toSlice(v interface{}) ([]interface{}, error) {
	if v == nil {
		return nil, nil
	}
	if s, ok := v.([]interface{}); ok {
		return s, nil
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.String {
		// strings are not slices in gomplate contexts usually; return error?
		return nil, fmt.Errorf("expected a slice, got %T", v)
	}
	if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
		out := make([]interface{}, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = rv.Index(i).Interface()
		}
		return out, nil
	}
	return nil, fmt.Errorf("expected a slice, got %T", v)
}

func toStringSlice(v interface{}) ([]string, error) {
	if v == nil {
		return nil, nil
	}
	if s, ok := v.([]string); ok {
		return s, nil
	}
	slice, err := toSlice(v)
	if err != nil {
		// single string?
		if str, ok := v.(string); ok {
			return []string{str}, nil
		}
		return nil, err
	}
	out := make([]string, len(slice))
	for i, el := range slice {
		out[i] = toString(el)
	}
	return out, nil
}

func toMap(v interface{}) (map[string]interface{}, error) {
	if v == nil {
		return nil, nil
	}
	if m, ok := v.(map[string]interface{}); ok {
		return m, nil
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Map && rv.Type().Key().Kind() == reflect.String {
		out := make(map[string]interface{}, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			out[iter.Key().String()] = iter.Value().Interface()
		}
		return out, nil
	}
	// tmplctx-like map types (map[string]interface{} underlying)
	if rv.Kind() == reflect.Map {
		out := make(map[string]interface{})
		iter := rv.MapRange()
		for iter.Next() {
			out[toString(iter.Key().Interface())] = iter.Value().Interface()
		}
		return out, nil
	}
	if rv.Kind() == reflect.Pointer {
		if rv.IsNil() {
			return nil, nil
		}
		return toMap(rv.Elem().Interface())
	}
	return nil, fmt.Errorf("expected a map, got %T", v)
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	// sort alphabetically
	for i := 0; i < len(keys); i++ {
		for j := i + 1; j < len(keys); j++ {
			if keys[j] < keys[i] {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
	}
	return keys
}

func deepCopy(v interface{}) interface{} {
	if v == nil {
		return nil
	}
	switch t := v.(type) {
	case map[string]interface{}:
		m := make(map[string]interface{}, len(t))
		for k, val := range t {
			m[k] = deepCopy(val)
		}
		return m
	case []interface{}:
		s := make([]interface{}, len(t))
		for i, val := range t {
			s[i] = deepCopy(val)
		}
		return s
	case []string:
		s := make([]string, len(t))
		copy(s, t)
		return s
	default:
		// try map via reflection
		if m, err := toMap(v); err == nil && m != nil {
			out := make(map[string]interface{}, len(m))
			for k, val := range m {
				out[k] = deepCopy(val)
			}
			return out
		}
		if s, err := toSlice(v); err == nil && s != nil {
			// preserve []string etc? caller may expect []interface{} in merges
			out := make([]interface{}, len(s))
			for i, val := range s {
				out[i] = deepCopy(val)
			}
			return out
		}
		return v
	}
}
