package funcs

import (
	"bytes"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"gopkg.in/yaml.v3"
)

// TOML support is in toml.go

func parseYAMLObject(in string) (map[string]interface{}, error) {
	out := make(map[string]interface{})
	err := yaml.Unmarshal([]byte(in), &out)
	if err != nil {
		return nil, err
	}
	if out == nil {
		out = make(map[string]interface{})
	}
	return out, nil
}

func parseYAMLArray(in string) ([]interface{}, error) {
	var out []interface{}
	err := yaml.Unmarshal([]byte(in), &out)
	if err != nil {
		return nil, err
	}
	return out, nil
}

func parseJSONObject(in string) (map[string]interface{}, error) {
	out, err := parseYAMLObject(in)
	if err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %w", in, err)
	}
	return out, nil
}

func parseJSONArray(in string) ([]interface{}, error) {
	out, err := parseYAMLArray(in)
	if err != nil {
		return nil, fmt.Errorf("unable to unmarshal array %s: %w", in, err)
	}
	return out, nil
}

// ParseData parses raw bytes according to mime type, used by datasources.
// If mime empty, treat as text.
func ParseData(raw []byte, mime string) (interface{}, error) {
	// strip charset etc
	if i := strings.Index(mime, ";"); i >= 0 {
		mime = strings.TrimSpace(mime[:i])
	}
	switch mime {
	case "application/json", "text/json", "application/yaml", "application/x-yaml", "text/yaml", "text/x-yaml", "yaml":
		// try object, then array (matching original behaviour)
		if obj, err := parseYAMLObject(string(raw)); err == nil {
			// yaml object parser succeeds for some scalars? Actually yaml.Unmarshal into map errors for scalars, so fine
			// but need check: for array input, object fails
			return obj, nil
		} else {
			// attempt array
			arr, aerr := parseYAMLArray(string(raw))
			if aerr != nil {
				// For JSON, wrap array error; for YAML, return bare array error
				if mime == "application/json" || mime == "text/json" {
					return nil, fmt.Errorf("unable to unmarshal array %s: %w", string(raw), aerr)
				}
				return nil, aerr
			}
			return arr, nil
		}
	case "application/toml", "text/toml":
		obj, err := ParseTOML(string(raw))
		if err != nil {
			return nil, err // ParseTOML already wraps?
		}
		return obj, nil
	case "text/csv", "application/csv":
		return parseCSV(string(raw), ',')
	case "text/plain", "", "text/html":
		// hmm html? probe later; treat as string
		return string(raw), nil
	default:
		// known unsupported
		return nil, fmt.Errorf("data of type %q not yet supported", mime)
	}
}

func parseCSV(in string, delim rune) ([][]string, error) {
	r := csv.NewReader(strings.NewReader(in))
	r.Comma = delim
	r.LazyQuotes = false
	// csv reader default FieldsPerRecord?
	out := [][]string{}
	for {
		rec, err := r.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		out = append(out, rec)
	}
	if out == nil {
		out = [][]string{}
	}
	return out, nil
}

func csvByRow(in string, delim rune) ([]map[string]string, error) {
	rows, err := parseCSV(in, delim)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return []map[string]string{}, nil
	}
	header := rows[0]
	out := make([]map[string]string, 0, len(rows)-1)
	for _, row := range rows[1:] {
		m := make(map[string]string)
		for i, h := range header {
			if i < len(row) {
				m[h] = row[i]
			} else {
				m[h] = ""
			}
		}
		out = append(out, m)
	}
	return out, nil
}

func csvByColumn(in string, delim rune) (map[string][]string, error) {
	rows, err := parseCSV(in, delim)
	if err != nil {
		return nil, err
	}
	out := make(map[string][]string)
	if len(rows) == 0 {
		return out, nil
	}
	header := rows[0]
	for _, h := range header {
		out[h] = []string{}
	}
	for _, row := range rows[1:] {
		for i, h := range header {
			if i < len(row) {
				out[h] = append(out[h], row[i])
			}
		}
	}
	return out, nil
}

func toCSVString(v interface{}, delim rune) (string, error) {
	// v must be [][]string compatible or slice of slices
	var rows [][]string
	// direct
	if ss, ok := v.([][]string); ok {
		rows = ss
	} else {
		slice, err := toSlice(v)
		if err != nil {
			return "", err
		}
		for _, row := range slice {
			rs, err := toStringSlice(row)
			if err != nil {
				return "", err
			}
			rows = append(rows, rs)
		}
	}
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	w.Comma = delim
	// csv.Writer uses \r\n by default unless UseCRLF false; Writer default UseCRLF false actually? In Go, NewWriter uses \n? Check: csv.Writer UseCRLF false by default, writes \n. Original uses \r\n, so set true.
	w.UseCRLF = true
	if err := w.WriteAll(rows); err != nil {
		return "", err
	}
	w.Flush()
	return buf.String(), w.Error()
}

func marshalJSON(v interface{}) (string, error) {
	// Normalize values: convert maps with non-string keys etc via normalizeJSON
	nv := normalizeForJSON(v)
	b, err := json.Marshal(nv)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func normalizeForJSON(v interface{}) interface{} {
	if v == nil {
		return nil
	}
	switch t := v.(type) {
	case map[string]interface{}:
		m := make(map[string]interface{}, len(t))
		for k, val := range t {
			m[k] = normalizeForJSON(val)
		}
		return m
	case []interface{}:
		for i, el := range t {
			t[i] = normalizeForJSON(el)
		}
		return t
	case []string:
		return t
	default:
		if m, err := toMap(v); err == nil && m != nil {
			mm := make(map[string]interface{}, len(m))
			for k, val := range m {
				mm[k] = normalizeForJSON(val)
			}
			return mm
		}
		if s, err := toSlice(v); err == nil && s != nil {
			for i, el := range s {
				s[i] = normalizeForJSON(el)
			}
			return s
		}
		return v
	}
}
