package funcs

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

// minimal TOML parser covering common cases
func ParseTOML(in string) (map[string]interface{}, error) {
	root := make(map[string]interface{})
	current := root
	lines := strings.Split(in, "\n")
	for idx, raw := range lines {
		_ = idx
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]") {
			// array of tables
			key := strings.TrimSpace(line[2 : len(line)-2])
			parts := splitTOMLKey(key)
			parent := navigateTOML(root, parts[:len(parts)-1], true)
			last := parts[len(parts)-1]
			var arr []interface{}
			if existing, ok := parent[last]; ok {
				if a, ok2 := existing.([]interface{}); ok2 {
					arr = a
				}
			}
			newMap := make(map[string]interface{})
			arr = append(arr, newMap)
			parent[last] = arr
			current = newMap
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			key := strings.TrimSpace(line[1 : len(line)-1])
			parts := splitTOMLKey(key)
			current = navigateTOML(root, parts, true)
			continue
		}
		// key = value
		eq := findTOMLEquals(line)
		if eq < 0 {
			// error messages similar to original: Near line 1 (last key parsed ''): ...
			return nil, fmt.Errorf("unable to unmarshal object %s: Near line %d (last key parsed ''): unexpected EOF; expected key separator '='", in, idx+1)
		}
		keyPart := strings.TrimSpace(line[:eq])
		valPart := strings.TrimSpace(line[eq+1:])
		// strip trailing comment not in string - simplistic: handled in value parser? skip
		val, _, err := parseTOMLValue(valPart, in, idx+1)
		if err != nil {
			return nil, err
		}
		parts := splitTOMLKey(keyPart)
		target := navigateTOML(current, parts[:len(parts)-1], true)
		target[parts[len(parts)-1]] = val
	}
	return root, nil
}

func findTOMLEquals(s string) int {
	inStr := byte(0)
	for i := 0; i < len(s); i++ {
		if inStr != 0 {
			if s[i] == inStr {
				inStr = 0
			}
			continue
		}
		if s[i] == '"' || s[i] == '\'' {
			inStr = s[i]
			continue
		}
		if s[i] == '=' {
			return i
		}
	}
	return -1
}

func splitTOMLKey(k string) []string {
	// handle quoted keys simplistically
	var parts []string
	var cur strings.Builder
	inQ := byte(0)
	for i := 0; i < len(k); i++ {
		c := k[i]
		if inQ != 0 {
			if c == inQ {
				inQ = 0
			} else {
				cur.WriteByte(c)
			}
			continue
		}
		if c == '"' || c == '\'' {
			inQ = c
			continue
		}
		if c == '.' {
			parts = append(parts, strings.TrimSpace(cur.String()))
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	parts = append(parts, strings.TrimSpace(cur.String()))
	return parts
}

func navigateTOML(root map[string]interface{}, parts []string, create bool) map[string]interface{} {
	cur := root
	for _, p := range parts {
		if p == "" {
			continue
		}
		if next, ok := cur[p].(map[string]interface{}); ok {
			cur = next
		} else if arr, ok := cur[p].([]interface{}); ok && len(arr) > 0 {
			if m, ok := arr[len(arr)-1].(map[string]interface{}); ok {
				cur = m
			} else {
				m := make(map[string]interface{})
				cur[p] = m
				cur = m
			}
		} else {
			m := make(map[string]interface{})
			cur[p] = m
			cur = m
		}
	}
	return cur
}

func parseTOMLValue(s string, full string, line int) (interface{}, int, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, 0, fmt.Errorf("unable to unmarshal object %s: Near line %d (last key parsed ''): expected value", full, line)
	}
	switch {
	case strings.HasPrefix(s, "\"\"\""):
		end := strings.Index(s[3:], "\"\"\"")
		if end < 0 {
			return s[3:], len(s), nil
		}
		return s[3 : 3+end], 3 + end + 3, nil
	case strings.HasPrefix(s, "'''"):
		end := strings.Index(s[3:], "'''")
		if end < 0 {
			return s[3:], len(s), nil
		}
		return s[3 : 3+end], 3 + end + 3, nil
	case s[0] == '"':
		// parse quoted
		var out strings.Builder
		i := 1
		for ; i < len(s); i++ {
			if s[i] == '\\' && i+1 < len(s) {
				i++
				switch s[i] {
				case 'n': out.WriteByte('\n')
				case 't': out.WriteByte('\t')
				case 'r': out.WriteByte('\r')
				case '"': out.WriteByte('"')
				case '\\': out.WriteByte('\\')
				case 'u':
					if i+4 < len(s) {
						code, _ := strconv.ParseInt(s[i+1:i+5], 16, 32)
						out.WriteRune(rune(code))
						i += 4
					}
				default: out.WriteByte(s[i])
				}
				continue
			}
			if s[i] == '"' {
				i++
				break
			}
			out.WriteByte(s[i])
		}
		return out.String(), i, nil
	case s[0] == '\'':
		end := strings.Index(s[1:], "'")
		if end < 0 {
			return s[1:], len(s), nil
		}
		return s[1 : 1+end], end + 2, nil
	case s[0] == '[':
		// array - need find matching ]
		depth := 0
		inStr := byte(0)
		end := -1
		for i := 0; i < len(s); i++ {
			c := s[i]
			if inStr != 0 {
				if c == inStr && (inStr == '\'' || i == 0 || s[i-1] != '\\') {
					inStr = 0
				}
				continue
			}
			if c == '"' || c == '\'' {
				inStr = c
				continue
			}
			if c == '[' || c == '{' {
				depth++
			}
			if c == ']' || c == '}' {
				depth--
				if depth == 0 {
					end = i
					break
				}
			}
		}
		if end < 0 {
			end = len(s)
		}
		inner := strings.TrimSpace(s[1:end])
		var arr []interface{}
		arr = []interface{}{}
		if inner != "" {
			parts := splitTOMLArray(inner)
			for _, p := range parts {
				v, _, err := parseTOMLValue(p, full, line)
				if err != nil {
					return nil, 0, err
				}
				arr = append(arr, v)
			}
		}
		return arr, end + 1, nil
	case s[0] == '{':
		depth := 0
		end := -1
		inStr := byte(0)
		for i := 0; i < len(s); i++ {
			c := s[i]
			if inStr != 0 {
				if c == inStr && s[i-1] != '\\' {
					inStr = 0
				}
				continue
			}
			if c == '"' || c == '\'' {
				inStr = c
				continue
			}
			if c == '{' || c == '[' { depth++ }
			if c == '}' || c == ']' {
				depth--
				if depth == 0 { end = i; break }
			}
		}
		if end < 0 { end = len(s)-1 }
		inner := strings.TrimSpace(s[1:end])
		m := make(map[string]interface{})
		if inner != "" {
			parts := splitTOMLArray(inner)
			for _, p := range parts {
				eq := findTOMLEquals(p)
				if eq < 0 { continue }
				k := splitTOMLKey(strings.TrimSpace(p[:eq]))
				v, _, err := parseTOMLValue(strings.TrimSpace(p[eq+1:]), full, line)
				if err != nil { return nil, 0, err }
				target := navigateTOML(m, k[:len(k)-1], true)
				target[k[len(k)-1]] = v
			}
		}
		return m, end + 1, nil
	case s == "true":
		return true, 4, nil
	case s == "false":
		return false, 5, nil
	default:
		// number / date / bare - take until comma or end (for top-level, whole)
		token := s
		// strip trailing comment
		if idx := strings.Index(token, " #"); idx >= 0 {
			token = strings.TrimSpace(token[:idx])
		}
		// date?
		layouts := []string{time.RFC3339Nano, "2006-01-02T15:04:05", "2006-01-02 15:04:05Z07:00", "2006-01-02", "15:04:05"}
		for _, lay := range layouts {
			if t, err := time.Parse(lay, token); err == nil {
				// only if token looks like date (contains - or :)
				if strings.Contains(token, "-") || strings.Contains(token, ":") {
					return t, len(token), nil
				}
			}
		}
		clean := strings.ReplaceAll(token, "_", "")
		if i, err := strconv.ParseInt(clean, 10, 64); err == nil {
			return i, len(token), nil
		}
		if strings.HasPrefix(strings.ToLower(clean), "0x") {
			if i, err := strconv.ParseInt(clean, 0, 64); err == nil { return i, len(token), nil }
		}
		if strings.HasPrefix(strings.ToLower(clean), "0o") {
			if i, err := strconv.ParseInt(clean, 0, 64); err == nil { return i, len(token), nil }
		}
		if strings.HasPrefix(strings.ToLower(clean), "0b") {
			if i, err := strconv.ParseInt(clean, 0, 64); err == nil { return i, len(token), nil }
		}
		if f, err := strconv.ParseFloat(clean, 64); err == nil {
			return f, len(token), nil
		}
		if token == "inf" || token == "+inf" { return strconv.ParseFloat("Inf",64) }
		// invalid starting with { etc would have been caught; for other bare words, original error
		if strings.HasPrefix(token, "{") {
			return nil, 0, fmt.Errorf("unable to unmarshal object %s: Near line %d (last key parsed ''): expected '.' or '=', but got '{' instead", full, line)
		}
		return nil, 0, fmt.Errorf("unable to unmarshal object %s: Near line %d (last key parsed ''): expected value but found %q instead", full, line, token)
	}
}

func splitTOMLArray(s string) []string {
	var parts []string
	depth := 0
	inStr := byte(0)
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr != 0 {
			if c == inStr && (i == 0 || s[i-1] != '\\') {
				inStr = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			inStr = c
			continue
		}
		if c == '[' || c == '{' { depth++ }
		if c == ']' || c == '}' { depth-- }
		if c == ',' && depth == 0 {
			parts = append(parts, strings.TrimSpace(s[start:i]))
			start = i + 1
		}
	}
	if start < len(s) {
		p := strings.TrimSpace(s[start:])
		if p != "" {
			parts = append(parts, p)
		}
	}
	return parts
}

// ToTOML encoding -----------------------------------------------------------------
func MarshalTOML(v interface{}) (string, error) {
	m, err := toMap(v)
	if err != nil {
		// if not map, maybe ??? original expects map
		return "", err
	}
	var sb strings.Builder
	writeTOMLMap(&sb, m, nil, 0)
	return sb.String(), nil
}

func writeTOMLMap(sb *strings.Builder, m map[string]interface{}, prefix []string, depth int) {
	keys := sortedKeys(m)
	indent := strings.Repeat("  ", depth)
	// scalars first
	for _, k := range keys {
		val := m[k]
		if _, isMap := val.(map[string]interface{}); isMap { continue }
		if mm, _ := toMap(val); mm != nil { continue }
		// array of tables?
		if isTableArray(val) { continue }
		sb.WriteString(indent)
		sb.WriteString(tomlKey(k))
		sb.WriteString(" = ")
		sb.WriteString(tomlValue(val))
		sb.WriteString("\n")
	}
	// tables
	for _, k := range keys {
		val := m[k]
		if isTableArray(val) {
			arr, _ := toSlice(val)
			for _, el := range arr {
				mm, _ := toMap(el)
				if mm == nil { continue }
				full := append(append([]string{}, prefix...), k)
				sb.WriteString("\n")
				sb.WriteString(indent) // tables headers not indented? probe nested
				// original: [b] at col0, values indented. For nested, header is [a.b] ?
				// We'll write header without indent for depth 0, check later
				_ = full
				sb.WriteString("[[")
				sb.WriteString(strings.Join(full, "."))
				sb.WriteString("]]\n")
				writeTOMLMapBody(sb, mm, full, depth+1)
			}
			continue
		}
		mm, err := toMap(val)
		if err != nil || mm == nil { continue }
		full := append(append([]string{}, prefix...), k)
		sb.WriteString("\n")
		sb.WriteString("[")
		// quote keys if needed
		var quoted []string
		for _, p := range full { quoted = append(quoted, tomlKey(p)) }
		sb.WriteString(strings.Join(quoted, "."))
		sb.WriteString("]\n")
		writeTOMLMapBody(sb, mm, full, depth+1)
	}
}

func writeTOMLMapBody(sb *strings.Builder, m map[string]interface{}, prefix []string, depth int) {
	keys := sortedKeys(m)
	indent := strings.Repeat("  ", depth-0) // depth is 1 for first level -> 2 spaces? Actually earlier: [b] values had 2 spaces. depth param herein: when called from top depth+1 =1 , indent should be 2 spaces = strings.Repeat("  ", depth)
	indent = strings.Repeat("  ", depth)
	_ = indent
	// scalars
	for _, k := range keys {
		val := m[k]
		if mm, _ := toMap(val); mm != nil { continue }
		if isTableArray(val) { continue }
		sb.WriteString(indent)
		sb.WriteString(tomlKey(k))
		sb.WriteString(" = ")
		sb.WriteString(tomlValue(val))
		sb.WriteString("\n")
	}
	for _, k := range keys {
		val := m[k]
		if isTableArray(val) {
			arr, _ := toSlice(val)
			for _, el := range arr {
				mm, _ := toMap(el)
				if mm == nil { continue }
				full := append(append([]string{}, prefix...), k)
				sb.WriteString("\n[")
				var quoted []string
				for _, p := range full { quoted = append(quoted, tomlKey(p)) }
				// array table header uses [[ ]]
				sb.WriteString("[")
				sb.WriteString(strings.Join(quoted, "."))
				sb.WriteString("]]\n")
				writeTOMLMapBody(sb, mm, full, depth+1)
			}
			continue
		}
		mm, err := toMap(val)
		if err != nil || mm == nil { continue }
		full := append(append([]string{}, prefix...), k)
		sb.WriteString("\n")
		sb.WriteString("[")
		var quoted []string
		for _, p := range full { quoted = append(quoted, tomlKey(p)) }
		sb.WriteString(strings.Join(quoted, "."))
		sb.WriteString("]\n")
		writeTOMLMapBody(sb, mm, full, depth+1)
	}
}

func isTableArray(v interface{}) bool {
	s, err := toSlice(v)
	if err != nil || len(s) == 0 { return false }
	_, err = toMap(s[0])
	return err == nil && s[0] != nil
	// note: [] of scalars returns false because toMap fails
}

func tomlKey(k string) string {
	if k == "" { return `""` }
	for _, r := range k {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '_' || r == '-') {
			return strconv.Quote(k)
		}
	}
	return k
}

func tomlValue(v interface{}) string {
	switch t := v.(type) {
	case string:
		return strconv.Quote(t)
	case bool:
		if t { return "true" }
		return "false"
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return fmt.Sprintf("%d", t)
	case float32, float64:
		f, _ := toFloat64(v)
		// TOML float representation: if integral, "1.0"? Probe later
		s := strconv.FormatFloat(f, 'f', -1, 64)
		if !strings.Contains(s, ".") && !strings.Contains(s, "e") && !strings.Contains(s, "E") && s != "Inf" && s != "-Inf" && s != "NaN" {
			s += ".0"
		}
		return s
	case time.Time:
		return t.Format(time.RFC3339Nano)
	case nil:
		return `""`
	default:
		if s, err := toSlice(v); err == nil {
			var parts []string
			for _, el := range s {
				parts = append(parts, tomlValue(el))
			}
			return "[" + strings.Join(parts, ", ") + "]"
		}
		if m, err := toMap(v); err == nil && m != nil {
			// inline table
			keys := sortedKeys(m)
			var parts []string
			for _, k := range keys {
				parts = append(parts, tomlKey(k)+" = "+tomlValue(m[k]))
			}
			return "{" + strings.Join(parts, ", ") + "}"
		}
		return strconv.Quote(fmt.Sprintf("%v", v))
	}
}

var _ = sort.StringSlice{}
EOF
"}

