			// but need check: for array input, object fails
			return obj, nil
		} else {
			// attempt array
			arr, aerr := parseYAMLArray(string(raw))
			if aerr != nil {
				// For JSON, wrap array error; for YAML, return bare array error
				if mime == "application/json" || mime == "text/json" {
					return nil, fmt.Errorf("unable to unmarshal array %s: %w", string(raw), aerr)
				}
				return nil, aerr
			}
			return arr, nil
		}
