func parseCSV(in string, delim rune) ([][]string, error) {
	r := csv.NewReader(strings.NewReader(in))
	r.Comma = delim
	r.LazyQuotes = false
	// csv reader default FieldsPerRecord?
	out := [][]string{}
	for {
		rec, err := r.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		out = append(out, rec)
	}
	if out == nil {
		out = [][]string{}
	}
	return out, nil
}

func csvByRow(in string, delim rune) ([]map[string]string, error) {
	rows, err := parseCSV(in, delim)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return []map[string]string{}, nil
	}
	header := rows[0]
	out := make([]map[string]string, 0, len(rows)-1)
	for _, row := range rows[1:] {
		m := make(map[string]string)
		for i, h := range header {
			if i < len(row) {
				m[h] = row[i]
			} else {
				m[h] = ""
			}
		}
		out = append(out, m)
	}
	return out, nil
}

func csvByColumn(in string, delim rune) (map[string][]string, error) {
	rows, err := parseCSV(in, delim)
	if err != nil {
		return nil, err
	}
	out := make(map[string][]string)
	if len(rows) == 0 {
		return out, nil
	}
	header := rows[0]
	for _, h := range header {
		out[h] = []string{}
	}
	for _, row := range rows[1:] {
		for i, h := range header {
			if i < len(row) {
				out[h] = append(out[h], row[i])
			}
		}
	}
	return out, nil
}

func toCSVString(v interface{}, delim rune) (string, error) {
	// v must be [][]string compatible or slice of slices
	var rows [][]string
	// direct
	if ss, ok := v.([][]string); ok {
		rows = ss
	} else {
		slice, err := toSlice(v)
		if err != nil {
			return "", err
		}
		for _, row := range slice {
			rs, err := toStringSlice(row)
			if err != nil {
				return "", err
			}
			rows = append(rows, rs)
		}
	}
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	w.Comma = delim
	// csv.Writer uses \r\n by default unless UseCRLF false; Writer default UseCRLF false actually? In Go, NewWriter uses \n? Check: csv.Writer UseCRLF false by default, writes \n. Original uses \r\n, so set true.
	w.UseCRLF = true
	if err := w.WriteAll(rows); err != nil {
		return "", err
	}
	w.Flush()
	return buf.String(), w.Error()
}

func marshalJSON(v interface{}) (string, error) {
	// Normalize values: convert maps with non-string keys etc via normalizeJSON
	nv := normalizeForJSON(v)
	b, err := json.Marshal(nv)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func normalizeForJSON(v interface{}) interface{} {
	if v == nil {
		return nil
	}
	switch t := v.(type) {
	case map[string]interface{}:
		m := make(map[string]interface{}, len(t))
		for k, val := range t {
			m[k] = normalizeForJSON(val)
		}
		return m
	case []interface{}:
		for i, el := range t {
			t[i] = normalizeForJSON(el)
		}
		return t
	case []string:
		return t
	default:
		if m, err := toMap(v); err == nil && m != nil {
			mm := make(map[string]interface{}, len(m))
			for k, val := range m {
				mm[k] = normalizeForJSON(val)
			}
			return mm
		}
		if s, err := toSlice(v); err == nil && s != nil {
			for i, el := range s {
				s[i] = normalizeForJSON(el)
			}
			return s
		}
		return v
	}
}
