}

func writeTOMLMap(sb *strings.Builder, m map[string]interface{}, prefix []string, depth int) {
	keys := sortedKeys(m)
	indent := strings.Repeat("  ", depth)
	// scalars first
	for _, k := range keys {
		val := m[k]
		if _, isMap := val.(map[string]interface{}); isMap { continue }
		if mm, _ := toMap(val); mm != nil { continue }
		// array of tables?
		if isTableArray(val) { continue }
		sb.WriteString(indent)
		sb.WriteString(tomlKey(k))
		sb.WriteString(" = ")
		sb.WriteString(tomlValue(val))
		sb.WriteString("\n")
	}
	// tables
	for _, k := range keys {
		val := m[k]
		if isTableArray(val) {
			arr, _ := toSlice(val)
			for _, el := range arr {
				mm, _ := toMap(el)
				if mm == nil { continue }
				full := append(append([]string{}, prefix...), k)
