}

func (f *CollFuncs) Slice(values ...interface{}) []interface{} {
	if values == nil {
		return []interface{}{}
	}
	return values
}

func (f *CollFuncs) GoSlice(item interface{}, indices ...interface{}) (interface{}, error) {
	// mimic Go template slice builtin: use reflection
	v := reflect.ValueOf(item)
	if !v.IsValid() {
		return nil, fmt.Errorf("slice, error: untyped nil")
	}
	// convert indices to int
	idx := make([]int, len(indices))
	for i, a := range indices {
		n, err := toInt(a)
		if err != nil { return nil, err }
		idx[i] = n
	}
	// use reflect Slice / Slice3
	switch v.Kind() {
	case reflect.String, reflect.Slice, reflect.Array:
		switch len(idx) {
		case 0:
			return v.Interface(), nil
		case 1:
			return v.Slice(idx[0], v.Len()).Interface(), nil
		case 2:
			if v.Kind() == reflect.String {
