		case 3:
			if v.Kind() == reflect.String {
				return nil, fmt.Errorf("slice: string cannot have 3 indexes")
			}
			return v.Slice3(idx[0], idx[1], idx[2]).Interface(), nil
		default:
			return nil, fmt.Errorf("too many slice indexes: %d", len(idx))
		}
	default:
		return nil, fmt.Errorf("can't slice item of type %T", item)
