func (f *CollFuncs) Index(args ...interface{}) (interface{}, error) {
	// coll.Index indexes... in  ; last arg is in, preceding are indexes
	if len(args) < 1 {
		return nil, fmt.Errorf("Index: expected at least 1 argument")
	}
	if len(args) == 1 {
		// only in? return?
		return args[0], nil
	}
	indexes := args[:len(args)-1]
	cur := args[len(args)-1]
	for _, idx := range indexes {
		if cur == nil {
			return nil, fmt.Errorf("index of nil")
		}
		if m, err := toMap(cur); err == nil && m != nil {
			k := toString(idx)
			v, ok := m[k]
			if !ok {
				return nil, fmt.Errorf("map has no entry for key %q", k)
			}
			cur = v
			continue
		}
		if slice, err := toSlice(cur); err == nil {
			i, err := toInt(idx)
			if err != nil { return nil, err }
			if i < 0 || i >= len(slice) {
				return nil, fmt.Errorf("index out of range: %d", i)
			}
			cur = slice[i]
			continue
		}
		if s, ok := cur.(string); ok {
			i, err := toInt(idx)
			if err != nil { return nil, err }
			if i < 0 || i >= len(s) { return nil, fmt.Errorf("index out of range: %d", i) }
			cur = string(s[i])
			continue
		}
		// reflect struct/map etc
		rv := reflect.ValueOf(cur)
		if rv.Kind() == reflect.Map {
			key := reflect.ValueOf(idx)
			// convert key type
