			if !v.IsValid() { return nil, fmt.Errorf("map has no entry for key %q", toString(idx)) }
			cur = v.Interface()
			continue
		}
		return nil, fmt.Errorf("cannot index %T", cur)
	}
	return cur, nil
}

func (f *CollFuncs) Keys(maps ...interface{}) ([]interface{}, error) {
	var out []interface{}
	for _, m := range maps {
		mp, err := toMap(m)
		if err != nil { return nil, err }
		keys := sortedKeys(mp)
		for _, k := range keys { out = append(out, k) }
	}
	if out == nil { out = []interface{}{} }
	return out, nil
}

func (f *CollFuncs) Values(maps ...interface{}) ([]interface{}, error) {
	var out []interface{}
	for _, m := range maps {
		mp, err := toMap(m)
		if err != nil { return nil, err }
		keys := sortedKeys(mp)
		for _, k := range keys { out = append(out, mp[k]) }
	}
	if out == nil { out = []interface{}{} }
	return out, nil
}

func (f *CollFuncs) Append(value interface{}, list ...interface{}) ([]interface{}, error) {
	// Usage: coll.Append value list ... ? Docs: Append value list..., but pipeline: list | append value -> value is ??? Pipeline passes list as last arg, so append 5 where list piped: coll.Append 5 [list] ??? Wait example: `coll.Slice 1 1 2 3 | append 5` - pipeline: append is alias to Coll.Append, args: (5) plus piped list as final arg. So signature Append(value, list...) where last elements? Actually template pipeline appends piped value as last argument. So call is Append(5, slice). That's value=5, listArgs=[slice]. If direct: coll.Append value list... where list may be slice or varargs?
	// Need determine: In alias context, function signature likely Append(list, value) in sprig? Sprig append(list, item) ??? Let's probe later; implement heuristic:
	// Our method defined as Append(value interface{}, list ...interface{}) - When called as `coll.Append 5 (coll.Slice 1 2)` -> value=5, list=[slice] -> result should append 5 to slice (flatten one level if single slice)
	// When piped: `slice | coll.Append 5` -> same.
	// If called as `coll.Append (coll.Slice ...) 5` ??? would misinterpret.
	// Check original probing later.
	var base []interface{}
	if len(list) == 1 {
		if s, err := toSlice(list[0]); err == nil {
			base = append([]interface{}{}, s...)
		} else {
			base = []interface{}{list[0]}
		}
	} else if len(list) > 1 {
		// list may be ?? If first arg was list and value ??? ambiguous
		base = append([]interface{}{}, list...)
	} else {
		base = []interface{}{}
	}
