	out := append([]interface{}{}, s...)
	// determine sortable: all same comparable type type
	sortSliceStable(out, key)
	return out, nil
}

func sortSliceStable(out []interface{}, key string) {
	getKey := func(v interface{}) interface{} {
		if key == "" { return v }
		if m, err := toMap(v); err == nil && m != nil {
			return m[key]
		}
		// struct field?
		rv := reflect.ValueOf(v)
		if rv.Kind() == reflect.Struct {
			f := rv.FieldByName(key)
			if f.IsValid() { return f.Interface() }
		}
		if rv.Kind() == reflect.Pointer && !rv.IsNil() {
			f := rv.Elem().FieldByName(key)
			if f.IsValid() { return f.Interface() }
		}
		return v
	}
	sort.SliceStable(out, func(i, j int) bool {
		a := getKey(out[i]); b := getKey(out[j])
		return lessValue(a, b)
	})
