			if em, err := toMap(existing); err == nil {
				if vm, err2 := toMap(v); err2 == nil {
					out[k] = mergeMapsPriority(em, vm)
					continue
				}
			}
			// keep existing
			continue
		}
		out[k] = deepCopy(v)
	}
	return out
}

