			if _, isString := k.(string); !isString {
				for _, el := range s { keys = append(keys, toString(el)) }
				continue
			}
		}
		keys = append(keys, toString(k))
	}
	return keys, m, nil
}

func (f *CollFuncs) Pick(args ...interface{}) (map[string]interface{}, error) {
	keys, mval, err := parseKeysArgs(args)
	if err != nil { return nil, err }
	m, err := toMap(mval)
	if err != nil { return nil, err }
	out := make(map[string]interface{})
	for _, k := range keys {
