		if s, ok := cur.(string); ok {
			i, err := toInt(idx)
			if err != nil { return nil, err }
			if i < 0 || i >= len(s) { return nil, fmt.Errorf("index out of range: %d", i) }
			cur = string(s[i])
			continue
		}
		// reflect struct/map etc
		rv := reflect.ValueOf(cur)
		if rv.Kind() == reflect.Map {
			key := reflect.ValueOf(idx)
			// convert key type
			if key.Type() != rv.Type().Key() {
				if key.Type().ConvertibleTo(rv.Type().Key()) {
					key = key.Convert(rv.Type().Key())
				} else {
					key = reflect.ValueOf(toString(idx))
					if key.Type().ConvertibleTo(rv.Type().Key()) { key = key.Convert(rv.Type().Key()) }
				}
			}
			v := rv.MapIndex(key)
			if !v.IsValid() { return nil, fmt.Errorf("map has no entry for key %q", toString(idx)) }
			cur = v.Interface()
			continue
		}
		return nil, fmt.Errorf("cannot index %T", cur)
	}
	return cur, nil
}

func (f *CollFuncs) Keys(maps ...interface{}) ([]interface{}, error) {
	var out []interface{}
	for _, m := range maps {
		mp, err := toMap(m)
		if err != nil { return nil, err }
		keys := sortedKeys(mp)
		for _, k := range keys { out = append(out, k) }
	}
	if out == nil { out = []interface{}{} }
	return out, nil
}

func (f *CollFuncs) Values(maps ...interface{}) ([]interface{}, error) {
	var out []interface{}
	for _, m := range maps {
		mp, err := toMap(m)
		if err != nil { return nil, err }
		keys := sortedKeys(mp)
		for _, k := range keys { out = append(out, mp[k]) }
	}
	if out == nil { out = []interface{}{} }
	return out, nil
}

