func (f *CollFuncs) Prepend(value interface{}, list ...interface{}) ([]interface{}, error) {
	var base []interface{}
	if len(list) == 1 {
		if s, err := toSlice(list[0]); err == nil {
			base = append([]interface{}{}, s...)
		} else {
			base = []interface{}{list[0]}
		}
	} else if len(list) > 1 {
		base = append([]interface{}{}, list...)
	}
	out := []interface{}{value}
	return append(out, base...), nil
}

func (f *CollFuncs) Uniq(list interface{}) ([]interface{}, error) {
	s, err := toSlice(list)
	if err != nil { return nil, err }
	seen := map[string]bool{}
	out := []interface{}{}
	for _, el := range s {
		key := fmt.Sprintf("%#v", el)
		if !seen[key] {
			seen[key] = true
			out = append(out, el)
		}
	}
	return out, nil
}

func (f *CollFuncs) Flatten(args ...interface{}) ([]interface{}, error) {
	// Flatten [depth] list ; last arg is list, optional first is depth
	depth := -1
	var list interface{}
	if len(args) == 1 {
		list = args[0]
	} else if len(args) == 2 {
		d, err := toInt(args[0])
		if err != nil { return nil, err }
		depth = d
		list = args[1]
	} else {
		return nil, fmt.Errorf("Flatten: expected 1 or 2 arguments")
	}
	s, err := toSlice(list)
	if err != nil { return nil, err }
	out := flattenSlice(s, depth, 0)
	if out == nil { out = []interface{}{} }
	return out, nil
}

func flattenSlice(s []interface{}, depth int, cur int) []interface{} {
	out := []interface{}{}
	for _, el := range s {
		if inner, err := toSlice(el); err == nil && el != nil {
			// only flatten if depth permits: depth -1 infinite, or cur < depth
			// Examples: Flatten 2 on nested: need semantics levels.
			// Flatten with depth 2: top level is level1 ?
			// Implement: if depth == -1 or cur < depth { flatten recursively } where cur starts 0 for top elements? Test later.
			if depth == -1 || cur < depth {
				out = append(out, flattenSlice(inner, depth, cur+1)...)
				continue
			}
		}
		out = append(out, el)
	}
	return out
}

func (f *CollFuncs) Reverse(list interface{}) ([]interface{}, error) {
	s, err := toSlice(list)
	if err != nil { return nil, err }
	out := make([]interface{}, len(s))
	for i, el := range s { out[len(s)-1-i] = el }
	return out, nil
}

func (f *CollFuncs) Sort(args ...interface{}) ([]interface{}, error) {
	// Sort [key] list ; last is list, optional key first
	var key string
	var list interface{}
	if len(args) == 1 {
		list = args[0]
	} else if len(args) == 2 {
		key = toString(args[0])
		list = args[1]
	} else {
		return nil, fmt.Errorf("Sort: expected 1 or 2 arguments")
	}
	s, err := toSlice(list)
	if err != nil { return nil, err }
	// copy
	out := append([]interface{}{}, s...)
	// determine sortable: all same comparable type type
	sortSliceStable(out, key)
	return out, nil
}

func sortSliceStable(out []interface{}, key string) {
	getKey := func(v interface{}) interface{} {
		if key == "" { return v }
		if m, err := toMap(v); err == nil && m != nil {
			return m[key]
		}
		// struct field?
		rv := reflect.ValueOf(v)
		if rv.Kind() == reflect.Struct {
			f := rv.FieldByName(key)
			if f.IsValid() { return f.Interface() }
		}
		if rv.Kind() == reflect.Pointer && !rv.IsNil() {
			f := rv.Elem().FieldByName(key)
			if f.IsValid() { return f.Interface() }
		}
		return v
	}
	sort.SliceStable(out, func(i, j int) bool {
		a := getKey(out[i]); b := getKey(out[j])
		return lessValue(a, b)
	})
	// If not sortable (mixed types/maps), original returns unmodified. Our sort may have reordered arbitrarily - check mixed: if elements are maps without key etc, lessValue false both ways so stable preserves.
}

func lessValue(a, b interface{}) bool {
	// numeric comparison if both numeric
	if isNumValue(a) && isNumValue(b) {
		af, _ := toFloat64(a); bf, _ := toFloat64(b)
		return af < bf
	}
	if sa, ok := a.(string); ok {
		if sb, ok := b.(string); ok { return sa < sb }
	}
	// bool?
	if ba, ok := a.(bool); ok {
		if bb, ok := b.(bool); ok { return !ba && bb }
	}
	return fmt.Sprintf("%v", a) < fmt.Sprintf("%v", b)
}

func (f *CollFuncs) Merge(dst interface{}, srcs ...interface{}) (map[string]interface{}, error) {
	dstMap, err := toMap(dst)
	if err != nil { return nil, err }
	result := deepCopy(dstMap).(map[string]interface{})
	// precedence: dst highest, then srcs in order for filling missing / deep merging where existing wins
	for _, src := range srcs {
		sm, err := toMap(src)
		if err != nil { continue }
		result = mergeMapsPriority(result, sm)
	}
	return result, nil
}

// mergeMapsPriority: a wins over b, but deep merge maps
func mergeMapsPriority(a, b map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{})
	for k, v := range a { out[k] = deepCopy(v) }
	for k, v := range b {
		if existing, ok := out[k]; ok {
			// if both maps, deep merge with existing priority
			if em, err := toMap(existing); err == nil {
				if vm, err2 := toMap(v); err2 == nil {
					out[k] = mergeMapsPriority(em, vm)
					continue
				}
			}
			// keep existing
			continue
		}
		out[k] = deepCopy(v)
	}
	return out
}

// For datasource merging: first wins
func MergeMapsFirstWins(maps []map[string]interface{}) map[string]interface{} {
	if len(maps) == 0 { return map[string]interface{}{} }
	result := deepCopy(maps[0]).(map[string]interface{})
	for _, m := range maps[1:] {
		result = mergeMapsPriority(result, m)
	}
	return result
}

func parseKeysArgs(args []interface{}) ([]string, interface{}, error) {
	// Pick/Omit: keys... map ; last arg map, preceding keys may be slice or strings
	if len(args) < 1 { return nil, nil, fmt.Errorf("expected at least 1 argument") }
	m := args[len(args)-1]
	keyArgs := args[:len(args)-1]
	var keys []string
	for _, k := range keyArgs {
		if s, err := toSlice(k); err == nil && k != nil {
			// if it's a slice arg, expand
			if _, isString := k.(string); !isString {
				for _, el := range s { keys = append(keys, toString(el)) }
				continue
			}
		}
		keys = append(keys, toString(k))
	}
	return keys, m, nil
}

func (f *CollFuncs) Pick(args ...interface{}) (map[string]interface{}, error) {
	keys, mval, err := parseKeysArgs(args)
	if err != nil { return nil, err }
	m, err := toMap(mval)
	if err != nil { return nil, err }
	out := make(map[string]interface{})
	for _, k := range keys {
		if v, ok := m[k]; ok { out[k] = v }
	}
	return out, nil
}

func (f *CollFuncs) Omit(args ...interface{}) (map[string]interface{}, error) {
	keys, mval, err := parseKeysArgs(args)
	if err != nil { return nil, err }
	m, err := toMap(mval)
	if err != nil { return nil, err }
	omitSet := make(map[string]bool)
	for _, k := range keys { omitSet[k] = true }
	out := make(map[string]interface{})
	for k, v := range m {
		if !omitSet[k] { out[k] = v }
	}
	return out, nil
}

func (f *CollFuncs) Set(key string, value interface{}, m interface{}) (map[string]interface{}, error) {
	mp, err := toMap(m)
	if err != nil { return nil, err }
	// modify in place if it is map[string]interface{}
	if real, ok := m.(map[string]interface{}); ok {
		real[key] = value
		return real, nil
	}
	// tmplctx-like?
	rv := reflect.ValueOf(m)
	if rv.Kind() == reflect.Map && rv.Type().Key().Kind() == reflect.String {
		rv.SetMapIndex(reflect.ValueOf(key), reflect.ValueOf(value))
		return mp, nil
	}
	if rv.Kind() == reflect.Pointer && !rv.IsNil() && rv.Elem().Kind() == reflect.Map {
		rv.Elem().SetMapIndex(reflect.ValueOf(key), reflect.ValueOf(value))
		// return as map
		mp[key] = value
		return mp, nil
	}
	mp[key] = value
	return mp, nil
}

func (f *CollFuncs) Unset(key string, m interface{}) (map[string]interface{}, error) {
	mp, err := toMap(m)
	if err != nil { return nil, err }
	if real, ok := m.(map[string]interface{}); ok {
		delete(real, key)
		return real, nil
	}
	rv := reflect.ValueOf(m)
	if rv.Kind() == reflect.Map && rv.Type().Key().Kind() == reflect.String {
		rv.SetMapIndex(reflect.ValueOf(key), reflect.Value{})
		return mp, nil
	}
	if rv.Kind() == reflect.Pointer && !rv.IsNil() && rv.Elem().Kind() == reflect.Map {
		rv.Elem().SetMapIndex(reflect.ValueOf(key), reflect.Value{})
	}
	delete(mp, key)
	return mp, nil
}

