	if b {
		return true
	}
	// extra true-ish?
	switch strings.ToLower(in) {
	case "yes", "y", "on":
		// need probe; may be false in original. We'll check later.
		return false
	}
	return false
}

func (f *ConvFuncs) Default(dflt interface{}, in interface{}) interface{} {
	if in == nil {
		return dflt
	}
	// empty check
	v := reflect.ValueOf(in)
	switch v.Kind() {
	case reflect.String, reflect.Slice, reflect.Array, reflect.Map:
		if v.Len() == 0 { return dflt }
	case reflect.Bool:
		if !v.Bool() { return dflt }
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		if v.Int() == 0 { return dflt }
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		if v.Uint() == 0 { return dflt }
	case reflect.Float32, reflect.Float64:
		if v.Float() == 0 { return dflt }
	case reflect.Pointer, reflect.Interface:
		if v.IsNil() { return dflt }
	}
	if in == "" {
		return dflt
	}
	return in
}

func (f *ConvFuncs) Join(in interface{}, sep string) (string, error) {
	// Docs usage conv.Join in sep, but pipeline: in | conv.Join sep -> Join(sep, in)?? Wait template pipe adds in as last arg, so if function signature is Join(in, sep), pipeline usage would be `sep | ???` confusion. Docs Usage only shows conv.Join in sep (no pipeline). Check alias `join $a "-"` example: join is alias for Conv.Join, args (slice, "-") so first slice second sep.
	slice, err := toSlice(in)
	if err != nil {
		// single value?
		return toString(in), nil
	}
	parts := make([]string, len(slice))
	for i, el := range slice { parts[i] = toString(el) }
	return strings.Join(parts, sep), nil
}

func (f *ConvFuncs) URL(in string) (*url.URL, error) {
	return url.Parse(in)
}

