func (f *ConvFuncs) ParseInt(s string, base int, bitSize int) (int64, error) {
	return strconv.ParseInt(s, base, bitSize)
}
func (f *ConvFuncs) ParseFloat(s string, bitSize int) (float64, error) {
	return strconv.ParseFloat(s, bitSize)
}
func (f *ConvFuncs) ParseUint(s string, base int, bitSize int) (uint64, error) {
	return strconv.ParseUint(s, base, bitSize)
}
func (f *ConvFuncs) Atoi(s string) (int, error) {
	return strconv.Atoi(s)
}

func toBoolImpl(v interface{}) bool {
	if v == nil { return false }
	switch t := v.(type) {
	case bool:
		return t
	case string:
		s := strings.ToLower(strings.TrimSpace(t))
		if s == "1" || s == "t" || s == "true" || s == "yes" { return true }
		// 0x01 etc: parse int?
		if i, err := parseIntString(t); err == nil && i == 1 { return true }
		if i, err := strconv.ParseInt(t, 0, 64); err == nil && i == 1 { return true }
		return false
	default:
		if i, err := toInt64(v); err == nil {
			return i == 1
		}
		return false
	}
