package funcs

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Abbrev [offset] width input ; last is input
func (f *StringFuncs) Abbrev(args ...interface{}) (string, error) {
	if len(args) < 2 || len(args) > 3 {
		return "", fmt.Errorf("Abbrev: expected 2 or 3 arguments")
	}
	input := toString(args[len(args)-1])
	var offset, width int
	var err error
	if len(args) == 2 {
		width, err = toInt(args[0])
		if err != nil { return "", err }
	} else {
		offset, err = toInt(args[0])
		if err != nil { return "", err }
		width, err = toInt(args[1])
		if err != nil { return "", err }
	}
	return abbrev(input, offset, width), nil
}

func abbrev(in string, offset, width int) string {
	runes := []rune(in)
	if len(runes) <= width {
		return in
	}
	// Based on examples: Abbrev 9 on "foobarbazquxquux" (16) => "foobar..." (6+3=9)
	// Abbrev 6 9 => "...baz..." offset 6: starting at? string from offset?
	if offset == 0 {
		if width < 4 {
			// just trunc?
			if width >= 0 && width < len(runes) { return string(runes[:width]) }
			return in
		}
		return string(runes[:width-3]) + "..."
	}
	// with offset: result is "..." + substring + "..." if there is remainder, width includes ellipses
	// Example offset6 width9: "...baz..." => middle 3 chars starting at offset? in[6:9]="baz"
	if width < 7 {
		// fallback
		return string(runes[offset:])
	}
	midLen := width - 6
	if offset+midLen > len(runes) {
		midLen = len(runes) - offset
		// if reaches end, trailing ellipsis maybe not?
		return "..." + string(runes[offset:offset+midLen])
	}
	return "..." + string(runes[offset:offset+midLen]) + "..."
}

func (f *StringFuncs) Contains(substr string, input interface{}) bool {
	return strings.Contains(toString(input), substr)
}
func (f *StringFuncs) HasPrefix(prefix string, input interface{}) bool {
	return strings.HasPrefix(toString(input), prefix)
}
func (f *StringFuncs) HasSuffix(suffix string, input interface{}) bool {
	return strings.HasSuffix(toString(input), suffix)
}

func (f *StringFuncs) Indent(args ...interface{}) (string, error) {
	// Indent [width] [indent] input ; last input
	// forms:
	// Indent input (default 1, " ")? probe? docs: optional width, indent
	// Pipeline examples: strings.Indent "  "  (single string arg + piped input) -> that single arg is indent string, width default 1? If arg is string, treat as indent.
