package funcs

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

func (f *TimeFuncs) Now() time.Time { return time.Now() }

func (f *TimeFuncs) Parse(layout string, value string) (time.Time, error) {
	return time.Parse(layout, value)
}
func (f *TimeFuncs) ParseLocal(layout string, value string) (time.Time, error) {
	return time.ParseInLocation(layout, value, time.Local)
}
func (f *TimeFuncs) ParseInLocation(layout string, location string, value string) (time.Time, error) {
	loc, err := time.LoadLocation(location)
	if err != nil { return time.Time{}, err }
	return time.ParseInLocation(layout, value, loc)
}
func (f *TimeFuncs) ParseDuration(value string) (time.Duration, error) {
	// argument could be ??? typed string in signature; template engine handles
	return time.ParseDuration(value)
}
func (f *TimeFuncs) Since(t time.Time) time.Duration { return time.Since(t) }
func (f *TimeFuncs) Until(t time.Time) time.Duration { return time.Until(t) }

func (f *TimeFuncs) Unix(args ...interface{}) (time.Time, error) {
	// Unix time ; arg may be int or string with fractional
	if len(args)!=1 { return time.Time{}, fmt.Errorf("Unix: expected 1 argument") }
	v := args[0]
	if s, ok := v.(string); ok {
		// split fractional
		if strings.Contains(s, ".") {
			parts := strings.SplitN(s, ".", 2)
			sec, err := strconv.ParseInt(parts[0], 10, 64)
			if err != nil {
				// maybe negative? handle
				f, ferr := strconv.ParseFloat(s, 64)
				if ferr != nil { return time.Time{}, err }
				sec = int64(f)
				nsec := int64((f - float64(sec)) * 1e9)
