// returns raw, mime, specialParsed, isSpecial, err
func (r *Registry) readRawForDS(ds *Datasource, subpath string) ([]byte, string, interface{}, bool, error) {
	rawURL := strings.TrimSpace(ds.URL)
	// merge scheme
	if strings.HasPrefix(rawURL, "merge:") {
		parsed, err := r.readMerge(ds, rawURL)
		if err != nil {
			return nil, "", nil, false, err
		}
		return nil, "", parsed, true, nil
	}

	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, "", nil, false, fmt.Errorf("couldn't read datasource '%s' (%s): %v", ds.Alias, ds.URL, err)
	}
	scheme := u.Scheme

	// type override from query
	typeOverride := ""
	if u.Query() != nil {
		if t := u.Query().Get("type"); t != "" {
			typeOverride = t
		}
	}

	switch scheme {
	case "", "file":
		return r.readFileDS(ds, u, subpath, typeOverride)
	case "http", "https":
		return r.readHTTPDS(ds, u, subpath, typeOverride)
	case "env":
		return r.readEnvDS(ds, u, subpath, typeOverride)
	case "stdin":
		name := strings.Trim(u.Path, "/")
		if subpath != "" {
			// name for mime maybe subpath
			name = strings.Trim(subpath, "/")
		}
		b, err := r.getStdin()
		if err != nil {
			return nil, "", nil, false, r.wrapErr(ds, ds.URL, "open", fmt.Sprintf("stdin:///%s", name), name, err)
		}
		mimeType := typeOverride
		if mimeType == "" {
			mimeType = mimeByName(name)
		}
		return b, mimeType, nil, false, nil
	case "git+https", "git+http", "git+ssh", "git", "git+file":
		// attempt git clone handling in datasource_git.go
		return r.readGitDS(ds, u, subpath, typeOverride)
	default:
		// unsupported schemes that originally try known providers - return fsys error for unknown, special messages for known cloud
		if scheme == "vault" || scheme == "consul" || scheme == "consul+http" || scheme == "consul+https" || scheme == "aws+sm" || scheme == "aws+smp" || scheme == "s3" || scheme == "gs" || scheme == "azblob" || scheme == "gcp+meta" {
			// try cloud reading (may contact endpoints etc, implemented in datasource_cloud.go)
			return r.readCloudDS(ds, u, subpath, typeOverride)
		}
		// unknown
		fsysPath := rawURL
		if !strings.HasSuffix(fsysPath, "/") {
			fsysPath += "/"
		}
		inner := fmt.Errorf("fsys for path %s: filesystem provider for %q unavailable: no filesystem registered for scheme %q", fsysPath, fsysPath, scheme)
		return nil, "", nil, false, fmt.Errorf("couldn't read datasource '%s' (%s): %v", ds.Alias, ds.URL, inner)
	}
}

func mimeByName(name string) string {
	if name == "" || name == "." {
		return "text/plain"
	}
	ext := path.Ext(name)
	if ext == "" {
		ext = filepath.Ext(name)
	}
	switch strings.ToLower(ext) {
	case ".json":
		return "application/json"
	case ".yaml", ".yml":
		return "application/yaml"
	case ".toml":
		return "application/toml"
	case ".csv":
		return "text/csv"
	case ".txt", ".text":
		return "text/plain"
	case ".xml":
		return "application/xml"
	case ".html", ".htm":
		return "text/html"
	}
	mt := mime.TypeByExtension(ext)
	if mt == "" {
		return "text/plain"
	}
	return mt
}

func (r *Registry) wrapErr(ds *Datasource, outer string, op string, fsURL string, name string, inner error) error {
