// file datasource
func (r *Registry) readFileDS(ds *Datasource, u *url.URL, subpath string, typeOverride string) ([]byte, string, interface{}, bool, error) {
	rawPath := u.Path
	isFileScheme := u.Scheme == "file"
	if !isFileScheme {
		// relative url: url.Parse may put path in Path, or Opaque for some?
		if u.Opaque != "" {
			rawPath = u.Opaque
		}
		// preserve original before query/fragment
		orig := ds.URL
		// strip query/fragment from orig manually to keep ./ etc
		if idx := strings.IndexAny(orig, "?#"); idx >= 0 {
			orig = orig[:idx]
		}
		rawPath = orig
	} else {
		// file:///tmp/... Path = /tmp/...
		if u.Host != "" && u.Host != "localhost" {
			// file://host/path ... treat host as part?
			rawPath = "/" + u.Host + u.Path
		}
	}
	// compute resolved path
	resolved := rawPath
	nameForMime := rawPath
	if subpath != "" {
		baseDir := rawPath
		if !strings.HasSuffix(rawPath, "/") {
			// if existing dir, use as dir else dirname
			if fi, err := os.Stat(datafs.Abs(rawPath)); err == nil && fi.IsDir() {
				baseDir = rawPath
			} else {
				baseDir = filepath.Dir(rawPath)
				// Dir("config.json") = "." - keep .
			}
		}
		resolved = filepath.Join(baseDir, strings.TrimPrefix(subpath, "/"))
		nameForMime = subpath
	}
	absResolved := datafs.Abs(resolved)

	// determine outer display, fsURL, name for errors
	var outerDisplay, fsURL, name string
	if subpath != "" {
		if isFileScheme || filepath.IsAbs(rawPath) {
			// display joined file URL
			outerDisplay = "file://" + absResolved // abs starts with /, so file:///...
			fsURL = "file:///"
			name = absResolved
		} else {
			outerDisplay = "/" + strings.TrimPrefix(subpath, "/")
			fsURL = "/"
			name = strings.TrimPrefix(subpath, "/")
			if strings.TrimPrefix(subpath, "/") == "" { name = subpath }
			// special: name as given without leading? Observed for subpath "nope.json" name "nope.json", for "/a/b" name "a/b"
			name = strings.TrimPrefix(subpath, "/")
		}
	} else {
		if isFileScheme || filepath.IsAbs(rawPath) {
			outerDisplay = "file://" + absResolved
			fsURL = "file:///"
			name = absResolved
			// name should be original path if file scheme? abs same
			if isFileScheme {
				name = u.Path
			}
		} else {
			outerDisplay = ds.URL // original as supplied (without ? maybe include? If original had query, display includes? We'll keep as is)
			// outer should be orig without query? test for missing with type... unknown. keep ds.URL
			fsURL = "/"
			name = rawPath
		}
	}

	// read / stat
	fi, err := os.Stat(absResolved)
	if err != nil {
		inner := datafs.PathErrorLike("open", resolved, err)
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "open", fsURL, name, inner)
	}
	if fi.IsDir() {
		entries, err := datafs.ReadDir(resolved)
		if err != nil {
			return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "open", fsURL, name, err)
		}
		return nil, "", entries, true, nil
	}
	b, err := os.ReadFile(absResolved)
	if err != nil {
		inner := datafs.PathErrorLike("open", resolved, err)
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "open", fsURL, name, inner)
	}
	mt := typeOverride
	if mt == "" {
		mt = mimeByName(nameForMime)
	}
	return b, mt, nil, false, nil
}

// http datasource
func (r *Registry) readHTTPDS(ds *Datasource, u *url.URL, subpath string, typeOverride string) ([]byte, string, interface{}, bool, error) {
	// resolved URL
	resolved := *u
	if subpath != "" {
		// similar dir logic: if path ends / or ... use dir of path else use path as dir? For http bucket example base is directory url (ends with / or is root). We'll follow file logic based on suffix and can't stat.
		basePath := u.Path
		if !strings.HasSuffix(basePath, "/") {
			// treat base as file, use its dir
			basePath = path.Dir(basePath)
			if !strings.HasSuffix(basePath, "/") { basePath += "/" }
		}
		resolved.Path = path.Join(basePath, strings.TrimPrefix(subpath, "/"))
		// path.Join cleans leading, ensure leading slash
		if !strings.HasPrefix(resolved.Path, "/") { resolved.Path = "/" + resolved.Path }
	}
	fullURL := resolved.String()
	// fsURL and name
	fsURL := u.Scheme + "://" + u.Host + "/"
	if subpath == "" && (u.Path == "" || u.Path == "/") {
		fsURL = fullURL
		if !strings.HasSuffix(fsURL, "/") { /* keep */ }
		name := "."
		_ = name
	}
	name := ""
	if subpath != "" {
		// name is resolved path's base? Or full resolved path trimmed? Original for directory base + subpath? Unknown. Use basename of resolved?
		// For http missing with subpath, outer display is full URL, inner name likely resolved base
		name = path.Base(resolved.Path)
	} else {
		if u.Path == "" || u.Path == "/" {
			name = "."
		} else {
			name = path.Base(u.Path)
		}
	}
	if subpath == "" && u.Path != "" && u.Path != "/" {
		// fsURL should be root up to last slash? Original for /notfound: fsURL http://host/ (root), for /dir/file likely ??? Wait path /data.json -> fs root is scheme://host + dir? It gave http://.../ for /notfound (dir = /) consistent with dir of path. Or root.
		dir := path.Dir(u.Path)
		if dir != "/" && !strings.HasSuffix(dir, "/") { dir += "/" }
		if dir != "." {
			fsURL = u.Scheme + "://" + u.Host + dir
		}
		// preserve query in fsURL if present? Earlier case with ?foo=bar fsURL included "?foo=bar" at root. That suggests fsURL string is u with Path replaced by dir and query kept: scheme://host/?foo=bar
		if u.RawQuery != "" {
			// fsURL as earlier: http://host/?foo=bar
			fsURL = u.Scheme + "://" + u.Host + dir + "?" + u.RawQuery
		}
	}
	outerDisplay := ds.URL
	if subpath != "" {
		outerDisplay = fullURL
		// but if query in original, full includes? resolved retains query
	}

	client := &http.Client{}
	// HEAD
	headReq, err := http.NewRequest(http.MethodHead, fullURL, nil)
	if err != nil {
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "stat", fsURL, name, err)
	}
	for k, vals := range ds.Header {
		for _, v := range vals { headReq.Header.Add(k, v) }
	}
	headResp, err := client.Do(headReq)
	if err != nil {
		// err is *url.Error with string `Head "...": ...`
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "stat", fsURL, name, err)
	}
	defer headResp.Body.Close()
	io.Copy(io.Discard, headResp.Body)
	if headResp.StatusCode >= 400 {
		inner := fmt.Errorf("http HEAD failed with status %d", headResp.StatusCode)
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "stat", fsURL, name, inner)
	}
	// If directory URL (ends /) - original behaviour: HEAD would have been to ... already; for our server, "/" returned 404 above, but real directory servers might return html listing. We'll attempt GET and if content-type html ??? treat as ?
	// GET
	getReq, err := http.NewRequest(http.MethodGet, fullURL, nil)
	if err != nil { return nil, "", nil, false, err }
	for k, vals := range ds.Header {
		for _, v := range vals { getReq.Header.Add(k, v) }
	}
	getResp, err := client.Do(getReq)
	if err != nil {
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "stat", fsURL, name, err)
	}
	defer getResp.Body.Close()
	if getResp.StatusCode >= 400 {
		inner := fmt.Errorf("http HEAD failed with status %d", getResp.StatusCode)
		return nil, "", nil, false, r.wrapErr(ds, outerDisplay, "stat", fsURL, name, inner)
	}
	body, err := io.ReadAll(getResp.Body)
	if err != nil { return nil, "", nil, false, err }
	mt := typeOverride
	if mt == "" {
		ct := getResp.Header.Get("Content-Type")
		if ct != "" {
			// use as mime (ParseData strips params)
			// But if ct is text/html for a json file? extension may win? We'll prefer extension if ct is octet-stream/html?
			// Original: content type from response is used - if path extension is known and ct differs, ??? Choose extension if ct == "text/html" and ext known json etc? Hmm
			mt = ct
			// If ct is application/octet-stream, fallback to extension
			if strings.Contains(ct, "application/octet-stream") {
				mt = mimeByName(resolved.Path)
			}
		} else {
			mt = mimeByName(resolved.Path)
		}
	}
	// If URL path ends with "/" and content is? Might be directory listing not supported - return as text (ParseData text/plain/html)
	return body, mt, nil, false, nil
}

// env datasource
func (r *Registry) readEnvDS(ds *Datasource, u *url.URL, subpath string, typeOverride string) ([]byte, string, interface{}, bool, error) {
	// env:///VAR
	if u.Host != "" {
		fsURL := "env://" + u.Host + "/"
		inner := fmt.Errorf("file does not exist")
		return nil, "", nil, false, r.wrapErr(ds, ds.URL, "stat", fsURL, ".", inner)
	}
	varName := strings.Trim(u.Path, "/")
	if subpath != "" {
		// subpath treated as? If base path empty, subpath is var name; if base var is ??? join?
		if varName == "" {
			varName = strings.Trim(subpath, "/")
		} else {
			varName = varName + "/" + strings.Trim(subpath, "/")
			// env vars cannot contain /, maybe they join with _? ignore
		}
	}
	fsURL := "env:///"
	val, ok := os.LookupEnv(varName)
	if !ok {
		inner := fmt.Errorf("file does not exist")
		return nil, "", nil, false, r.wrapErr(ds, ds.URL, "stat", fsURL, varName, inner)
	}
	mt := typeOverride
	if mt == "" { mt = "text/plain" }
	return []byte(val), mt, nil, false, nil
}

// merge
func (r *Registry) readMerge(ds *Datasource, rawURL string) (interface{}, error) {
	opaque := strings.TrimPrefix(rawURL, "merge:")
	// split by |
	parts := strings.Split(opaque, "|")
	var maps []map[string]interface{}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		// each part as datasource url
		// If part matches defined alias? merge examples use file names, not alias... If alias exists, use it?
		var parsed interface{}
		var err error
		if partDS, ok := r.Get(part); ok {
			parsed, err = r.readParsedForDS(partDS, "")
		} else {
			// treat as URL / file
			tmpDS := &Datasource{Alias: part, URL: part, Header: make(http.Header)}
			parsed, err = r.readParsedForDS(tmpDS, "")
		}
		if err != nil {
			// Wrap according to original merge error format:
			// couldn't read datasource 'x' (merge:...): open (url: "merge:///", name: "config.json|missing"): open config.json|missing: opening merge part "missing": open tmp/t2/missing: no such file or directory
			// inner extraction difficult. Construct approximate:
			// Try extract inner path error from err: we need file path stripped
			// For missing file part, our readParsedForDS error is wrapped "couldn't read datasource 'missing' (...): open ...: open tmp/..."
			// We simplify to replicate first level:
			msg := err.Error()
			// attempt to find last "open <path>:"
			// Build inner: opening merge part "<part>": <last inner error segment>
			// Find colon segments - use msg after last "): "
			innerPart := msg
			if idx := strings.LastIndex(msg, "open "); idx >= 0 {
				// need full path error: from that open onwards that's the PathError (open tmp/...)
				innerPart = msg[idx:]
				// innerPart like "open tmp/t2/missing: no such file or directory"
			}
			return nil, fmt.Errorf("couldn't read datasource '%s' (%s): open (url: %q, name: %q): open %s: opening merge part %q: %s", ds.Alias, ds.URL, "merge:///", opaque, opaque, part, innerPart)
		}
		mp, err := toMap(parsed)
		if err != nil {
			// if parsed is not map, maybe skip? If array etc merge fails?
			return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %v", ds.Alias, ds.URL, err)
		}
		maps = append(maps, mp)
	}
	merged := MergeMapsFirstWins(maps)
	return merged, nil
}

func (r *Registry) Reachable(alias string) bool {
	_, err := r.ReadParsed(alias, "")
	return err == nil
}
