// merge
func (r *Registry) readMerge(ds *Datasource, rawURL string) (interface{}, error) {
	opaque := strings.TrimPrefix(rawURL, "merge:")
	// split by |
	parts := strings.Split(opaque, "|")
	var maps []map[string]interface{}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		// each part as datasource url
		// If part matches defined alias? merge examples use file names, not alias... If alias exists, use it?
