			// treat as URL / file
			tmpDS := &Datasource{Alias: part, URL: part, Header: make(http.Header)}
			parsed, err = r.readParsedForDS(tmpDS, "")
		}
		if err != nil {
			// Wrap according to original merge error format:
			// couldn't read datasource 'x' (merge:...): open (url: "merge:///", name: "config.json|missing"): open config.json|missing: opening merge part "missing": open tmp/t2/missing: no such file or directory
			// inner extraction difficult. Construct approximate:
			// Try extract inner path error from err: we need file path stripped
			// For missing file part, our readParsedForDS error is wrapped "couldn't read datasource 'missing' (...): open ...: open tmp/..."
			// We simplify to replicate first level:
			msg := err.Error()
			// attempt to find last "open <path>:"
			// Build inner: opening merge part "<part>": <last inner error segment>
			// Find colon segments - use msg after last "): "
			innerPart := msg
			if idx := strings.LastIndex(msg, "open "); idx >= 0 {
				// need full path error: from that open onwards that's the PathError (open tmp/...)
				innerPart = msg[idx:]
				// innerPart like "open tmp/t2/missing: no such file or directory"
			}
			return nil, fmt.Errorf("couldn't read datasource '%s' (%s): open (url: %q, name: %q): open %s: opening merge part %q: %s", ds.Alias, ds.URL, "merge:///", opaque, opaque, part, innerPart)
		}
		mp, err := toMap(parsed)
		if err != nil {
			// if parsed is not map, maybe skip? If array etc merge fails?
			return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %v", ds.Alias, ds.URL, err)
		}
		maps = append(maps, mp)
	}
	merged := MergeMapsFirstWins(maps)
	return merged, nil
}

func (r *Registry) Reachable(alias string) bool {
	_, err := r.ReadParsed(alias, "")
	return err == nil
}
