func mimeByName(name string) string {
	if name == "" || name == "." {
		return "text/plain"
	}
	ext := path.Ext(name)
	if ext == "" {
		ext = filepath.Ext(name)
	}
	switch strings.ToLower(ext) {
	case ".json":
		return "application/json"
	case ".yaml", ".yml":
		return "application/yaml"
	case ".toml":
		return "application/toml"
	case ".csv":
		return "text/csv"
	case ".txt", ".text":
		return "text/plain"
	case ".xml":
		return "application/xml"
	case ".html", ".htm":
		return "text/html"
	}
	mt := mime.TypeByExtension(ext)
	if mt == "" {
		return "text/plain"
	}
	return mt
