	mt := typeOverride
	if mt == "" { mt = mimeByName(key); if mt == "text/plain" {
		// consul values often JSON if parses? original determines by key extension
	} }
	return b, mt, nil, false, nil
}

func (r *Registry) readGCPMetaDS(ds *Datasource, u *url.URL, subpath string, typeOverride string) ([]byte, string, interface{}, bool, error) {
	endpoint := os.Getenv("GCP_META_ENDPOINT")
	if endpoint == "" { endpoint = "http://metadata.google.internal" }
	p := u.Path
	if subpath != "" { p = p + "/" + strings.Trim(subpath, "/") }
	full := strings.TrimSuffix(endpoint, "/") + "/computeMetadata/v1" + p
	client := &http.Client{Timeout: 2 * time.Second}
	req, _ := http.NewRequest("GET", full, nil)
	req.Header.Set("Metadata-Flavor", "Google")
