	b, _ := io.ReadAll(resp.Body)
	if resp.StatusCode >= 400 { return nil, "", nil, false, r.wrapErr(ds, ds.URL, "stat", "gcp+meta:///", strings.Trim(p, "/"), fmt.Errorf("http failed with status %d", resp.StatusCode)) }
	mt := typeOverride
	if mt == "" { mt = "text/plain" }
	return b, mt, nil, false, nil
}

func (r *Registry) tryVault(ds *Datasource, u *url.URL, subpath string, typeOverride string) ([]byte, string, interface{}, bool, error) {
	addr := os.Getenv("VAULT_ADDR")
	token := os.Getenv("VAULT_TOKEN")
	if addr == "" || token == "" { return nil, "", nil, false, fmt.Errorf("no vault") }
	key := strings.Trim(u.Path, "/")
	if subpath != "" { key = strings.Trim(subpath, "/") }
	// mount is first component?
	full := strings.TrimSuffix(addr, "/") + "/v1/" + key
	client := &http.Client{Timeout: 5 * time.Second}
	req, _ := http.NewRequest("GET", full, nil)
	req.Header.Set("X-Vault-Token", token)
	resp, err := client.Do(req)
	if err != nil { return nil, "", nil, false, err }
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	if resp.StatusCode >= 400 { return nil, "", nil, false, fmt.Errorf("vault status %d", resp.StatusCode) }
	// vault JSON {data:{data:{...}}} etc - parse via ParseData json and unwrap?
	parsed, err := ParseData(b, "application/json")
	if err != nil { return b, "application/json", nil, false, nil }
	if m, ok := parsed.(map[string]interface{}); ok {
		if d, ok := m["data"].(map[string]interface{}); ok {
			if inner, ok := d["data"].(map[string]interface{}); ok { return nil, "", inner, true, nil }
			return nil, "", d, true, nil
		}
	}
	_ = json.Marshal
	return b, "application/json", nil, false, nil
}
