	searchFrom := 0
	if schemeIdx >= 0 { searchFrom = schemeIdx + 3 }
	if idx := strings.Index(rest[searchFrom:], "//"); idx >= 0 {
		pos := searchFrom + idx
		repoURL = rest[:pos]
		innerPath = rest[pos+2:]
