func pkcs7Pad(data []byte, blockSize int) []byte {
	padding := blockSize - len(data)%blockSize
	padtext := make([]byte, padding)
	for i := range padtext { padtext[i] = byte(padding) }
	return append(data, padtext...)
}
func pkcs7Unpad(data []byte) ([]byte, error) {
	if len(data)==0 { return data, nil }
	padding := int(data[len(data)-1])
	if padding==0 || padding>16 || padding>len(data) { return nil, fmt.Errorf("invalid padding") }
	for i:=0;i<padding;i++ {
		if data[len(data)-1-i] != byte(padding) { return nil, fmt.Errorf("invalid padding") }
	}
	return data[:len(data)-padding], nil
}

