func prefixToBig(p netip.Prefix) (*big.Int, int) {
	addr := p.Addr()
	if addr.Is4() {
		b := addr.As4()
		n := new(big.Int).SetBytes(b[:])
		return n, 32
	}
	b := addr.As16()
	return new(big.Int).SetBytes(b[:]), 128
}
func bigToIP(n *big.Int, total int, is4 bool) netip.Addr {
	if is4 {
		var b [4]byte
		bs := n.Bytes()
		// pad to 4
		tmp := make([]byte,4)
		copy(tmp[4-len(bs):], bs)
		copy(b[:], tmp)
		return netip.AddrFrom4(b)
	}
	var b [16]byte
	bs := n.Bytes()
	tmp := make([]byte,16)
	copy(tmp[16-len(bs):], bs)
	copy(b[:], tmp)
	return netip.AddrFrom16(b)
}

func cidrHost(prefix netip.Prefix, hostnum int64) (netip.Addr, error) {
	masked := prefix.Masked()
	base, total := prefixToBig(masked)
	hostBits := total - masked.Bits()
	if hostnum < 0 {
		// Terraform: negative counts from end? hostnum -1 is last address? Support: add 2^hostBits + hostnum
		max := new(big.Int).Lsh(big.NewInt(1), uint(hostBits))
		n := new(big.Int).Add(base, max)
		n.Add(n, big.NewInt(hostnum))
		return bigToIP(n, total, masked.Addr().Is4()), nil
	}
	// check hostnum fits in hostBits
	if hostBits < 63 {
		max := int64(1) << uint(hostBits)
		if hostnum >= max {
			// original terraform errors? Return as computed anyway?
			_ = max
		}
	}
	n := new(big.Int).Add(base, big.NewInt(hostnum))
	return bigToIP(n, total, masked.Addr().Is4()), nil
}

func cidrNetmask(prefix netip.Prefix) (netip.Addr, error) {
	total := 32
	if !prefix.Addr().Is4() { total = 128 }
	bits := prefix.Bits()
	mask := new(big.Int)
	if bits==0 {
		mask.SetInt64(0)
	} else {
		mask.Lsh(big.NewInt(1), uint(total))
		mask.Sub(mask, big.NewInt(1))
		mask.Rsh(mask, uint(total-bits)) // not correct - compute: ((1<<total)-1) << (total-bits) masked to total bits
		// recompute properly:
		all := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), uint(total)), big.NewInt(1))
		m := new(big.Int).Lsh(all, uint(total-bits))
		m.And(m, all)
		mask = m
		_ = mask
		return bigToIP(m, total, prefix.Addr().Is4()), nil
	}
	return bigToIP(mask, total, prefix.Addr().Is4()), nil
}

func cidrSubnets(prefix netip.Prefix, newbits int) ([]netip.Prefix, error) {
	if newbits < 0 { return nil, fmt.Errorf("CIDRSubnets: newbits must be positive") }
	count := 1 << uint(newbits)
	newPrefixLen := prefix.Bits() + newbits
	basePrefix := prefix.Masked()
	base, total := prefixToBig(basePrefix)
	_ = total
	// each subnet size = 2^(total - newPrefixLen)
	hostBits := total - newPrefixLen
	size := new(big.Int).Lsh(big.NewInt(1), uint(hostBits))
	out := make([]netip.Prefix, 0, count)
	for i:=0;i<count;i++ {
		offset := new(big.Int).Mul(size, big.NewInt(int64(i)))
		addrInt := new(big.Int).Add(base, offset)
		addr := bigToIP(addrInt, total, basePrefix.Addr().Is4())
		out = append(out, netip.PrefixFrom(addr, newPrefixLen))
	}
	return out, nil
}

func cidrSubnetSizes(prefix netip.Prefix, newbits []int) ([]netip.Prefix, error) {
	basePrefix := prefix.Masked()
	base, total := prefixToBig(basePrefix)
	cur := new(big.Int).Set(base)
	var out []netip.Prefix
	for _, nb := range newbits {
		newLen := basePrefix.Bits() + nb
		if newLen > total { return nil, fmt.Errorf("CIDRSubnetSizes: prefix too long") }
		hostBits := total - newLen
		size := new(big.Int).Lsh(big.NewInt(1), uint(hostBits))
		// align cur up to size boundary if needed (Terraform does: next subnet starts after previous, aligned?)
		// Check remainder
		rem := new(big.Int).Mod(new(big.Int).Set(cur), size)
		if rem.Sign()!=0 {
			cur.Add(cur, new(big.Int).Sub(size, rem))
		}
		addr := bigToIP(new(big.Int).Set(cur), total, basePrefix.Addr().Is4())
		out = append(out, netip.PrefixFrom(addr, newLen))
		cur.Add(cur, size)
	}
	return out, nil
}
