	"sort"
	"strconv"
	"strings"

	"local/gomplate/sockaddrpkg"
)

func getAllIfAddrs() (sockaddrpkg.IfAddrs, error) {
	ifaces, err := gonet.Interfaces()
	if err != nil {
		return nil, err
	}
	var out sockaddrpkg.IfAddrs
	for _, iface := range ifaces {
		addrs, err := iface.Addrs()
		if err != nil {
			continue
		}
		for _, a := range addrs {
			if ipnet, ok := a.(*gonet.IPNet); ok {
				if ipnet.IP.To4() != nil {
					out = append(out, sockaddrpkg.IfAddr{
						SockAddr:  sockaddrpkg.IPv4Addr{Address: ipv4ToUint(ipnet.IP), Mask: mask4ToUint(ipnet.Mask)},
						Interface: iface,
					})
				} else {
					out = append(out, sockaddrpkg.IfAddr{
						SockAddr:  sockaddrpkg.IPv6Addr{Address: sockaddrpkg.IPv6Address(ipv6ToBigLocal(ipnet.IP)), Mask: sockaddrpkg.IPv6Mask(ipv6MaskBigLocal(ipnet.Mask))},
						Interface: iface,
					})
				}
			}
		}
	}
	if out == nil {
		out = sockaddrpkg.IfAddrs{}
	}
	return out, nil
}

func ipv4ToUint(ip gonet.IP) uint32 {
	ip4 := ip.To4()
	if ip4 == nil { return 0 }
	return uint32(ip4[0])<<24 | uint32(ip4[1])<<16 | uint32(ip4[2])<<8 | uint32(ip4[3])
}
func uintToIPv4(v uint32) gonet.IP {
	return gonet.IPv4(byte(v>>24), byte(v>>16), byte(v>>8), byte(v))
}
func mask4ToUint(m gonet.IPMask) uint32 {
	if len(m) == 4 {
		return uint32(m[0])<<24 | uint32(m[1])<<16 | uint32(m[2])<<8 | uint32(m[3])
	}
	ones, _ := m.Size()
	if ones == 0 { return 0 }
	if ones == 32 { return ^uint32(0) }
	return ^uint32(0) << (32 - ones)
}
func ipv6ToBigLocal(ip gonet.IP) *big.Int {
	ip16 := ip.To16()
	if ip16 == nil { ip16 = ip }
	return new(big.Int).SetBytes([]byte(ip16))
}
func ipv6MaskBigLocal(mask gonet.IPMask) *big.Int {
	ones, bits := mask.Size()
	if bits == 0 { return big.NewInt(0) }
	// bits may be 128
	if ones == 0 { return big.NewInt(0) }
	all := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 128), big.NewInt(1))
	m := new(big.Int).Lsh(all, uint(128-ones))
	m.And(m, all)
	return m
}

func ifAddrIP(ifa sockaddrpkg.IfAddr) gonet.IP {
	switch s := ifa.SockAddr.(type) {
	case sockaddrpkg.IPv4Addr:
		return uintToIPv4(s.Address)
	case sockaddrpkg.IPv6Addr:
		if s.Address == nil { return nil }
		bs := make([]byte, 16)
		bb := (*big.Int)(s.Address).Bytes()
		copy(bs[16-len(bb):], bb)
		return gonet.IP(bs)
	}
	return nil
}
func ifAddrMaskOnes(ifa sockaddrpkg.IfAddr) int {
	switch s := ifa.SockAddr.(type) {
	case sockaddrpkg.IPv4Addr:
		ones := 0
		m := s.Mask
		for i := 0; i < 32; i++ {
			if (m>>uint(31-i))&1 == 1 { ones++ } else { break }
		}
		return ones
	case sockaddrpkg.IPv6Addr:
		if s.Mask == nil { return 0 }
		// count ones in 128 bit mask
		n := (*big.Int)(s.Mask)
		ones := 0
		for i := 127; i >= 0; i-- {
			if n.Bit(i) == 1 { ones++ } else { break }
		}
		return ones
	}
	return 0
}

func ifAddrAttr(ifa sockaddrpkg.IfAddr, selector string) (string, error) {
	ip := ifAddrIP(ifa)
	switch selector {
	case "address":
		if ip != nil { return ip.String(), nil }
		return ifa.SockAddr.String(), nil
	case "name":
		return ifa.Interface.Name, nil
	case "type":
		if ip != nil && ip.To4() != nil { return "IPv4", nil }
		if ip != nil { return "IPv6", nil }
		return "Unix", nil
	case "network":
		if ip != nil {
			ones := ifAddrMaskOnes(ifa)
			var mask gonet.IPMask
			if ip.To4() != nil { mask = gonet.CIDRMask(ones, 32) } else { mask = gonet.CIDRMask(ones, 128) }
			if mask != nil { return ip.Mask(mask).String(), nil }
		}
		return "", nil
	case "netmask":
		if ip != nil {
			ones := ifAddrMaskOnes(ifa)
			if ip.To4() != nil { return gonet.IP(gonet.CIDRMask(ones, 32)).String(), nil }
			return gonet.IP(gonet.CIDRMask(ones, 128)).String(), nil
		}
		return "", nil
	case "broadcast":
		if s, ok := ifa.SockAddr.(sockaddrpkg.IPv4Addr); ok {
			b := s.Address | ^s.Mask
			return uintToIPv4(b).String(), nil
		}
		if ip != nil { return ip.String(), nil }
		return "", nil
	case "port":
		switch s := ifa.SockAddr.(type) {
		case sockaddrpkg.IPv4Addr: return strconv.Itoa(int(s.Port)), nil
		case sockaddrpkg.IPv6Addr: return strconv.Itoa(int(s.Port)), nil
		}
		return "0", nil
	case "size":
		ones := ifAddrMaskOnes(ifa)
		total := 32
		if ip != nil && ip.To4() == nil { total = 128 }
		size := 1
		// compute 2^(total-ones) maybe overflow for v6 - return as big string?
		if total-ones >= 63 { return new(big.Int).Lsh(big.NewInt(1), uint(total-ones)).String(), nil }
		return strconv.Itoa(1 << uint(total-ones)), nil
	case "flags":
		return ifaceFlagsString(ifa.Interface.Flags), nil
	default:
		return "", fmt.Errorf("unsupported attribute name %q", selector)
	}
}

func ifaceFlagsString(fl gonet.Flags) string {
	// net.Interface Flags String() already returns like "up|loopback|running"
	return fl.String()
}

func toIfAddrs(v interface{}) (sockaddrpkg.IfAddrs, error) {
	if addrs, ok := v.(sockaddrpkg.IfAddrs); ok { return addrs, nil }
	// slice of IfAddr
	slice, err := toSlice(v)
	if err != nil { return nil, err }
	out := sockaddrpkg.IfAddrs{}
	for _, el := range slice {
		if ifa, ok := el.(sockaddrpkg.IfAddr); ok { out = append(out, ifa) }
	}
	return out, nil
}

func isPrivateIP(ip gonet.IP) bool {
	if ip == nil { return false }
	if ip4 := ip.To4(); ip4 != nil {
		// RFC1918 + loopback/linklocal etc RFC6890 includes many; for forwardable private check we caller filters loopback
		return ip4[0] == 10 || (ip4[0] == 172 && ip4[1] >= 16 && ip4[1] <= 31) || (ip4[0] == 192 && ip4[1] == 168) || ip4[0] == 127 || (ip4[0] == 169 && ip4[1] == 254) || ip4[0] == 100 && (ip4[1] >= 64 && ip4[1] <= 127)
	}
	// IPv6 unique local fc00::/8 etc, link local
	return ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || (len(ip) == 16 && (ip[0]&0xfe == 0xfc))
}
func isForwardable(ip gonet.IP) bool {
	if ip == nil { return false }
	if ip.IsLoopback() || ip.IsMulticast() || ip.IsUnspecified() || ip.IsLinkLocalMulticast() || ip.IsLinkLocalUnicast() { return false }
	return true
}

// SockaddrFuncs

func (f *SockaddrFuncs) GetAllInterfaces() (sockaddrpkg.IfAddrs, error) { return getAllIfAddrs() }

func (f *SockaddrFuncs) GetDefaultInterfaces() (sockaddrpkg.IfAddrs, error) {
	// mimic go-sockaddr: runs /sbin/ip
	out, err := exec.Command("/sbin/ip", "route", "show", "default").Output()
	if err != nil { return nil, err }
	// parse dev name
	fields := strings.Fields(string(out))
	var dev string
	for i, fld := range fields {
		if fld == "dev" && i+1 < len(fields) { dev = fields[i+1]; break }
	}
	all, err := getAllIfAddrs()
	if err != nil { return nil, err }
	var res sockaddrpkg.IfAddrs
	for _, a := range all { if a.Interface.Name == dev { res = append(res, a) } }
	if res == nil { res = sockaddrpkg.IfAddrs{} }
	return res, nil
}

func (f *SockaddrFuncs) GetPrivateInterfaces() (sockaddrpkg.IfAddrs, error) {
	all, err := getAllIfAddrs(); if err != nil { return nil, err }
	// original also requires default route; if can't determine default, returns [] (not error)
	defaults, derr := f.GetDefaultInterfaces()
	if derr != nil { return sockaddrpkg.IfAddrs{}, nil }
	var out sockaddrpkg.IfAddrs
	for _, a := range defaults {
		ip := ifAddrIP(a)
		_ = all
		if isPrivateIP(ip) && isForwardable(ip) { out = append(out, a) }
	}
	// If default list empty but all? docs: private interfaces has default route; keep defaults filtering
	if out == nil { out = sockaddrpkg.IfAddrs{} }
	return out, nil
}
func (f *SockaddrFuncs) GetPublicInterfaces() (sockaddrpkg.IfAddrs, error) {
	defaults, derr := f.GetDefaultInterfaces()
	if derr != nil { return sockaddrpkg.IfAddrs{}, nil }
	var out sockaddrpkg.IfAddrs
	for _, a := range defaults {
		ip := ifAddrIP(a)
		if !isPrivateIP(ip) && isForwardable(ip) && !ip.IsLoopback() { out = append(out, a) }
	}
	if out == nil { out = sockaddrpkg.IfAddrs{} }
	return out, nil
}

func (f *SockaddrFuncs) Sort(selector string, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	clauses := strings.Split(selector, ",")
	// stable sort applying clauses reverse?
	sortFn := func(list sockaddrpkg.IfAddrs) {
		sort.SliceStable(list, func(i, j int) bool {
			for _, cl := range clauses {
				desc := false
				sel := cl
				if strings.HasPrefix(sel, "-") { desc = true; sel = sel[1:] } else if strings.HasPrefix(sel, "+") { sel = sel[1:] }
				cmp := compareIfAddr(list[i], list[j], sel)
				if cmp != 0 {
					if desc { return cmp > 0 }
					return cmp < 0
				}
			}
			return false
		})
	}
	sortFn(list)
	return list, nil
}
func compareIfAddr(a, b sockaddrpkg.IfAddr, sel string) int {
	switch sel {
	case "address":
		ai := ""; if ip:=ifAddrIP(a); ip!=nil { ai=ip.String() }
		bi := ""; if ip:=ifAddrIP(b); ip!=nil { bi=ip.String() }
		// compare numerically for IPv4?
		av := ipv4StrToUint(ai); bv := ipv4StrToUint(bi)
		if av!=0 || bv!=0 { if av < bv {return -1}; if av > bv {return 1}; return 0 }
		if ai < bi { return -1 }; if ai > bi { return 1 }; return 0
	case "name":
		if a.Interface.Name < b.Interface.Name { return -1 }; if a.Interface.Name > b.Interface.Name { return 1 }; return 0
	case "size":
		as:=ifAddrMaskOnes(a); bs:=ifAddrMaskOnes(b); // smaller mask (larger host?) docs: size sorts smaller mask (?), /24 before /32 means ones ascending
		if as < bs { return -1 }; if as > bs { return 1 }; return 0
	case "type":
		at:=ifAddrAttrMust(a,"type"); bt:=ifAddrAttrMust(b,"type")
		order:=map[string]int{"Unix":0,"IPv4":1,"IPv6":2}
		if order[at] < order[bt] {return -1}; if order[at] > order[bt] {return 1}; return 0
	case "port":
		ap,_:=ifAddrAttr(a,"port"); bp,_:=ifAddrAttr(b,"port"); ai,_:=strconv.Atoi(ap); bi,_:=strconv.Atoi(bp); if ai<bi {return -1}; if ai>bi {return 1}; return 0
	case "default":
		return 0
	}
	return 0
}
func ifAddrAttrMust(a sockaddrpkg.IfAddr, sel string) string { s,_:=ifAddrAttr(a,sel); return s }
func ipv4StrToUint(s string) uint32 { ip:=gonet.ParseIP(s); if ip==nil || ip.To4()==nil {return 0}; return ipv4ToUint(ip) }

func matchesSelector(ifa sockaddrpkg.IfAddr, selector, value string) bool {
	ip := ifAddrIP(ifa)
	switch strings.ToLower(selector) {
	case "type":
		t := strings.ToLower(ifAddrAttrMust(ifa, "type"))
		return t == strings.ToLower(value)
	case "name":
		return ifa.Interface.Name == value
	case "address":
		return ip != nil && ip.String() == value
	case "network":
		_, ipnet, err := gonet.ParseCIDR(value)
		if err != nil { // value may be IP/mask like 192.168.0.0/24 - same
			return false
		}
		return ipnet.Contains(ip)
	case "size":
		return strconv.Itoa(ifAddrMaskOnes(ifa)) == value
	case "port":
		return ifAddrAttrMust(ifa, "port") == value
	case "flag":
		// check flags string contains or special flags
		v := strings.ToLower(value)
		flags := strings.ToLower(ifaceFlagsString(ifa.Interface.Flags))
		if strings.Contains(flags, v) { return true }
		switch v {
		case "loopback": return ip != nil && ip.IsLoopback()
		case "multicast": return ip != nil && ip.IsMulticast()
		case "forwardable": return isForwardable(ip)
		case "global unicast": return ip != nil && ip.IsGlobalUnicast()
		case "link-local unicast": return ip != nil && ip.IsLinkLocalUnicast()
		case "link-local multicast": return ip != nil && ip.IsLinkLocalMulticast()
		case "interface-local multicast": return ip != nil && ip.IsInterfaceLocalMulticast()
		case "unspecified": return ip != nil && ip.IsUnspecified()
		case "up": return ifa.Interface.Flags&gonet.FlagUp != 0
		case "down": return ifa.Interface.Flags&gonet.FlagUp == 0
		case "broadcast": return ifa.Interface.Flags&gonet.FlagBroadcast != 0
		case "point-to-point": return ifa.Interface.Flags&gonet.FlagPointToPoint != 0
		}
		return false
	case "rfc":
		switch value {
		case "1918", "6890":
			return isPrivateIP(ip)
		case "6598":
			return ip != nil && ip.To4() != nil && ip.To4()[0]==100
		default:
			return isPrivateIP(ip)
		}
	}
	return false
}

func (f *SockaddrFuncs) Exclude(selector, value string, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	out := sockaddrpkg.IfAddrs{}
	for _, a := range list { if !matchesSelector(a, selector, value) { out=append(out,a) } }
	return out, nil
}
func (f *SockaddrFuncs) Include(selector, value string, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	out := sockaddrpkg.IfAddrs{}
	for _, a := range list { if matchesSelector(a, selector, value) { out=append(out,a) } }
	return out, nil
}
func (f *SockaddrFuncs) Attr(selector string, addrs interface{}) (string, error) {
	list, err := toIfAddrs(addrs); if err != nil { return "", err }
	// also if single IfAddr passed via range dot: argument is IfAddr not slice
	if ifa, ok := addrs.(sockaddrpkg.IfAddr); ok { return ifAddrAttr(ifa, selector) }
	if len(list)==0 {
		// validate selector first (original returns error for unsupported even if empty?)
		// attempt check
		if _, err := ifAddrAttr(sockaddrpkg.IfAddr{}, selector); err != nil { return "", err }
		return "", nil
	}
	return ifAddrAttr(list[0], selector)
}
func (f *SockaddrFuncs) Join(selector, separator string, addrs interface{}) (string, error) {
	list, err := toIfAddrs(addrs); if err != nil { return "", err }
	if ifa, ok := addrs.(sockaddrpkg.IfAddr); ok { s,_:=ifAddrAttr(ifa, selector); return s, nil }
	var parts []string
	for _, a := range list { s, err:=ifAddrAttr(a, selector); if err!=nil {return "",err}; parts=append(parts,s) }
	return strings.Join(parts, separator), nil
}
func (f *SockaddrFuncs) Limit(limit int, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	if limit < 0 { limit = 0 }
	if limit > len(list) { limit = len(list) }
	return list[:limit], nil
}
func (f *SockaddrFuncs) Offset(offset int, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	if offset < 0 { offset = 0 }
	if offset > len(list) { return sockaddrpkg.IfAddrs{}, nil }
	return list[offset:], nil
}
func (f *SockaddrFuncs) Unique(selector string, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	seen := map[string]bool{}
	out := sockaddrpkg.IfAddrs{}
	for _, a := range list {
		v := ifAddrAttrMust(a, selector)
		if !seen[v] { seen[v]=true; out=append(out,a) }
	}
	return out, nil
}
func (f *SockaddrFuncs) Math(selector, operation string, addrs interface{}) (sockaddrpkg.IfAddrs, error) {
	list, err := toIfAddrs(addrs); if err != nil { return nil, err }
	// only support address +N / -N
	if selector != "address" { return sockaddrpkg.IfAddrs{}, nil }
	if len(operation)<1 { return sockaddrpkg.IfAddrs{}, nil }
	// operation like +5
	op := operation[0]
	numStr := operation[1:]
	n, err := strconv.ParseInt(numStr, 10, 64); if err!=nil { return sockaddrpkg.IfAddrs{}, nil }
	if op=='-' { n = -n } else if op!='+' { return sockaddrpkg.IfAddrs{}, nil }
	out := sockaddrpkg.IfAddrs{}
	for _, a := range list {
		ip := ifAddrIP(a)
		if ip==nil { continue }
		if ip.To4()!=nil {
			v := int64(ipv4ToUint(ip)) + n
			newA := a
			orig := a.SockAddr.(sockaddrpkg.IPv4Addr)
			orig.Address = uint32(v)
			newA.SockAddr = orig
			out=append(out,newA)
		} else {
			bigIP := ipv6ToBigLocal(ip)
			bigIP.Add(bigIP, big.NewInt(n))
			newA := a
			orig := a.SockAddr.(sockaddrpkg.IPv6Addr)
			orig.Address = sockaddrpkg.IPv6Address(bigIP)
			newA.SockAddr = orig
			out=append(out,newA)
		}
		// Math in go-sockaddr: it operates and returns only ??? Original example: GetAllInterfaces | Math -> Attr gave 127.0.0.6 (first) so list retained all? we'll keep all transformed
	}
	return out, nil
}

func (f *SockaddrFuncs) GetPrivateIP() (string, error) {
	addrs, err := f.GetPrivateInterfaces(); if err!=nil { return "", nil }
	if len(addrs)==0 { return "", nil }
	return ifAddrAttr(addrs[0], "address")
}
func (f *SockaddrFuncs) GetPrivateIPs() (string, error) {
	all, err := getAllIfAddrs(); if err!=nil { return "", nil }
	var parts []string
	for _, a := range all { ip:=ifAddrIP(a); if isPrivateIP(ip) && isForwardable(ip) { parts=append(parts, ip.String()) } }
	return strings.Join(parts, " "), nil
}
func (f *SockaddrFuncs) GetPublicIP() (string, error) {
	addrs, err := f.GetPublicInterfaces(); if err!=nil { return "", nil }
	if len(addrs)==0 { return "", nil }
	return ifAddrAttr(addrs[0], "address")
}
func (f *SockaddrFuncs) GetPublicIPs() (string, error) {
	all, err := getAllIfAddrs(); if err!=nil { return "", nil }
	var parts []string
	for _, a := range all { ip:=ifAddrIP(a); if !isPrivateIP(ip) && isForwardable(ip) && ip!=nil && !ip.IsLoopback() { parts=append(parts, ip.String()) } }
	return strings.Join(parts, " "), nil
}
func (f *SockaddrFuncs) GetInterfaceIP(name string) (string, error) {
	ips, err := f.GetInterfaceIPs(name); if err!=nil { return "", err }
	_ = ips
	// original returns empty for lo; maybe it filters forwardable & size sorting: take list of interfaces IPs filtered forwardable, sorted by size (mask ones ascending), first.
	all, err := getAllIfAddrs(); if err!=nil { return "", nil }
	var cands []sockaddrpkg.IfAddr
	for _, a := range all { if a.Interface.Name==name { ip:=ifAddrIP(a); if isForwardable(ip) { cands=append(cands,a) } } }
	if len(cands)==0 { return "", nil }
	sort.SliceStable(cands, func(i,j int) bool { return ifAddrMaskOnes(cands[i]) < ifAddrMaskOnes(cands[j]) })
	return ifAddrAttr(cands[0], "address")
}
func (f *SockaddrFuncs) GetInterfaceIPs(name string) (string, error) {
	all, err := getAllIfAddrs(); if err!=nil { return "", nil }
	var parts []string
	for _, a := range all { if a.Interface.Name==name { ip:=ifAddrIP(a); if ip!=nil { parts=append(parts, ip.String()) } } }
	return strings.Join(parts, " "), nil
}
