func (f *SockaddrFuncs) GetInterfaceIP(name string) (string, error) {
	ips, err := f.GetInterfaceIPs(name); if err!=nil { return "", err }
	_ = ips
	// original returns empty for lo; maybe it filters forwardable & size sorting: take list of interfaces IPs filtered forwardable, sorted by size (mask ones ascending), first.
	all, err := getAllIfAddrs(); if err!=nil { return "", nil }
	var cands []sockaddrpkg.IfAddr
	for _, a := range all { if a.Interface.Name==name { ip:=ifAddrIP(a); if isForwardable(ip) { cands=append(cands,a) } } }
