func (v *SemverVersion) String() string {
	var sb strings.Builder
	sb.WriteString(strconv.FormatUint(v.MajorVal,10)); sb.WriteString(".")
	sb.WriteString(strconv.FormatUint(v.MinorVal,10)); sb.WriteString(".")
