func (v *SemverVersion) Major() uint64 { return v.MajorVal } // template field .Major might be method or field? In Masterminds, Major is a method ? Docs example (semver.Semver "v1.1.1").Major yields 1 . If we name field MajorVal, .Major will invoke method Major() . Good.
func (v *SemverVersion) Minor() uint64 { return v.MinorVal }
func (v *SemverVersion) Patch() uint64 { return v.PatchVal }
func (v *SemverVersion) Prerelease() string { return v.Pre }
func (v *SemverVersion) Metadata() string { return v.Meta }
func (v *SemverVersion) Original() string { return v.Orig }
func (v *SemverVersion) SetPrerelease(pre string) (*SemverVersion, error) {
