func (v *SemverVersion) SetMetadata(meta string) (*SemverVersion, error) {
	nv := *v; nv.Meta = meta; return &nv, nil
}
func (v *SemverVersion) IncMajor() (*SemverVersion, error) { nv:=*v; nv.MajorVal++; nv.MinorVal=0; nv.PatchVal=0; nv.Pre=""; return &nv, nil }
func (v *SemverVersion) IncMinor() (*SemverVersion, error) { nv:=*v; nv.MinorVal++; nv.PatchVal=0; nv.Pre=""; return &nv, nil }
func (v *SemverVersion) IncPatch() (*SemverVersion, error) { nv:=*v; nv.PatchVal++; nv.Pre=""; return &nv, nil }

func parseSemver(s string) (*SemverVersion, error) {
	orig := s
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "v")
	s = strings.TrimPrefix(s, "V")
	// metadata
	meta := ""
	if idx:=strings.Index(s, "+"); idx>=0 { meta=s[idx+1:]; s=s[:idx] }
	pre := ""
	if idx:=strings.Index(s, "-"); idx>=0 { pre=s[idx+1:]; s=s[:idx] }
	parts := strings.Split(s, ".")
	if len(parts)>3 { return nil, fmt.Errorf("Invalid character(s) found in major number") } // approximation
	for len(parts)<3 { parts=append(parts,"0") }
	var nums [3]uint64
	for i, p := range parts {
		if p=="" { return nil, fmt.Errorf("Invalid semantic version") }
		n, err:=strconv.ParseUint(p,10,64); if err!=nil { return nil, fmt.Errorf("Invalid character(s) found in number %q", p) }
		nums[i]=n
	}
	return &SemverVersion{MajorVal: nums[0], MinorVal: nums[1], PatchVal: nums[2], Pre: pre, Meta: meta, Orig: orig}, nil
}

func (f *SemverFuncs) Semver(input string) (*SemverVersion, error) { return parseSemver(input) }

func (f *SemverFuncs) CheckConstraint(constraint string, input string) (bool, error) {
	v, err:=parseSemver(input); if err!=nil { return false, err }
	return checkConstraint(constraint, v)
}

func checkConstraint(expr string, v *SemverVersion) (bool, error) {
	// split by comma = AND, || = OR
	orParts := strings.Split(expr, "||")
	for _, orPart := range orParts {
		andParts := strings.Split(orPart, ",")
		okAll := true
		for _, part := range andParts {
			part=strings.TrimSpace(part)
			if part=="" { continue }
			ok, err:=checkOneConstraint(part, v)
			if err!=nil { return false, err }
			if !ok { okAll=false; break }
		}
		if okAll { return true, nil }
	}
	return false, nil
}

func checkOneConstraint(part string, v *SemverVersion) (bool, error) {
	// operators: >=, <=, >, <, =, !=, ^, ~, - ranges, x wildcards
	// hyphen range "1.2 - 1.4"
	if strings.Contains(part, " - ") {
		sides:=strings.Split(part," - "); if len(sides)==2 {
			lo, err:=parseSemver(strings.TrimSpace(sides[0])); if err!=nil {return false,err}
			hi, err:=parseSemver(strings.TrimSpace(sides[1])); if err!=nil {return false,err}
			return compareSemver(v, lo) >=0 && compareSemver(v, hi) <=0, nil
		}
	}
	op := ""
	rest := part
	for _, cand := range []string{">=", "<=", "!=", ">", "<", "=", "^", "~"} {
		if strings.HasPrefix(part, cand) { op=cand; rest=strings.TrimSpace(part[len(cand):]); break }
	}
	// wildcard x
	if strings.Contains(rest, "x") || strings.Contains(rest, "*") || strings.Contains(rest, "X") {
		// strip v
		r:=strings.TrimPrefix(rest,"v")
		segs:=strings.Split(r,".")
		// create low version filling x with 0, check major/minor prefix
		// Simplistic: if first seg x => true; if major matches and second x => true etc.
		// Convert to range?
		if segs[0]=="x"||segs[0]=="*"||segs[0]=="X" { return true, nil }
		maj, _:=strconv.ParseUint(segs[0],10,64)
		if v.MajorVal != maj { return false, nil }
		if len(segs)>=2 && !(segs[1]=="x"||segs[1]=="*") {
			min, _:=strconv.ParseUint(segs[1],10,64); if v.MinorVal != min { return false, nil }
		}
		if len(segs)>=3 && !(segs[2]=="x"||segs[2]=="*") {
			pat, _:=strconv.ParseUint(segs[2],10,64); if v.PatchVal != pat { return false, nil }
		}
		return true, nil
	}
	cv, err:=parseSemver(rest); if err!=nil { return false, err }
	cmp:=compareSemver(v, cv)
	switch op {
	case "": // equal or if rest had implicit? Masterminds default =?
		return cmp==0, nil
	case "=": return cmp==0, nil
	case "!=": return cmp!=0, nil
	case ">": return cmp>0, nil
	case "<": return cmp<0, nil
	case ">=": return cmp>=0, nil
	case "<=": return cmp<=0, nil
	case "^":
		// compatible: >= cv and < next major (if major>0) etc.
		if cmp<0 { return false, nil }
		if cv.MajorVal>0 { return v.MajorVal==cv.MajorVal, nil }
		if cv.MinorVal>0 { return v.MajorVal==0 && v.MinorVal==cv.MinorVal, nil }
		return v.MajorVal==0 && v.MinorVal==0 && v.PatchVal==cv.PatchVal, nil
	case "~":
		if cmp<0 { return false, nil }
		return v.MajorVal==cv.MajorVal && v.MinorVal==cv.MinorVal, nil // patch can vary; if minor specified? Masterminds ~1.2 means >=1.2 <1.3 ; ~1 means <2
	}
	return false, nil
}

func compareSemver(a,b *SemverVersion) int {
	if a.MajorVal!=b.MajorVal { if a.MajorVal<b.MajorVal {return -1}; return 1 }
	if a.MinorVal!=b.MinorVal { if a.MinorVal<b.MinorVal {return -1}; return 1 }
	if a.PatchVal!=b.PatchVal { if a.PatchVal<b.PatchVal {return -1}; return 1 }
	// prerelease: empty > non-empty; compare dot segments numeric <
	if a.Pre==b.Pre { return 0 }
	if a.Pre=="" { return 1 }
	if b.Pre=="" { return -1 }
	as:=strings.Split(a.Pre,"."); bs:=strings.Split(b.Pre,".")
	for i:=0;i<len(as) && i<len(bs);i++ {
		if as[i]==bs[i] { continue }
