package semver

import (
	"fmt"
	"strconv"
	"strings"
)

type Version struct {
	MajorVal uint64
	MinorVal uint64
	PatchVal uint64
	Pre      string
	Meta     string
	Orig     string
}

func (v *Version) String() string {
	var sb strings.Builder
	sb.WriteString(strconv.FormatUint(v.MajorVal, 10))
	sb.WriteString(".")
	sb.WriteString(strconv.FormatUint(v.MinorVal, 10))
	sb.WriteString(".")
	sb.WriteString(strconv.FormatUint(v.PatchVal, 10))
	if v.Pre != "" {
		sb.WriteString("-")
		sb.WriteString(v.Pre)
	}
	if v.Meta != "" {
		sb.WriteString("+")
		sb.WriteString(v.Meta)
	}
	return sb.String()
}
func (v *Version) Major() uint64 { return v.MajorVal }
func (v *Version) Minor() uint64 { return v.MinorVal }
func (v *Version) Patch() uint64 { return v.PatchVal }
func (v *Version) Prerelease() string { return v.Pre }
func (v *Version) Metadata() string   { return v.Meta }
func (v *Version) Original() string   { return v.Orig }
func (v *Version) SetPrerelease(pre string) (*Version, error) {
	nv := *v
	nv.Pre = pre
	return &nv, nil
}
func (v *Version) SetMetadata(meta string) (*Version, error) {
	nv := *v
	nv.Meta = meta
	return &nv, nil
}
func (v *Version) IncMajor() (*Version, error) { nv := *v; nv.MajorVal++; nv.MinorVal = 0; nv.PatchVal = 0; nv.Pre = ""; return &nv, nil }
func (v *Version) IncMinor() (*Version, error) { nv := *v; nv.MinorVal++; nv.PatchVal = 0; nv.Pre = ""; return &nv, nil }
func (v *Version) IncPatch() (*Version, error) { nv := *v; nv.PatchVal++; nv.Pre = ""; return &nv, nil }

