		if inQ!=0 { if s[i]==inQ { inQ=0 }; continue }
		if s[i]=='\'' || s[i]=='"' { inQ=s[i]; continue }
		if s[i]=='[' { depth++ }
		if s[i]==']' { depth--; if depth==0 { return i } }
