	// expressions combined with && or ||
	if strings.Contains(filter, "&&") {
		parts:=strings.Split(filter,"&&")
		for _, p:=range parts { if !evalJSONPathFilter(strings.TrimSpace(p), cand) { return false } }
		return true
	}
	if strings.Contains(filter, "||") {
		parts:=strings.Split(filter,"||")
		for _, p:=range parts { if evalJSONPathFilter(strings.TrimSpace(p), cand) { return true } }
		return false
	}
	// find operator
	ops:=[]string{"==","!=",">=", "<=", ">", "<", "=~"}
	for _, op:=range ops {
