package funcs

import (
	"fmt"
	"strconv"
	"strings"
)

// Very small jq subset: supports ., .foo, .foo.bar, .foo[], .[], .[index], pipes |, arrays constructions [ expr, ... ] splitting at pipeline level?, object construction {"k": expr}, select? length, keys, values, map(...), etc.

func jqEval(expr string, in interface{}) (interface{}, error) {
	expr=strings.TrimSpace(expr)
	if expr=="" || expr=="." { return in, nil }
	// Top level: if result multiple items (stream) - our eval returns possibly multiple for [] iteration.
	results, err := jqEvalStream(expr, in)
	if err != nil { return nil, err }
	if len(results)==0 { return nil, nil }
	if len(results)==1 { return results[0], nil }
	return results, nil
}

func jqEvalStream(expr string, in interface{}) ([]interface{}, error) {
	// handle pipe at top level (not inside brackets/braces/parens/strings)
	parts:=splitJQTop(expr, '|')
	if len(parts)>1 {
		cur:=[]interface{}{in}
		for _, part := range parts {
			part=strings.TrimSpace(part)
			var next []interface{}
			for _, v := range cur {
				res, err:=jqEvalStream(part, v)
				if err!=nil { return nil, err }
				next=append(next, res...)
			}
			cur=next
		}
		return cur, nil
	}
	// single expression
	return jqEvalSingle(expr, in)
}

func splitJQTop(expr string, sep rune) []string {
	var parts []string
	depthBrack:=0; depthParen:=0; depthBrace:=0; inStr:=false; esc:=false
	start:=0
	for i, r := range expr {
		if inStr {
			if esc { esc=false; continue }
			if r=='\\' { esc=true; continue }
			if r=='"' { inStr=false }
			continue
		}
		switch r {
		case '"': inStr=true
		case '[': depthBrack++
		case ']': depthBrack--
		case '(': depthParen++
		case ')': depthParen--
		case '{': depthBrace++
		case '}': depthBrace--
		default:
			if r==sep && depthBrack==0 && depthParen==0 && depthBrace==0 {
				parts=append(parts, expr[start:i])
				start=i+len(string(r))
			}
		}
	}
	parts=append(parts, expr[start:])
	// Filter empty caused by sep at edges
	var out []string
	for _, p:=range parts { if strings.TrimSpace(p)!="" { out=append(out,p) } }
		if len(out)==0 { out=parts }
	return out
}

func jqEvalSingle(expr string, in interface{}) ([]interface{}, error) {
	expr=strings.TrimSpace(expr)
	if expr=="." { return []interface{}{in}, nil }
