	case "empty":
		return []interface{}{}, nil
	case "not":
		return []interface{}{!toBoolImpl(in)}, nil
	}
	// comparisons etc: .foo == "x", .foo > 1 etc
	for _, op := range []string{"==","!=",">=","<=",">","<"} {
