func jqType(v interface{}) string {
	if v==nil { return "null" }
	switch v.(type) {
	case string: return "string"
	case bool: return "boolean"
	case map[string]interface{}: return "object"
	default:
		if _, err:=toSlice(v); err==nil { return "array" }
		if isNumValue(v) { return "number" }
		return "object"
	}
}

func sortedKeysAsInterfaces(keys []string) []interface{} { out:=make([]interface{},len(keys)); for i,k:=range keys{out[i]=k}; return out }

func findTopColon(s string) int {
	depthB:=0; depthP:=0; depthBr:=0; inStr:=false; esc:=false
	for i, r:=range s {
		if inStr { if esc{esc=false;continue}; if r=='\\'{esc=true;continue}; if r=='"'{inStr=false}; continue }
