	}
	return -1
}

func jqEvalPath(expr string, in interface{}) ([]interface{}, error) {
	// expr like . , .foo, .foo.bar, .foo[0], .foo[], .[], .foo.bar[]
	// tokenize by . and []
	cur:=[]interface{}{in}
	i:=0
	// expr starts .
	for i < len(expr) {
		if expr[i]=='.' {
			i++
			// name
			start:=i
			for i < len(expr) && (isJSONPathNameChar(expr[i])) { i++ }
