			} else if (strings.HasPrefix(inner,"\"")||strings.HasPrefix(inner,"'")) {
				key:=strings.Trim(inner,"\"'")
				for _, v:=range cur { if m,err:=toMap(v); err==nil { if val,ok:=m[key]; ok{next=append(next,val)} else {next=append(next,nil)} } }
