				idx,_:=strconv.Atoi(inner)
				for _, v:=range cur { if s,err:=toSlice(v); err==nil { if idx<0{idx=len(s)+idx}; if idx>=0 && idx < len(s){ next=append(next,s[idx]) } else { next=append(next,nil) } } }
			}
			cur=next
			continue
		}
		// unknown char maybe operator space - break
		if expr[i]==' ' || expr[i]=='\t' { i++; continue }
		// could be remaining expression like // etc unsupported
		break
	}
	if cur==nil { cur=[]interface{}{} }
	return cur, nil
}
