package funcs

import (
	"fmt"
	"strconv"
	"strings"
)

// JSONPath subset --------------------------------------------------------------------
func (f *CollFuncs) JSONPath(expression string, in interface{}) (interface{}, error) {
	results, err := jsonPathQuery(expression, in)
	if err != nil { return nil, err }
	if len(results) == 0 { return nil, nil }
	if len(results) == 1 {
		// Original: if expression is definite ( $.a ) returns single; if indefinite ($..a) returns slice even if 1? Probe later. Use heuristic: if contains ".." or "[?" or "[*]" or slice range, return slice
		if isIndefiniteJSONPath(expression) { return results, nil }
		return results[0], nil
	}
	return results, nil
}

func isIndefiniteJSONPath(expr string) bool {
	return strings.Contains(expr, "..") || strings.Contains(expr, "[*]") || strings.Contains(expr, "[?") || strings.Contains(expr, ",") || strings.Contains(expr, ":")
}

// parse and query
func jsonPathQuery(expr string, in interface{}) ([]interface{}, error) {
	expr = strings.TrimSpace(expr)
	if !strings.HasPrefix(expr, "$") { return nil, fmt.Errorf("JSONPath: expression must start with $") }
	rest := expr[1:]
	tokens, err := tokenizeJSONPath(rest)
	if err != nil { return nil, err }
	cur := []interface{}{in}
	for _, tok := range tokens {
		var next []interface{}
		switch tok.kind {
		case "child":
			for _, v := range cur {
				if m, err := toMap(v); err == nil && m != nil {
					if val, ok := m[tok.name]; ok { next = append(next, val) }
				}
			}
		case "recursive":
			for _, v := range cur {
				// collect all values for key recursively (including root if matches)
				collectRecursive(v, tok.name, &next)
			}
		case "wildcard":
			for _, v := range cur {
				if m, err := toMap(v); err == nil && m != nil {
					// order: sorted? JSONPath usually map iteration unpredictable - original implementation (PaesslerAG?) sorted? For tests with single map may not matter. Use sorted keys for determinism.
					for _, k := range sortedKeys(m) { next = append(next, m[k]) }
				} else if s, err := toSlice(v); err == nil {
					next = append(next, s...)
				}
			}
		case "index":
			for _, v := range cur {
				if s, err := toSlice(v); err == nil {
					idx := tok.index
					if idx < 0 { idx = len(s) + idx }
					if idx >= 0 && idx < len(s) { next = append(next, s[idx]) }
				} else if m, err := toMap(v); err == nil && m != nil {
					if val, ok := m[strconv.Itoa(tok.index)]; ok { next = append(next, val) }
				}
			}
		case "slice":
			for _, v := range cur {
				if s, err := toSlice(v); err == nil {
					start, end := tok.start, tok.end
					if start < 0 { start = len(s) + start }
					if end < 0 { end = len(s) + end }
					if tok.hasEnd == false { end = len(s) }
					if start < 0 { start = 0 }
					if end > len(s) { end = len(s) }
					if start < end { for _, el := range s[start:end] { next = append(next, el) } }
				}
			}
		case "filter":
			for _, v := range cur {
				candidates := []interface{}{}
				if s, err := toSlice(v); err == nil { candidates = s } else { candidates = []interface{}{v} }
				for _, cand := range candidates {
					if evalJSONPathFilter(tok.filter, cand) { next = append(next, cand) }
				}
			}
		case "script_index_multi":
			// [0,1] etc handled as multiple indices token contains names
			for _, idx := range tok.indices {
				for _, v := range cur {
					if s, err := toSlice(v); err == nil && idx >=0 && idx < len(s) { next=append(next, s[idx]) }
				}
			}
		case "union":
			for _, name := range tok.names {
				for _, v := range cur {
					if m, err := toMap(v); err == nil && m != nil {
						if val, ok := m[name]; ok { next = append(next, val) }
					}
				}
			}
		}
		cur = next
	}
	if cur == nil { cur = []interface{}{} }
	return cur, nil
}

type jpToken struct {
	kind string // child recursive wildcard index slice filter union script...
	name string
	index int
	start, end int
	hasEnd bool
	filter string
	indices []int
	names []string
}

func tokenizeJSONPath(s string) ([]jpToken, error) {
	var toks []jpToken
	i := 0
	for i < len(s) {
		if strings.HasPrefix(s[i:], "..") {
			i += 2
			// next name or * or [
			if i < len(s) && s[i] == '*' {
				toks = append(toks, jpToken{kind:"wildcard"})
				i++
				continue
			}
			if i < len(s) && s[i] == '[' {
				// recursive followed by bracket - treat bracket token as recursive wildcard? Simplified: find ]
				end := strings.Index(s[i:], "]")
				if end<0 { return nil, fmt.Errorf("JSONPath: unterminated bracket") }
				inner := s[i+1:i+end]
				// recursive descent then apply token on all descendants - approximating by wildcard recursive? We'll produce recursive with empty name then bracket? Hard.
				// Instead produce a token recursive with name parsed below?
				_ = inner
				// For $..[0] etc, approximate as wildcard then index
				toks = append(toks, jpToken{kind:"wildcard_recursive"})
				// fallthrough to bracket parsing in next loop? we consumed? Not - set i to bracket start and let bracket handle after adding recursive wildcard expansion step that flattens all descendants
				// Our token kinds don't support. Simplify: add token kind recursive_all
				// Replace last token
				toks[len(toks)-1] = jpToken{kind:"recursive_all"}
				// now parse bracket as separate token in loop iteration (don't advance)
				continue
			}
			// name
			start := i
			for i < len(s) && (isJSONPathNameChar(s[i])) { i++ }
			name := s[start:i]
			toks = append(toks, jpToken{kind:"recursive", name:name})
			continue
		}
		if s[i] == '.' {
			i++
			if i < len(s) && s[i]=='*' { toks=append(toks, jpToken{kind:"wildcard"}); i++; continue }
			start:=i
			for i < len(s) && isJSONPathNameChar(s[i]) { i++ }
			name:=s[start:i]
			if name!="" { toks=append(toks, jpToken{kind:"child", name:name}) }
			continue
		}
		if s[i]=='[' {
			end:=findBracketEnd(s,i)
			if end<0 { return nil, fmt.Errorf("JSONPath: unterminated bracket") }
			inner:=strings.TrimSpace(s[i+1:end])
			i=end+1
			if inner=="*" {
				toks=append(toks, jpToken{kind:"wildcard"}); continue
			}
			if strings.HasPrefix(inner, "?(") || strings.HasPrefix(inner, "?") {
				// filter ?(@.x > 1) or ? @...
				f:=strings.TrimSpace(inner[1:])
				f=strings.Trim(f, "()")
				toks=append(toks, jpToken{kind:"filter", filter:f}); continue
			}
			if strings.HasPrefix(inner, "(") {
				// script expression - unsupported
				return nil, fmt.Errorf("JSONPath: script expressions not supported")
			}
			if strings.Contains(inner, ":") {
				parts:=strings.Split(inner, ":")
				var startv, endv int; var hasEnd bool
				if parts[0]!="" { startv,_=strconv.Atoi(parts[0]) }
				if len(parts)>1 && parts[1]!="" { endv,_=strconv.Atoi(parts[1]); hasEnd=true }
				toks=append(toks, jpToken{kind:"slice", start:startv, end:endv, hasEnd:hasEnd}); continue
			}
			if strings.Contains(inner, ",") {
				parts:=strings.Split(inner, ",")
				var names []string; var indices []int; isIndex:=true
				for _, p := range parts { p=strings.Trim(p, " '\""); if _,err:=strconv.Atoi(p); err!=nil { isIndex=false }; names=append(names,p); if n,err:=strconv.Atoi(p); err==nil { indices=append(indices,n) } }
				if isIndex { toks=append(toks, jpToken{kind:"script_index_multi", indices:indices}) } else { toks=append(toks, jpToken{kind:"union", names:names}) }
				continue
			}
			// quoted name or index
			if (strings.HasPrefix(inner,"'") && strings.HasSuffix(inner,"'")) || (strings.HasPrefix(inner,"\"") && strings.HasSuffix(inner,"\"")) {
				name:=inner[1:len(inner)-1]
				toks=append(toks, jpToken{kind:"child", name:name}); continue
			}
			if n, err:=strconv.Atoi(inner); err==nil { toks=append(toks, jpToken{kind:"index", index:n}); continue }
			// bare name in brackets
			toks=append(toks, jpToken{kind:"child", name:inner})
			continue
		}
		// unknown char skip
		i++
	}
	// handle recursive_all token kind in query: we need support - transform: it means flatten all descendants into list then next token applies. Implement in query by special case: if token kind recursive_all, collect all nodes recursively.
	for idx, tok := range toks {
		if tok.kind=="recursive_all" {
			toks[idx].kind="recursive_all_token"
		}
	}
	return toks, nil
}

func isJSONPathNameChar(c byte) bool {
	return c=='_' || c=='$' || (c>='a'&&c<='z') || (c>='A'&&c<='Z') || (c>='0'&&c<='9') || c=='-'
}
func findBracketEnd(s string, start int) int {
	depth:=0; inQ:=byte(0)
	for i:=start;i<len(s);i++ {
		if inQ!=0 { if s[i]==inQ { inQ=0 }; continue }
		if s[i]=='\'' || s[i]=='"' { inQ=s[i]; continue }
		if s[i]=='[' { depth++ }
		if s[i]==']' { depth--; if depth==0 { return i } }
	}
	return -1
}

func collectRecursive(v interface{}, name string, out *[]interface{}) {
	if m, err:=toMap(v); err==nil && m!=nil {
		if val, ok:=m[name]; ok { *out=append(*out, val) }
		for _, k:=range sortedKeys(m) { collectRecursive(m[k], name, out) }
		return
	}
	if s, err:=toSlice(v); err==nil {
		for _, el:=range s { collectRecursive(el, name, out) }
	}
}
func collectAll(v interface{}, out *[]interface{}) {
	*out=append(*out, v)
	if m, err:=toMap(v); err==nil && m!=nil {
		for _, k:=range sortedKeys(m) { collectAll(m[k], out) }
		return
	}
	if s, err:=toSlice(v); err==nil {
		for _, el:=range s { collectAll(el, out) }
	}
}

// filter evaluation: @.field operator value, @ operator value, exists @.field
func evalJSONPathFilter(filter string, cand interface{}) bool {
	filter=strings.TrimSpace(filter)
	// strip surrounding parens already
	// expressions combined with && or ||
	if strings.Contains(filter, "&&") {
		parts:=strings.Split(filter,"&&")
		for _, p:=range parts { if !evalJSONPathFilter(strings.TrimSpace(p), cand) { return false } }
		return true
	}
	if strings.Contains(filter, "||") {
		parts:=strings.Split(filter,"||")
		for _, p:=range parts { if evalJSONPathFilter(strings.TrimSpace(p), cand) { return true } }
		return false
	}
	// find operator
	ops:=[]string{"==","!=",">=", "<=", ">", "<", "=~"}
	for _, op:=range ops {
		if idx:=strings.Index(filter, op); idx>=0 {
			left:=strings.TrimSpace(filter[:idx])
			right:=strings.TrimSpace(filter[idx+len(op):])
			lval:=evalJSONPathFilterOperand(left, cand)
			rval:=parseFilterLiteral(right)
			return compareFilter(lval, rval, op)
		}
	}
	// existence: @.foo
	if strings.HasPrefix(filter,"@") {
		// evaluate path on cand - if result non-empty and not false?
		path:="$"+filter[1:]
		res, err:=jsonPathQuery(path, cand)
		if err!=nil { return false }
		if len(res)==0 { return false }
		if b, ok:=res[0].(bool); ok { return b }
		return true
	}
	return false
}
func evalJSONPathFilterOperand(s string, cand interface{}) interface{} {
	s=strings.TrimSpace(s)
	if strings.HasPrefix(s,"@") {
		path:="$"+s[1:]
		res, err:=jsonPathQuery(path, cand)
		if err!=nil || len(res)==0 { return nil }
		return res[0]
	}
	return parseFilterLiteral(s)
