func parseFilterLiteral(s string) interface{} {
	s=strings.TrimSpace(s)
	if len(s)>=2 && ((s[0]=='"'&&s[len(s)-1]=='"')||(s[0]=='\''&&s[len(s)-1]=='\'')) { return s[1:len(s)-1] }
	if s=="true"{return true}; if s=="false"{return false}; if s=="null"{return nil}
	if n,err:=strconv.ParseFloat(s,64); err==nil {
		if strings.Contains(s,".") { return n }
		if i,err:=strconv.ParseInt(s,10,64); err==nil { return int(i) } // use matching types from parsed JSON (int)
		return n
	}
	return s
}
func compareFilter(l, r interface{}, op string) bool {
	// numeric
	if isNumValue(l) && isNumValue(r) {
		lf,_:=toFloat64(l); rf,_:=toFloat64(r)
		switch op { case "==": return lf==rf; case "!=": return lf!=rf; case ">": return lf>rf; case "<": return lf<rf; case ">=": return lf>=rf; case "<=": return lf<=rf }
	}
