	switch op { case "==": return fmt.Sprintf("%v",l)==fmt.Sprintf("%v",r); case "!=": return fmt.Sprintf("%v",l)!=fmt.Sprintf("%v",r); case ">": return ls>rs; case "<": return ls<rs; case ">=": return ls>=rs; case "<=": return ls<=rs; case "=~": return strings.Contains(ls, rs) }
	return false
}

// JQ subset -------------------------------------------------------------------------------------
func (f *CollFuncs) JQ(expression string, in interface{}) (interface{}, error) {
	return jqEval(expression, in)
