		return []interface{}{out}, nil
	}
	if strings.HasPrefix(expr, "select(") && strings.HasSuffix(expr, ")") {
		inner:=expr[7:len(expr)-1]
		res, err:=jqEvalStream(inner, in); if err!=nil {return nil, err}
		if len(res)>0 && toBoolImpl(res[0]) { return []interface{}{in}, nil }
		return []interface{}{}, nil
	}
	if strings.HasPrefix(expr, "[") && strings.HasSuffix(expr, "]") {
		inner:=strings.TrimSpace(expr[1:len(expr)-1])
		if inner=="" { return []interface{}{[]interface{}{}}, nil }
		parts:=splitJQTop(inner, ',')
		// Note splitJQTop only splits on pipe char param - we passed ',' as rune, it splits on comma at top - ok
		var collected []interface{}
		for _, part:=range parts {
			res, err:=jqEvalStream(strings.TrimSpace(part), in); if err!=nil {return nil, err}
			collected=append(collected, res...)
		}
		return []interface{}{collected}, nil
	}
	if strings.HasPrefix(expr, "{") && strings.HasSuffix(expr, "}") {
		inner:=strings.TrimSpace(expr[1:len(expr)-1])
		if inner=="" { return []interface{}{map[string]interface{}{}}, nil }
		parts:=splitJQTop(inner, ',')
		out:=make(map[string]interface{})
		for _, part:=range parts {
			// key: expr or "key": expr or .key shorthand? jq {"title":.title}
			colon:=findTopColon(part)
			if colon<0 {
				// shorthand .foo or key
				key:=strings.Trim(part, " \"")
				res, err:=jqEvalStream(part, in); if err==nil && len(res)>0 { out[strings.TrimPrefix(key,".")] = res[0] }
				continue
			}
			keyRaw:=strings.TrimSpace(part[:colon])
			key:=strings.Trim(keyRaw, "\"")
			if strings.HasPrefix(keyRaw, "(") { // dynamic key (expr)
				// evaluate key expr
				kexpr:=strings.Trim(keyRaw, "()")
				resk, _:=jqEvalStream(kexpr, in); if len(resk)>0 { key=toString(resk[0]) }
			}
			valExpr:=strings.TrimSpace(part[colon+1:])
			res, err:=jqEvalStream(valExpr, in); if err!=nil {return nil,err}
			if len(res)==1 { out[key]=res[0] } else { out[key]=res }
		}
		return []interface{}{out}, nil
	}
	if strings.HasPrefix(expr, "(") && strings.HasSuffix(expr, ")") {
		return jqEvalStream(expr[1:len(expr)-1], in)
	}
	// field / path expression starting with .
	if strings.HasPrefix(expr, ".") {
		return jqEvalPath(expr, in)
	}
	// Literals
	if len(expr)>=2 && expr[0]=='"' && expr[len(expr)-1]=='"' {
		if s, err:=strconv.Unquote(expr); err==nil { return []interface{}{s}, nil }
		return []interface{}{strings.Trim(expr,"\"")}, nil
	}
	if expr=="true" { return []interface{}{true}, nil }
	if expr=="false" { return []interface{}{false}, nil }
	if expr=="null" { return []interface{}{nil}, nil }
	if n, err:=strconv.ParseFloat(expr,64); err==nil {
		if strings.Contains(expr,".") { return []interface{}{n}, nil }
		if i,err:=strconv.ParseInt(expr,10,64); err==nil { return []interface{}{int(i)}, nil }
		return []interface{}{n}, nil
	}
	// function calls like add, sort, reverse, unique, min, max, flatten, tostring, tonumber, type
	switch expr {
	case "add":
		if slice, err:=toSlice(in); err==nil {
			// numbers or strings
			if len(slice)==0 { return []interface{}{nil}, nil }
			if _, ok:=slice[0].(string); ok { var sb strings.Builder; for _,el:=range slice{sb.WriteString(toString(el))}; return []interface{}{sb.String()}, nil }
			sumF:=0.0; isFloat:=false; for _,el:=range slice{ if isFloatArg(el){isFloat=true}; f,_:=toFloat64(el); sumF+=f }
			if isFloat { return []interface{}{sumF}, nil }
			var sumI int64; for _,el:=range slice{ iv,_:=toInt64(el); sumI+=iv }; return []interface{}{sumI}, nil
		}
	case "sort":
		if slice, err:=toSlice(in); err==nil { out:=append([]interface{}{},slice...); if isSortableList(out,"") { sortSliceStable(out,"") }; return []interface{}{out}, nil }
	case "reverse":
		if slice, err:=toSlice(in); err==nil { out:=make([]interface{},len(slice)); for i,el:=range slice{out[len(slice)-1-i]=el}; return []interface{}{out}, nil }
	case "unique":
		if slice, err:=toSlice(in); err==nil { seen:=map[string]bool{}; var out []interface{}; for _,el:=range slice{ k:=fmt.Sprintf("%#v",el); if !seen[k]{seen[k]=true; out=append(out,el)}}; return []interface{}{out}, nil }
	case "min":
		if slice, err:=toSlice(in); err==nil && len(slice)>0 { best:=slice[0]; for _,el:=range slice[1:]{ if lessValue(el,best){best=el}}; return []interface{}{best}, nil }
	case "max":
		if slice, err:=toSlice(in); err==nil && len(slice)>0 { best:=slice[0]; for _,el:=range slice[1:]{ if lessValue(best,el){best=el}}; return []interface{}{best}, nil }
	case "tostring":
		if s, ok:=in.(string); ok { return []interface{}{s}, nil }
		j,_:=marshalJSON(in); return []interface{}{j}, nil
	case "tonumber":
		if f, err:=toFloat64(in); err==nil { if isFloatArg(in){return []interface{}{f},nil}; iv,_:=toInt64(in); return []interface{}{iv}, nil }
	case "type":
		return []interface{}{jqType(in)}, nil
	case "empty":
		return []interface{}{}, nil
	case "not":
		return []interface{}{!toBoolImpl(in)}, nil
	}
	// comparisons etc: .foo == "x", .foo > 1 etc
	for _, op := range []string{"==","!=",">=","<=",">","<"} {
		if idx:=strings.Index(expr, op); idx>0 {
			left:=strings.TrimSpace(expr[:idx]); right:=strings.TrimSpace(expr[idx+len(op):])
			lres, err:=jqEvalStream(left, in); if err!=nil {return nil,err}
			rres, err:=jqEvalStream(right, in); if err!=nil {return nil,err}
			var lv, rv interface{}; if len(lres)>0{lv=lres[0]}; if len(rres)>0{rv=rres[0]}
			return []interface{}{compareFilter(lv,rv,op)}, nil
		}
	}
	return nil, fmt.Errorf("jq: unknown expression %q", expr)
}

func jqType(v interface{}) string {
	if v==nil { return "null" }
	switch v.(type) {
	case string: return "string"
	case bool: return "boolean"
	case map[string]interface{}: return "object"
	default:
		if _, err:=toSlice(v); err==nil { return "array" }
		if isNumValue(v) { return "number" }
		return "object"
	}
}

func sortedKeysAsInterfaces(keys []string) []interface{} { out:=make([]interface{},len(keys)); for i,k:=range keys{out[i]=k}; return out }

func findTopColon(s string) int {
	depthB:=0; depthP:=0; depthBr:=0; inStr:=false; esc:=false
	for i, r:=range s {
		if inStr { if esc{esc=false;continue}; if r=='\\'{esc=true;continue}; if r=='"'{inStr=false}; continue }
		switch r { case '"': inStr=true; case '[': depthB++; case ']': depthB--; case '(': depthP++; case ')': depthP--; case '{': depthBr++; case '}': depthBr--; case ':': if depthB==0 && depthP==0 && depthBr==0 { return i } }
	}
	return -1
}

func jqEvalPath(expr string, in interface{}) ([]interface{}, error) {
	// expr like . , .foo, .foo.bar, .foo[0], .foo[], .[], .foo.bar[]
	// tokenize by . and []
	cur:=[]interface{}{in}
	i:=0
	// expr starts .
	for i < len(expr) {
		if expr[i]=='.' {
			i++
			// name
			start:=i
			for i < len(expr) && (isJSONPathNameChar(expr[i])) { i++ }
			name:=expr[start:i]
			if name=="" { continue }
			var next []interface{}
			for _, v:=range cur {
				if m, err:=toMap(v); err==nil && m!=nil {
					if val, ok:=m[name]; ok { next=append(next,val) } else { next=append(next,nil) }
				} else {
					next=append(next,nil)
				}
			}
			cur=next
			continue
		}
		if expr[i]=='[' {
			end:=findBracketEnd(expr,i); if end<0 { return nil, fmt.Errorf("jq: unterminated [") }
			inner:=strings.TrimSpace(expr[i+1:end])
			i=end+1
			var next []interface{}
			if inner=="" {
				// iterate
				for _, v:=range cur {
					if s,err:=toSlice(v); err==nil { next=append(next,s...) } else if m,err:=toMap(v); err==nil { for _,k:=range sortedKeys(m){ next=append(next,m[k]) } } else { return nil, fmt.Errorf("jq: cannot iterate") }
				}
			} else if (strings.HasPrefix(inner,"\"")||strings.HasPrefix(inner,"'")) {
				key:=strings.Trim(inner,"\"'")
				for _, v:=range cur { if m,err:=toMap(v); err==nil { if val,ok:=m[key]; ok{next=append(next,val)} else {next=append(next,nil)} } }
			} else {
				idx,_:=strconv.Atoi(inner)
				for _, v:=range cur { if s,err:=toSlice(v); err==nil { if idx<0{idx=len(s)+idx}; if idx>=0 && idx < len(s){ next=append(next,s[idx]) } else { next=append(next,nil) } } }
			}
			cur=next
			continue
		}
		// unknown char maybe operator space - break
		if expr[i]==' ' || expr[i]=='\t' { i++; continue }
		// could be remaining expression like // etc unsupported
		break
	}
	if cur==nil { cur=[]interface{}{} }
	return cur, nil
}
