package tmpl

import (
	"bytes"
	"fmt"
	"path/filepath"
	"text/template"
)

type Template struct {
	root       *template.Template
	defaultCtx interface{}
	path       string
}

func New(root *template.Template, defaultCtx interface{}, path string) *Template {
	return &Template{root: root, defaultCtx: defaultCtx, path: path}
}

func (t *Template) Path() string {
	return t.path
}

func (t *Template) PathDir() string {
	return filepath.Dir(t.path)
}

func (t *Template) Exec(name string, ctx ...interface{}) (string, error) {
	if t.root == nil {
		return "", fmt.Errorf("template %q not defined", name)
	}
	// check defined
	if t.root.Lookup(name) == nil {
		return "", fmt.Errorf("template %q not defined", name)
	}
	var context interface{}
	if len(ctx) > 0 {
		context = ctx[0]
	} else {
		context = t.defaultCtx
	}
	var buf bytes.Buffer
	if err := t.root.ExecuteTemplate(&buf, name, context); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (t *Template) Inline(args ...interface{}) (string, error) {
	if len(args) < 1 || len(args) > 3 {
		return "", fmt.Errorf("wrong number of args for tpl: want 1, 2, or 3 - got %d", len(args))
	}
	var name, in string
	var context interface{}
	context = t.defaultCtx
	switch len(args) {
	case 1:
		in = stringify(args[0])
		name = ""
		// For inline without name, name should be ??? It creates a template maybe with random? It shouldn't overwrite root main name - clone root?
		// We'll parse as new template derived from root clone
		return t.execInline(name, in, context)
	case 2:
		name = stringify(args[0])
		in = stringify(args[1])
		return t.execInline(name, in, context)
	case 3:
		name = stringify(args[0])
		in = stringify(args[1])
		context = args[2]
		return t.execInline(name, in, context)
	}
	return "", nil
}

func stringify(v interface{}) string {
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", v)
}

func (t *Template) execInline(name, in string, context interface{}) (string, error) {
	if t.root == nil {
		return "", fmt.Errorf("no root template")
	}
	var tmpl *template.Template
	if name == "" {
		// clone root to avoid overriding main template definition
		cloned, err := t.root.Clone()
		if err != nil {
			// root may already have been executed (Clone fails after execution?). Template.Clone can be called after execution? It may error "template already executed"?? Root during execution - Clone check: can clone if not executed? Actually Template.Clone error if has executed? It says template is not cloneable after executed? During execution of root, its ??? might be considered executed. Original inline works during root execution, so they don't clone full root; they create a new template with same funcs/delims.
		// fallback: create new template sharing FuncMap? We don't have FuncMap stored. Use root's ??? We can create new temp using cloned if succeeded else use t.root.New with unique name
			_ = cloned
			_ = err
		}
		if cloned != nil {
			// Use a unique inline name
			tmpl = cloned.New("__inline__")
			if _, err := tmpl.Parse(in); err != nil { return "", err }
			var buf bytes.Buffer
			if err := tmpl.ExecuteTemplate(&buf, "__inline__", context); err != nil { return "", err }
			return buf.String(), nil
		}
		// fallback path below using root.New with generated name
		name = "__inline__"
		// continue to named path but this will mutate root - may overwrite subsequent? Use unique via counter could be stored? We'll just use root.New(name) and parse - subsequent inline reuse name overwrites.
		tmpl = t.root.New(name)
		if _, err := tmpl.Parse(in); err != nil { return "", err }
		var buf bytes.Buffer
		if err := tmpl.Execute(&buf, context); err != nil { return "", err }
		return buf.String(), nil
	}
	// named
	tmpl = t.root.New(name)
	if _, err := tmpl.Parse(in); err != nil { return "", err }
	var buf bytes.Buffer
	// Execute the newly defined template; tmpl.Execute executes that template (since New returns it)
	if err := tmpl.Execute(&buf, context); err != nil { return "", err }
	return buf.String(), nil
}

// Dir is alias mention in docs examples (tmpl.Dir) - does original have Dir method? PathDir docs example incorrectly uses tmpl.Dir . To avoid exposing extra method that original may not have, do NOT add Dir.

var _ = filepath.Dir
EOF
"}

