package funcs

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"text/template"
	"time"

	"local/gomplate/datafs"
	"local/gomplate/gcpcloud"
)

func NewMath(ctx context.Context) *MathFuncs { return &MathFuncs{ctx: ctx} }
func NewColl(ctx context.Context) *CollFuncs { return &CollFuncs{ctx: ctx} }
func NewConv(ctx context.Context) *ConvFuncs { return &ConvFuncs{ctx: ctx} }
func NewBase64(ctx context.Context) *Base64Funcs { return &Base64Funcs{ctx: ctx} }
func NewCrypto(ctx context.Context) *CryptoFuncs { return &CryptoFuncs{ctx: ctx} }
func NewData(ctx context.Context) *DataFuncs { return &DataFuncs{ctx: ctx} }
func NewEnv(ctx context.Context) *EnvFuncs { return &EnvFuncs{ctx: ctx} }
func NewFile(ctx context.Context) *FileFuncs { return &FileFuncs{ctx: ctx, fs: datafs.NewWdFS()} }
func NewFilePath(ctx context.Context) *FilePathFuncs { return &FilePathFuncs{ctx: ctx} }
func NewNet(ctx context.Context) *NetFuncs { return &NetFuncs{ctx: ctx} }
func NewPath(ctx context.Context) *PathFuncs { return &PathFuncs{ctx: ctx} }
func NewRandom(ctx context.Context) *RandomFuncs { return &RandomFuncs{ctx: ctx} }
func NewRegexp(ctx context.Context) *ReFuncs { return &ReFuncs{ctx: ctx} }
func NewSemver(ctx context.Context) *SemverFuncs { return &SemverFuncs{ctx: ctx} }
func NewSockaddr(ctx context.Context) *SockaddrFuncs { return &SockaddrFuncs{ctx: ctx} }
func NewStrings(ctx context.Context) *StringFuncs { return &StringFuncs{ctx: ctx} }
func NewTest(ctx context.Context) *TestFuncs { return &TestFuncs{ctx: ctx} }
func NewTime(ctx context.Context) *TimeFuncs { return newTimeFuncs(ctx) }
func NewUUID(ctx context.Context) *UUIDFuncs { return &UUIDFuncs{ctx: ctx} }
func NewAWS(ctx context.Context) *Funcs { return &Funcs{ctx: ctx} }
func NewGCP(ctx context.Context) *GcpFuncs {
	return &GcpFuncs{ctx: ctx, gcpopts: gcpcloud.ClientOptions{Timeout: 500 * time.Millisecond}}
}

// BuildFuncMap creates all template functions. tmplFunc is supplied by caller (main) and returns the tmpl namespace value.
func BuildFuncMap(ctx context.Context, rt *Runtime, tmplFunc interface{}) template.FuncMap {
	// namespace singletons (created per call - each template render creates one funcmap)
	mathNS := NewMath(ctx)
	collNS := NewColl(ctx)
	convNS := NewConv(ctx)
	base64NS := NewBase64(ctx)
	cryptoNS := NewCrypto(ctx)
	dataNS := NewData(ctx)
	envNS := NewEnv(ctx)
	fileNS := NewFile(ctx)
	filepathNS := NewFilePath(ctx)
	netNS := NewNet(ctx)
	pathNS := NewPath(ctx)
	randomNS := NewRandom(ctx)
	reNS := NewRegexp(ctx)
	semverNS := NewSemver(ctx)
	sockaddrNS := NewSockaddr(ctx)
	stringsNS := NewStrings(ctx)
	testNS := NewTest(ctx)
	timeNS := NewTime(ctx)
	uuidNS := NewUUID(ctx)
	awsNS := NewAWS(ctx)
	gcpNS := NewGCP(ctx)

	fm := template.FuncMap{
		// namespaces as niladic functions returning structs
		"aws": func() *Funcs { return awsNS },
		"base64": func() *Base64Funcs { return base64NS },
		"coll": func() *CollFuncs { return collNS },
		"conv": func() *ConvFuncs { return convNS },
		"crypto": func() *CryptoFuncs { return cryptoNS },
		"data": func() *DataFuncs { return dataNS },
		"env": func() *EnvFuncs { return envNS },
		"file": func() *FileFuncs { return fileNS },
		"filepath": func() *FilePathFuncs { return filepathNS },
		"gcp": func() *GcpFuncs { return gcpNS },
		"math": func() *MathFuncs { return mathNS },
		"net": func() *NetFuncs { return netNS },
		"path": func() *PathFuncs { return pathNS },
		"random": func() *RandomFuncs { return randomNS },
		"regexp": func() *ReFuncs { return reNS },
		"semver": func() *SemverFuncs { return semverNS },
		"sockaddr": func() *SockaddrFuncs { return sockaddrNS },
		"strings": func() *StringFuncs { return stringsNS },
		"test": func() *TestFuncs { return testNS },
		"time": func() *TimeFuncs { return timeNS },
		"uuid": func() *UUIDFuncs { return uuidNS },

		// datasource functions
		"datasource": func(args ...interface{}) (interface{}, error) {
			return datasourceFunc(rt, args...)
		},
		"ds": func(args ...interface{}) (interface{}, error) {
			return datasourceFunc(rt, args...)
		},
		"datasourceExists": func(alias string) bool {
			if rt == nil || rt.Registry == nil { return false }
			return rt.Registry.Exists(alias)
		},
		"datasourceReachable": func(alias string) bool {
			if rt == nil || rt.Registry == nil { return false }
			return rt.Registry.Reachable(alias)
		},
		"listDatasources": func() []string {
			if rt == nil || rt.Registry == nil { return []string{} }
			return rt.Registry.List()
		},
		"defineDatasource": func(alias string, url string) (string, error) {
			if rt != nil && rt.Registry != nil {
				rt.Registry.Define(alias, url, nil)
			}
			return "", nil
		},
		"include": func(args ...interface{}) (string, error) {
			if rt == nil || rt.Registry == nil { return "", fmt.Errorf("no datasource registry") }
			if len(args) < 1 || len(args) > 2 { return "", fmt.Errorf("include: expected 1 or 2 arguments") }
			alias := toString(args[0])
			sub := ""
			if len(args) == 2 { sub = toString(args[1]) }
			return rt.Registry.ReadRawString(alias, sub)
		},

		// aliases - math
		"add": mathNS.Add,
		"sub": func(a, b interface{}) (interface{}, error) { return mathNS.Sub(a, b) },
		"mul": mathNS.Mul,
		"div": func(a, b interface{}) (interface{}, error) { return mathNS.Div(a, b) },
		"pow": func(a, b interface{}) (interface{}, error) { return mathNS.Pow(a, b) },
		"rem": func(a, b interface{}) (interface{}, error) { return mathNS.Rem(a, b) },
		"seq": func(args ...interface{}) ([]int64, error) { return seqImpl(args...) },

		// coll aliases
		"dict": collNS.Dict,
		"has": collNS.Has,
		"jsonpath": collNS.JSONPath,
		"jq": collNS.JQ,
		"keys": collNS.Keys,
		"values": collNS.Values,
		// append/prepend: need function values matching method signatures but name in template errors should be lowercase alias? Template error for alias append: "error calling append: ..." The error prefix uses function name as called, so method wrapper is fine.
		"append": collNS.Append,
		"prepend": collNS.Prepend,
		"uniq": collNS.Uniq,
		"flatten": collNS.Flatten,
		"reverse": collNS.Reverse,
		"sort": collNS.Sort,
		"merge": collNS.Merge,
		"set": collNS.Set,
		"unset": collNS.Unset,
		"slice": collNS.Slice, // Note: original overrides Go's slice builtin with coll.Slice; coll.GoSlice is separate. Probe: template `slice` usage?

		// conv aliases
		"bool": convNS.Bool,
		"default": convNS.Default,
		"join": convNS.Join,
		"urlParse": convNS.URL,

		// data aliases
		"json": dataNS.JSON,
		"jsonArray": dataNS.JSONArray,
		"yaml": dataNS.YAML,
		"yamlArray": dataNS.YAMLArray,
		"toml": dataNS.TOML,
		"csv": dataNS.CSV,
		"csvByRow": dataNS.CSVByRow,
		"csvByColumn": dataNS.CSVByColumn,
		"cue": dataNS.CUE,
		"toJSON": dataNS.ToJSON,
		"toJSONPretty": dataNS.ToJSONPretty,
		"toYAML": dataNS.ToYAML,
		"toTOML": dataNS.ToTOML,
		"toCSV": dataNS.ToCSV,
		"toCUE": dataNS.ToCUE,

		// env
		"getenv": envNS.Getenv,

		// strings aliases
		"indent": stringsNS.Indent,
		"quote": stringsNS.Quote,
		"replaceAll": stringsNS.ReplaceAll,
		"shellQuote": stringsNS.ShellQuote,
		"squote": stringsNS.Squote,
		"title": stringsNS.Title,
		"toLower": stringsNS.ToLower,
		"toUpper": stringsNS.ToUpper,
		"trimSpace": stringsNS.TrimSpace,

		// test aliases
		"assert": testNS.Assert,
		"fail": testNS.Fail,
		"isKind": testNS.IsKind,
		"kind": testNS.Kind,
		"required": testNS.Required,
		"ternary": testNS.Ternary,

		// aws aliases
		"ec2meta": awsNS.EC2Meta,
		"ec2dynamic": awsNS.EC2Dynamic,
		"ec2region": awsNS.EC2Region,
		"ec2tag": awsNS.EC2Tag,
		"ec2tags": awsNS.EC2Tags,
	}

	// tpl alias will be registered by caller as tmpl namespace's Inline? tpl is top-level alias for tmpl.Inline. Caller supplies tmplFunc which returns *tmpl.Template; we need its Inline method via interface.
	// If tmplFunc is a function returning a value with Inline method, main will add "tmpl" and "tpl" entries separately.

	// plugins
	if rt != nil && len(rt.Plugins) > 0 {
		for name, plug := range rt.Plugins {
			funcName := name
			plugin := plug
			fm[funcName] = func(args ...interface{}) (string, error) {
				return runPlugin(ctx, rt, plugin, args)
			}
		}
	}

	return fm
}

func datasourceFunc(rt *Runtime, args ...interface{}) (interface{}, error) {
	if rt == nil || rt.Registry == nil {
		return nil, fmt.Errorf("undefined datasource")
	}
	if len(args) < 1 || len(args) > 2 {
		// template engine for variadic will not produce original "want at least 1" - our wrappers are variadic funcs at top level. Original datasource is a function with signature (alias string, subpath ...string) perhaps. That engine error would be want at least 1. Our function signature here is variadic - divergence for zero args. To mimic, main top-level alias could be defined differently but method here is shared. We return error that template will wrap as "error calling ds: ..."
		return nil, fmt.Errorf("datasource: expected at least 1 argument")
	}
	alias := toString(args[0])
	sub := ""
	if len(args) == 2 {
		sub = toString(args[1])
	}
	return rt.Registry.ReadParsed(alias, sub)
}

func runPlugin(ctx context.Context, rt *Runtime, plug PluginConfig, args []interface{}) (string, error) {
	timeout := plug.Timeout
	if timeout == 0 {
		if rt != nil && rt.PluginTimeout != 0 {
			timeout = rt.PluginTimeout
		} else {
			timeout = 5 * time.Second
		}
	}
	// Build command
	// plug.Cmd may contain spaces? Plugin config from CLI is just path, from config file cmd is single path - args separate.
	cmdArgs := []string{}
	cmdArgs = append(cmdArgs, plug.Args...)
	var stdinData []byte
	pluginArgs := args
	if plug.Pipe && len(args) > 0 {
		// last arg piped to stdin, not passed as argument
		stdinData = []byte(toString(args[len(args)-1]))
		pluginArgs = args[:len(args)-1]
	}
	for _, a := range pluginArgs {
		cmdArgs = append(cmdArgs, toString(a))
	}
	// Plugin timeout context
	cctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	cmd := exec.CommandContext(cctx, plug.Cmd, cmdArgs...)
	if plug.Pipe {
		cmd.Stdin = bytes.NewReader(stdinData)
	}
	var out bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errBuf
	// On Windows powershell handling not needed
	err := cmd.Run()
	if errBuf.Len() > 0 {
		// plugin stderr printed to gomplate stderr
		os.Stderr.Write(errBuf.Bytes())
	}
	if err != nil {
		if cctx.Err() != nil {
			return "", fmt.Errorf("plugin timed out after %s", timeout.String())
		}
		return "", err
	}
	return out.String(), nil
}

var _ = strings.TrimSpace
EOF
"}

