		}
		node.Cmd = p.Cmd
		node.Args = p.Args
		node.Pipe = p.Pipe
		return node, nil
	}
	var node struct {
		Cmd     string   `yaml:"cmd"`
		Args    []string `yaml:"args,omitempty"`
		Timeout string   `yaml:"timeout"`
		Pipe    bool     `yaml:"pipe,omitempty"`
	}
	node.Cmd = p.Cmd
