func (d DataSource) MarshalYAML() (interface{}, error) {
	// Marshal as struct with header then url, URL string normalized as url.URL string if it parses as absolute file etc? Caller pre-normalizes.
	return raw{Header: d.Header, URL: d.URL}, nil
}

func (d *DataSource) UnmarshalYAML(value *yaml.Node) error {
	var r raw
	if err := value.Decode(&r); err != nil {
		return err
	}
	d.Header = r.Header
	d.URL = r.URL
	// URL numbers become strings via yaml decode into string field - yaml.v3 should give "123"
	return nil
}

// Normalize URL string: if it's an absolute path, convert to file:// URL; if it parses as URL, return url.String(), else raw.
func NormalizeURLString(s string) string {
	if s == "" {
		return s
	}
	if strings.HasPrefix(s, "/") {
		// absolute path -> file://
		u := &url.URL{Scheme: "file", Path: s}
		return u.String()
	}
	if u, err := url.Parse(s); err == nil {
		// url.Parse for relative path with spaces escapes
		return u.String()
	}
	return s
}

