type flagVals struct {
	datasources []string
	headers []string
	contexts []string
	plugins []string
	inputFiles []string
	in string
	inputDir string
	excludes []string
	excludeProcessing []string
	includes []string
	outputFiles []string
	templates []string
	outputDir string
	outputMap string
	chmod string
	execPipe bool
	leftDelim string
	rightDelim string
	missingKey string
	experimental bool
	verbose bool
	configPath string
	help bool
	version bool
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func buildFlagSet(fv *flagVals) *pflag.FlagSet {
	fs := pflag.NewFlagSet("gomplate", pflag.ContinueOnError)
	fs.SortFlags = false
	fs.SetOutput(io.Discard)
	// defaults for usage generation: inputFiles/outputFiles etc storage initialized by sliceValue constructors
	// -d
	fs.VarP(newSliceValue(nil, &fv.datasources, "datasource"), "datasource", "d", "datasource in alias=URL form. Specify multiple times to add multiple sources.")
	fs.VarP(newSliceValue(nil, &fv.headers, "header"), "datasource-header", "H", "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
	fs.VarP(newSliceValue(nil, &fv.contexts, "context"), "context", "c", "pre-load a datasource into the context, in alias=URL form. Use the special alias `.` to set the root context.")
	fs.StringSliceVar(&fv.plugins, "plugin", nil, "plug in an external command as a function in name=path form. Can be specified multiple times")
	// -f
	// need default display [-] : sliceValue initial set
	fv.inputFiles = []string{"-"}
	// Register with a sliceValue with initial def [-]
	// Use VarP with custom value whose vals point to fv.inputFiles preinitialized
	fileVal := &sliceValue{vals: &fv.inputFiles, typ: "file"}
	fs.VarP(fileVal, "file", "f", "Template file to process. Omit to use standard input, or use --in or --input-dir")
	fs.StringVarP(&fv.in, "in", "i", "", "Template string to process (alternative to --file and --input-dir)")
	// input-dir directory type
	fv.inputDir = ""
	fs.Var(&stringTypeValue{v: &fv.inputDir, typ: "directory"}, "input-dir", "directory which is examined recursively for templates (alternative to --file and --in)")
	fs.StringSliceVar(&fv.excludes, "exclude", nil, "glob of files to not parse")
	fs.StringSliceVar(&fv.excludeProcessing, "exclude-processing", nil, "glob of files to be copied without parsing")
	fs.StringSliceVar(&fv.includes, "include", nil, "glob of files to parse")
	fv.outputFiles = []string{"-"}
	outVal := &sliceValue{vals: &fv.outputFiles, typ: "file"}
	fs.VarP(outVal, "out", "o", "output file name. Omit to use standard output.")
	fs.StringSliceVar(&fv.templates, "template", nil, "Additional template file(s)")
	// output-dir default "."
	fv.outputDir = "."
	fs.Var(&stringTypeValue{v: &fv.outputDir, typ: "directory"}, "output-dir", "directory to store the processed templates. Only used for --input-dir")
	fs.StringVar(&fv.outputMap, "output-map", "", "Template string to map the input file to an output path")
	fs.StringVar(&fv.chmod, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
	fs.BoolVar(&fv.execPipe, "exec-pipe", false, "pipe the output to the post-run exec command")
	// delimiters
	fv.leftDelim = "{{"
	fs.Var(&stringTypeValue{v: &fv.leftDelim, typ: "delimiter"}, "left-delim", "override the default left-delimiter [$GOMPLATE_LEFT_DELIM]")
	fv.rightDelim = "}}"
	fs.Var(&stringTypeValue{v: &fv.rightDelim, typ: "delimiter"}, "right-delim", "override the default right-delimiter [$GOMPLATE_RIGHT_DELIM]")
	fs.StringVar(&fv.missingKey, "missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")
	fs.BoolVar(&fv.experimental, "experimental", false, "enable experimental features [$GOMPLATE_EXPERIMENTAL]")
	fs.BoolVarP(&fv.verbose, "verbose", "V", false, "output extra information about what gomplate is doing")
	fs.StringVar(&fv.configPath, "config", ".gomplate.yaml", "config file (overridden by commandline flags)")
	fs.BoolVarP(&fv.help, "help", "h", false, "help for gomplate")
	fs.BoolVarP(&fv.version, "version", "v", false, "version for gomplate")

	// After definitions, capture usage
	usageText = "Usage:\n  gomplate [flags]\n\nFlags:\n" + fs.FlagUsagesWrapped(0)
	helpText = "Process text files with Go templates\n\n" + usageText
	return fs
}

func run(args []string) int {
	initLogger()
	fv := &flagVals{}
	fs := buildFlagSet(fv)
	// need reconstruct usage after fs defined (buildFlagSet sets)
	err := fs.Parse(args)
	if err != nil {
		// pflag may return ErrHelp? We defined help flag so not.
		return cobraError(err, true)
	}
	if fv.help {
		fmt.Fprint(os.Stdout, helpText)
		return 0
	}
	if fv.version {
		fmt.Fprintln(os.Stdout, "gomplate version "+versionStr)
		return 0
	}
	// positional args
	// ArgsLenAtDash: index in Args() where dash-terminated args start; if -1, no --
	dashIdx := fs.ArgsLenAtDash()
	allArgs := fs.Args()
	var preDash []string
	var postExec []string
	if dashIdx == -1 {
		preDash = allArgs
		postExec = nil
	} else {
		preDash = allArgs[:dashIdx]
		postExec = allArgs[dashIdx:]
	}
	if len(preDash) > 0 {
		err := fmt.Errorf("unknown command %q for %q", preDash[0], "gomplate")
		return cobraError(err, true)
	}
	verboseEnabled = fv.verbose

	// custom flag validations & parsing
	// Datasources + contexts first
	cliDatasources := make(map[string]configpkg.DataSource)
	cliContexts := make(map[string]configpkg.DataSource)
	// helper to parse datasource strings
	for _, rawArg := range fv.datasources {
		alias, ds, perr := parseDatasourceArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		if alias == "" && ds.URL == "" && rawArg == "" {
			continue
		}
		// Empty rawArg means --datasource= with empty value - skip (original)
		if rawArg == "" {
			continue
		}
		cliDatasources[alias] = ds
	}
	for _, rawArg := range fv.contexts {
		alias, ds, perr := parseDatasourceArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		if rawArg == "" { continue }
		cliContexts[alias] = ds
	}
	// headers
	type headerEntry struct { alias string; header http.Header }
	var cliHeaders []headerEntry
	for _, rawArg := range fv.headers {
		alias, hdr, perr := parseHeaderArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		cliHeaders = append(cliHeaders, headerEntry{alias, hdr})
	}
	// plugins
	cliPlugins := make(map[string]gomplatectx.PluginConfig)
	// Use ctx PluginConfig type
	for _, rawArg := range fv.plugins {
		if rawArg == "" { continue }
		name, pc, perr := parsePluginArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		cliPlugins[name] = pc
	}
	// templates parsing (store raw, normalized later) - no validation error except URL parse?
	cliTemplates := make(map[string]configpkg.DataSource)
	// maintain order of template args for deterministic nested loading - config map sorted by alias in marshal but nested templates order may matter for overrides definitions. Use slice too.
	type tmplEntry struct { alias string; ds configpkg.DataSource }
	var cliTemplateList []tmplEntry
	for _, rawArg := range fv.templates {
		if rawArg == "" { continue }
		alias, ds := parseTemplateArg(rawArg)
		cliTemplates[alias] = ds
		cliTemplateList = append(cliTemplateList, tmplEntry{alias, ds})
	}

	// environment config preliminary (plugin timeout invalid etc will be checked after config file? original cobra error category)
	// Determine config file path
	configPath := ""
	configExplicit := false
	if fs.Lookup("config").Changed {
		configPath = fv.configPath
		configExplicit = true
		if configPath == "" {
			configExplicit = false // disabled
		}
	} else if envCfg, present := os.LookupEnv("GOMPLATE_CONFIG"); present {
		if envCfg == "" {
			configPath = ""
			configExplicit = false
		} else {
			configPath = envCfg
			configExplicit = true
		}
	} else {
		// default
		if _, err := os.Stat(".gomplate.yaml"); err == nil {
			configPath = ".gomplate.yaml"
			configExplicit = false // but used
		} else {
			configPath = ""
		}
	}

	var fileCfg *configpkg.Config
	var cfgFileUsed string
	if configPath != "" {
		content, err := readFileForConfig(configPath)
		if err != nil {
			// config file requested, but couldn't be opened...
			// if default file exists but unreadable? Treat as requested if explicit or default present.
			msg := fmt.Sprintf("config file requested, but couldn't be opened: %v", err)
			return cobraError(fmt.Errorf("%s", msg), false)
		}
		cfgParsed, err := parseConfigFile(configPath, content)
		if err != nil {
			return cobraError(err, false)
		}
		fileCfg = cfgParsed
		cfgFileUsed = configPath
		_ = configExplicit
	}
	if cfgFileUsed != "" && verboseEnabled {
		logMsg("DEBUG", "using config file", logAttr{"cfgFile", cfgFileUsed})
	}

	// Build merged config
	cfg := configpkg.Config{}
	// env defaults first
	// GOMPLATE_LEFT_DELIM etc
	if v, present := os.LookupEnv("GOMPLATE_LEFT_DELIM"); present { cfg.LeftDelim = v }
	if v, present := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); present { cfg.RightDelim = v }
	if v, present := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); present {
		if b, err := strconv.ParseBool(v); err == nil { cfg.Experimental = b }
	}
	if v, present := os.LookupEnv("GOMPLATE_PLUGIN_TIMEOUT"); present {
		d, err := time.ParseDuration(v)
		if err != nil {
			msg := fmt.Sprintf("GOMPLATE_PLUGIN_TIMEOUT set to invalid value %q: %v", v, err)
			return cobraError(fmt.Errorf("%s", msg), false)
		}
		cfg.PluginTimeout = configpkg.Duration(d)
	}
	// config file overwrites env if keys present
	if fileCfg != nil {
		// detect present keys via yaml map
		present := presentKeys(cfgFileUsed)
		mergeConfigFile(&cfg, fileCfg, present)
	}
	// CLI overwrites
	// datasources etc merge
	if len(cliDatasources) > 0 {
		if cfg.Datasources == nil { cfg.Datasources = make(map[string]configpkg.DataSource) }
		for k, v := range cliDatasources { cfg.Datasources[k] = v }
	}
	if len(cliContexts) > 0 {
		if cfg.Context == nil { cfg.Context = make(map[string]configpkg.DataSource) }
		for k, v := range cliContexts { cfg.Context[k] = v }
	}
	if len(cliTemplates) > 0 {
		if cfg.Templates == nil { cfg.Templates = make(map[string]configpkg.DataSource) }
		for k, v := range cliTemplates { cfg.Templates[k] = v }
	} else {
		// if templates from config file, need template list for loading - built later from map
	}
	if len(cliPlugins) > 0 {
		if cfg.Plugins == nil { cfg.Plugins = make(map[string]gomplatectx.PluginConfig) }
		for k, v := range cliPlugins { cfg.Plugins[k] = v }
	}
	// headers apply to datasources/context/templates in cfg
	for _, he := range cliHeaders {
		applyHeader(&cfg, he.alias, he.header)
	}
	// simple fields if Changed
	changed := func(name string) bool { f := fs.Lookup(name); return f != nil && f.Changed }
	if changed("in") { cfg.In = fv.in }
	if changed("file") { cfg.InputFiles = append([]string{}, fv.inputFiles...) }
	if changed("input-dir") { cfg.InputDir = fv.inputDir }
	if changed("exclude") || changed("include") {
		var exc []string
		if len(fv.includes) > 0 {
			exc = append(exc, "*")
			for _, inc := range fv.includes { exc = append(exc, "!"+inc) }
		}
		exc = append(exc, fv.excludes...)
		cfg.Excludes = exc
	}
	if changed("exclude-processing") { cfg.ExcludeProcessing = append([]string{}, fv.excludeProcessing...) }
	if changed("out") { cfg.OutputFiles = append([]string{}, fv.outputFiles...) }
	if changed("output-dir") { cfg.OutputDir = fv.outputDir } else {
		// flag default "." should not overwrite config - if config also empty, keep empty for now (defaults applied later)
		// However, if config file didn't set outputDir and ..., leave as cfg value (could be from file)
	}
	if changed("output-map") { cfg.OutputMap = fv.outputMap }
	if changed("chmod") { cfg.Chmod = fv.chmod }
	if changed("left-delim") { cfg.LeftDelim = fv.leftDelim }
	if changed("right-delim") { cfg.RightDelim = fv.rightDelim }
	if changed("missing-key") { cfg.MissingKey = fv.missingKey }
	if changed("experimental") { cfg.Experimental = fv.experimental }
	if changed("exec-pipe") { cfg.ExecPipe = fv.execPipe }
	// templates from CLI: ordering list vs config templates - if CLI templates exist, use them as list order; else config templates list sorted by alias for determinism
	var templateEntries []tmplEntry
	if len(cliTemplateList) > 0 {
		templateEntries = cliTemplateList
		// also include config-only templates? CLI merges map, entries for config templates not in CLI should also be included. Append sorted config templates not already present
		var extra []string
		for k := range cfg.Templates { found:=false; for _, e:=range templateEntries { if e.alias==k {found=true} }; if !found { extra=append(extra,k) } }
		sort.Strings(extra)
		for _, k := range extra { templateEntries = append(templateEntries, tmplEntry{k, cfg.Templates[k]}) }
	} else {
		var keys []string; for k:=range cfg.Templates { keys=append(keys,k) }; sort.Strings(keys)
		for _, k:=range keys { templateEntries = append(templateEntries, tmplEntry{k, cfg.Templates[k]}) }
	}
	if len(postExec) > 0 {
		cfg.PostExec = append([]string{}, postExec...)
	}
	// exec-pipe influence: if execPipe true, outputFiles set to ['-'] in config dump pre-defaults (original behaviour)
	if cfg.ExecPipe {
		cfg.OutputFiles = []string{"-"}
	}

	// verbose starting/config
	// Note: verbose flag may also be set? config file cannot set verbose
	if verboseEnabled {
		logMsg("DEBUG", "starting gomplate")
		yamlStr := marshalConfigYAML(cfg)
		msg := "config is:\n---\n" + yamlStr
		logMsg("DEBUG", msg, logAttr{"version", versionStr}, logAttr{"build", "HEAD"})
	}

	// apply defaults
	cfgForValidation := cfg // copy for validation dump applied
	applyDefaults(&cfgForValidation)
	// validation
	if verr := validateConfig(&cfgForValidation); verr != nil {
		// verbose completed rendering log before error? Validation failures in verbose: earlier examples - did they print completed rendering? For validation errors with -V, check: missing-key etc. In prototype earlier, verbose config dump then completed? Let's test original mental: In -V validation error case (--missing-key bogus with -V?) we didn't test. Log logic: renderer returns? Validation occurs before rendering, so no completed log? In earlier -V huge test, the flow printed completed rendering with templatesRendered 0 BEFORE error log for validation (the second log). That indicates Run function logs completed even on validation? Wait huge test validate failure: debug logs included completed rendering 0,0,0 between config dump and error. But that validation was outputFiles/outputDir conflict detected at ... It printed completed. Whereas for -i -f conflict with -V? Need approximate: In main flow, after defaults+validate, if validation fails we should still log completed? Check quickly by original mental: earlier `['-V', '-d', ..., '--exec-pipe']` output included completed rendering. That was validation failure. So validation failure path also includes completed rendering log with templatesRendered=0 errors=0 duration=0.
		// implement: if verbose, log completed with experimental attr if set
		if verboseEnabled {
			logCompleted(cfgForValidation, 0, 0, 0)
		}
		errMsg := fmt.Sprintf("failed to validate config: %s\n---\n%s", verr.Error(), marshalConfigYAML(cfgForValidation))
		// marshalConfigYAML returns trailing newline; original message ends with "\n" from yaml (log line adds). In log, err string ends with "\n" (yaml). That's fine our log formatter adds newline after.
		// However marshal should not add extra blank?
		return runtimeError(fmt.Errorf("%s", errMsg))
	}
	cfg = cfgForValidation
	if cfg.Experimental && verboseEnabled {
		logMsg("INFO", "experimental functions and features enabled!", logAttr{"experimental", true})
	}

	// runtime / registry
	// stdin handling
	stdinCacheFunc := makeStdinFunc()
	rt, registry := buildRuntime(cfg, stdinCacheFunc)

	// context building
	defaultCtx, rootCtxValue, ctxErr := buildContext(cfg, registry)
	if ctxErr != nil {
		if verboseEnabled {
			logCompleted(cfg, 0, 0, 0)
		}
		return runtimeError(ctxErr)
	}
	_ = defaultCtx

	// gather templates
	templates, gatherErr := gatherTemplates(cfg, stdinCacheFunc)
	if gatherErr != nil {
		if verboseEnabled {
			logCompleted(cfg, 0, 1, 0)
		}
		return runtimeError(fmt.Errorf("failed to gather templates for rendering: %w", gatherErr))
	}

	// render all
	start := time.Now()
	rendered := 0
	errorsCount := 0
	var firstErr error
	var execPipeBuffers [][]byte // per template rendered output for piping
	// If execPipe and postExec, output should be piped, not written
	for _, tmpl := range templates {
		// For inputDir processing exclusion, gather already marked copyOnly
		if tmpl.copyOnly {
			// copy raw content to output (if not whitespace? copying binary files - empty check? For copy, even whitespace? Probably copy regardless)
			if err := writeOutput(cfg, tmpl, tmpl.content, registry); err != nil {
				if firstErr == nil { firstErr = err }
				errorsCount++
				break
			}
			rendered++
			continue
		}
		output, rerr := renderOneTemplate(cfg, tmpl, rootCtxValue, defaultCtx, registry, rt, templateEntries)
		if rerr != nil {
			if firstErr == nil { firstErr = rerr }
			// Determine errors count for verbose: parse errors gave 0, others 1
			if strings.Contains(rerr.Error(), "parse template") {
				// errors stays? Original: parse error errorsCount 0
			} else {
				errorsCount++
			}
			// If multiple templates, does gomplate continue rendering others on error? Probably stops? Probe later. Break for now.
			break
		}
		rendered++
		if cfg.ExecPipe && len(cfg.PostExec) > 0 {
			execPipeBuffers = append(execPipeBuffers, output)
			continue
		}
		// write output
		if err := writeOutput(cfg, tmpl, output, registry); err != nil {
			// error format original: renderTemplate: failed to render template <arg>: mkdirAll ...
			// writeOutput returns errors already in that shape? Our writeOutput returns raw mkdir error - wrap here
			wrapped := fmt.Errorf("renderTemplate: failed to render template %s: %w", tmpl.name, err)
			if firstErr == nil { firstErr = wrapped }
			errorsCount++
			break
		}
	}
	duration := time.Since(start)
	if verboseEnabled {
		// If firstErr is a gather... already logged? For render errors, log completed before error
		logCompleted(cfg, rendered, errorsCount, duration)
	}
	if firstErr != nil {
		return runtimeError(firstErr)
	}

	// post-exec
	if len(cfg.PostExec) > 0 {
		if verboseEnabled {
			// args as []string
			logMsg("DEBUG", "running post-exec command", logAttr{"args", cfg.PostExec})
		}
		var stdinBytes []byte
		if cfg.ExecPipe {
			for _, b := range execPipeBuffers { stdinBytes = append(stdinBytes, b...) }
		}
		if err := runPostExec(cfg, stdinBytes); err != nil {
			return runtimeError(err)
		}
	}
	return 0
}

func logCompleted(cfg configpkg.Config, rendered, errorsCount int, duration time.Duration) {
	attrs := []logAttr{}
	if cfg.Experimental { attrs = append(attrs, logAttr{"experimental", true}) }
	attrs = append(attrs, logAttr{"templatesRendered", rendered}, logAttr{"errors", errorsCount}, logAttr{"duration", duration})
	logMsg("DEBUG", "completed rendering", attrs...)
	// Note: original ordering: when experimental false, attrs are templatesRendered, errors, duration; when true, experimental first. That matches observed.
}

func marshalConfigYAML(cfg configpkg.Config) string {
	// Use yaml.Marshal; config struct is empty -> "{}\n"
	b, err := yaml.Marshal(&cfg)
	if err != nil { return "{}\n" }
	return string(b)
}

func presentKeys(path string) map[string]bool {
	keys := make(map[string]bool)
	if path == "" { return keys }
	b, err := readFileForConfig(path)
	if err != nil { return keys }
	var m map[string]interface{}
	if err := yaml.Unmarshal(b, &m); err == nil {
		for k := range m { keys[k] = true }
	}
	return keys
}

func mergeConfigFile(dst *configpkg.Config, src *configpkg.Config, present map[string]bool) {
	// If present map empty due to re-read fail, simply overwrite non-zero
	// We'll follow present keys if available, else heuristic.
	has := func(k string) bool {
		if len(present)==0 { return true }
		return present[k]
	}
	if has("datasources") { dst.Datasources = src.Datasources }
	if has("context") { dst.Context = src.Context }
	if has("templates") { dst.Templates = src.Templates }
	if has("plugins") { dst.Plugins = src.Plugins }
	if has("in") { dst.In = src.In }
	if has("inputDir") { dst.InputDir = src.InputDir }
	if has("excludes") { dst.Excludes = src.Excludes }
	if has("excludeProcessing") { dst.ExcludeProcessing = src.ExcludeProcessing }
	if has("inputFiles") { dst.InputFiles = src.InputFiles }
	if has("outputDir") { dst.OutputDir = src.OutputDir }
	if has("outputMap") { dst.OutputMap = src.OutputMap }
	if has("outputFiles") { dst.OutputFiles = src.OutputFiles }
	if has("chmod") { dst.Chmod = src.Chmod }
	if has("leftDelim") { dst.LeftDelim = src.LeftDelim }
	if has("rightDelim") { dst.RightDelim = src.RightDelim }
	if has("missingKey") { dst.MissingKey = src.MissingKey }
	if has("postExec") { dst.PostExec = src.PostExec }
	if has("pluginTimeout") { dst.PluginTimeout = src.PluginTimeout }
	if has("execPipe") { dst.ExecPipe = src.ExecPipe }
	if has("experimental") { dst.Experimental = src.Experimental }
	// also includes? config has no includes key per docs
}

func readFileForConfig(p string) ([]byte, error) {
	abs := datafs.Abs(p)
	b, err := os.ReadFile(abs)
	if err != nil {
		return nil, datafs.PathErrorLike("open", p, err)
		// PathErrorLike uses Abs(p) internally for trimmed - it receives p as supplied, Abs will make trimmed absolute - correct
	}
	return b, nil
}

func parseConfigFile(path string, content []byte) (*configpkg.Config, error) {
	var cfg configpkg.Config
	// Ensure maps initialized for header {}?
	if err := yaml.Unmarshal(content, &cfg); err != nil {
		return nil, fmt.Errorf("parsing config file %q: YAML decoding failed, syntax may be invalid: %w", path, err)
	}
	// initialize headers
	for k, ds := range cfg.Datasources { if ds.Header==nil { ds.Header=make(http.Header); cfg.Datasources[k]=ds } }
	for k, ds := range cfg.Context { if ds.Header==nil { ds.Header=make(http.Header); cfg.Context[k]=ds } }
	for k, ds := range cfg.Templates { if ds.Header==nil { ds.Header=make(http.Header); cfg.Templates[k]=ds } }
	return &cfg, nil
}

func applyHeader(cfg *configpkg.Config, alias string, hdr http.Header) {
	// Apply to datasources/context/templates if alias exists, else store for later dynamic? -H can apply to datasources defined dynamically - our registry headers handle alias separately via CLI headers registry later - but for config dump, headers are merged into datasource entry if it exists. If not exists, original config dump for -H alone with -i hi showed no datasource entry (header discarded for dump). Headers for dynamic sources are still available at runtime via registry - main buildRuntime should receive cli headers list - we lost it after applyHeader scope. To handle, buildRuntime will re-derive from cfg? If alias entry didn't exist, header not stored anywhere. Solution: Store headers in a global var for runtime.
	// We'll use package var cliHeaderMap
	if cliHeaderMap == nil { cliHeaderMap = make(map[string]http.Header) }
	// merge into global
	exist := cliHeaderMap[alias]
	if exist==nil { exist = make(http.Header) }
	for k, vals := range hdr { exist[k]=append(exist[k], vals...) }
	cliHeaderMap[alias]=exist

	applyTo := func(m map[string]configpkg.DataSource) {
		if m==nil { return }
		if ds, ok := m[alias]; ok {
			if ds.Header==nil { ds.Header=make(http.Header) }
			for k, vals:=range hdr { ds.Header[k]=append(ds.Header[k], vals...) }
			m[alias]=ds
		}
	}
	applyTo(cfg.Datasources); applyTo(cfg.Context); applyTo(cfg.Templates)
}

var cliHeaderMap map[string]http.Header

func applyDefaults(cfg *configpkg.Config) {
	if cfg.LeftDelim == "" { cfg.LeftDelim = "{{" }
	if cfg.RightDelim == "" { cfg.RightDelim = "}}" }
	if cfg.MissingKey == "" { cfg.MissingKey = "error" }
	if cfg.PluginTimeout.Duration() == 0 { cfg.PluginTimeout = configpkg.Duration(5 * time.Second) }
	if cfg.InputDir != "" && cfg.OutputMap == "" && cfg.OutputDir == "" {
		cfg.OutputDir = "."
	}
	// input/output files defaults
	if cfg.InputDir == "" {
		if cfg.In == "" && len(cfg.InputFiles) == 0 {
			cfg.InputFiles = []string{"-"}
		}
		if len(cfg.OutputFiles) == 0 {
			// number? default ['-']
			cfg.OutputFiles = []string{"-"}
		}
	} else {
		// inputDir mode: no outputFiles default
	}
}

func validateConfig(cfg *configpkg.Config) error {
	// only-one inputs
	inputOpts := []struct{name string; present bool}{
		{"in", cfg.In != "" || cfg.In == "" && false}, // need detect presence of in even if empty string? Original: -i "" counts as in present? Validation with -i '' + -f - ? cfg.In is "" indistinguishable; but post defaults In may be ... original tracks InPresence separately. Our cfg.In empty due to -i "" would be considered not set, then InputFiles default - stdin; conflict not detected. Edge - ignore.
		{"inputFiles", len(cfg.InputFiles) > 0},
		{"inputDir", cfg.InputDir != ""},
	}
