const versionStr = "0.0.0"

var helpText string
var usageText string

// ---------- logging ----------
type logAttr struct {
	k string
	v interface{}
}

var (
	logFormat string // json, logfmt, console, simple
	verboseEnabled bool
	stderrIsTTY bool
)

func initLogger() {
	stderrIsTTY = isTTY(os.Stderr)
	f := os.Getenv("GOMPLATE_LOG_FORMAT")
	switch f {
	case "json", "logfmt", "console", "simple":
		logFormat = f
	default:
		if stderrIsTTY {
			logFormat = "console"
		} else {
			logFormat = "json"
		}
	}
}

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil { return false }
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func logLevelEnabled(level string) bool {
	if verboseEnabled { return true }
	// non-verbose: only ERROR (and maybe WARN? original default level appears to be ???)
	return level == "ERROR"
}

func logMsg(level, msg string, attrs ...logAttr) {
	if !logLevelEnabled(level) { return }
	now := time.Now()
	var line string
	switch logFormat {
	case "logfmt":
		line = formatLogfmt(now, level, msg, attrs)
	case "console":
		line = formatConsole(now, level, msg, attrs, false)
	case "simple":
		line = formatSimple(msg, attrs)
	default: // json
		line = formatJSON(now, level, msg, attrs)
	}
	fmt.Fprintln(os.Stderr, line)
}

func formatJSON(now time.Time, level, msg string, attrs []logAttr) string {
	var b bytes.Buffer
	b.WriteString("{")
	writeJSONField := func(key string, val interface{}, first bool) {
		if !first { b.WriteString(",") }
		kb, _ := json.Marshal(key)
		b.Write(kb)
		b.WriteString(":")
		vb, _ := json.Marshal(val)
		// duration special: json.Marshal(time.Duration) is int64 ns - good; but our attrs may pass duration as time.Duration
		b.Write(vb)
	}
	_ = writeJSONField
	// manual for ordering and duration type
	fields := []struct{k string; v interface{}}{}
	// time as string RFC3339Nano
	// json encode time string
	tb, _ := json.Marshal(now.Format(time.RFC3339Nano))
	b.WriteString(`"time":`); b.Write(tb)
	lb, _ := json.Marshal(level); b.WriteString(`,"level":`); b.Write(lb)
	mb, _ := json.Marshal(msg); b.WriteString(`,"msg":`); b.Write(mb)
	for _, a := range attrs {
		kb, _ := json.Marshal(a.k); b.WriteString(","); b.Write(kb); b.WriteString(":")
		// special handling
		switch v := a.v.(type) {
		case time.Duration:
			b.WriteString(strconv.FormatInt(int64(v), 10))
		default:
			vb, _ := json.Marshal(v); b.Write(vb)
		}
		_ = fields
	}
	b.WriteString("}")
	return b.String()
}

func needsQuote(s string) bool {
	if s == "" { return true }
	for _, r := range s {
		if r <= ' ' || r == '"' || r == '=' || r == '\\' || !unicode.IsPrint(r) {
			return true
		}
	}
	return false
}

func attrValueString(v interface{}) string {
	switch t := v.(type) {
	case string:
		if needsQuote(t) { return strconv.Quote(t) }
		return t
	case time.Duration:
		return t.String()
	case []string:
		s := fmt.Sprintf("%v", t) // [a b]
		if needsQuote(s) { return strconv.Quote(s) }
		return s
	case error:
		s := t.Error()
		if needsQuote(s) { return strconv.Quote(s) }
		return s
	default:
		s := fmt.Sprintf("%v", t)
		if needsQuote(s) { return strconv.Quote(s) }
		return s
	}
}

func formatLogfmt(now time.Time, level, msg string, attrs []logAttr) string {
	// time format like slog TextHandler: 2006-01-02T15:04:05.000Z07:00 - in UTC gives ...Z
	timeStr := now.Format("2006-01-02T15:04:05.000Z07:00")
	var sb strings.Builder
	sb.WriteString("time="); sb.WriteString(timeStr)
	sb.WriteString(" level="); sb.WriteString(level)
	sb.WriteString(" msg=")
	if needsQuote(msg) { sb.WriteString(strconv.Quote(msg)) } else { sb.WriteString(msg) }
	// slog prints msg="" for empty - needsQuote("") true -> ""
	for _, a := range attrs {
		sb.WriteString(" "); sb.WriteString(a.k); sb.WriteString("="); sb.WriteString(attrValueString(a.v))
	}
	return sb.String()
}

func levelAbbrev(level string) string {
	switch level {
	case "DEBUG": return "DBG"
	case "INFO": return "INF"
	case "WARN", "WARNING": return "WRN"
	case "ERROR": return "ERR"
	default: return level
	}
}

func formatConsole(now time.Time, level, msg string, attrs []logAttr, early bool) string {
	// early = special ERROR long form handled separately
	timeStr := now.Format("15:04:05")
	if stderrIsTTY && logFormat == "console" {
		// colored
		var sb strings.Builder
		sb.WriteString("\x1b[2m"); sb.WriteString(timeStr); sb.WriteString("\x1b[0m")
		sb.WriteString(" ")
		abbr := levelAbbrev(level)
		switch level {
		case "ERROR": sb.WriteString("\x1b[91m"); sb.WriteString(abbr); sb.WriteString("\x1b[0m")
		case "INFO": sb.WriteString("\x1b[92m"); sb.WriteString(abbr); sb.WriteString("\x1b[0m")
		case "WARN", "WARNING": sb.WriteString("\x1b[93m"); sb.WriteString(abbr); sb.WriteString("\x1b[0m")
		default: sb.WriteString(abbr)
		}
		sb.WriteString(" ")
		sb.WriteString(msg)
		for _, a := range attrs {
			sb.WriteString(" ")
			sb.WriteString("\x1b[2m"); sb.WriteString(a.k); sb.WriteString("="); sb.WriteString("\x1b[0m")
			sb.WriteString(attrValueString(a.v))
		}
		return sb.String()
	}
	var sb strings.Builder
	sb.WriteString(timeStr); sb.WriteString(" "); sb.WriteString(levelAbbrev(level)); sb.WriteString(" "); sb.WriteString(msg)
	for _, a := range attrs {
		sb.WriteString(" "); sb.WriteString(a.k); sb.WriteString("="); sb.WriteString(attrValueString(a.v))
	}
	return sb.String()
}

func formatSimple(msg string, attrs []logAttr) string {
	var sb strings.Builder
	sb.WriteString("  "); sb.WriteString(msg)
	for _, a := range attrs {
		sb.WriteString(" "); sb.WriteString(a.k); sb.WriteString("="); sb.WriteString(attrValueString(a.v))
	}
	return sb.String()
}

func logError(err error) {
	logMsg("ERROR", "", logAttr{"err", err.Error()})
}
func logErrorStr(s string) {
	logMsg("ERROR", "", logAttr{"err", s})
}

// early logger for cobra flag errors: ERROR  err="..."
func logEarlyError(err error) {
	// format exactly: ERROR + two spaces? model: "ERROR" + " " + "" + " " + err="..."
	msg := fmt.Sprintf("ERROR  err=%s", strconv.Quote(err.Error()))
	fmt.Fprintln(os.Stderr, msg)
}

// cobra-style error: Error: ... to stderr, usage to stdout, then log line
func cobraError(err error, useEarly bool) int {
	fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
	fmt.Fprint(os.Stdout, usageText)
	if useEarly {
		logEarlyError(err)
	} else {
		logError(err)
	}
	return 1
}

func runtimeError(err error) int {
	logError(err)
	return 1
}

// ---------- pflag custom values ----------
type sliceValue struct {
	vals *[]string
	typ string
	changed bool
}
func newSliceValue(def []string, p *[]string, typ string) *sliceValue {
	*p = append([]string{}, def...)
	return &sliceValue{vals: p, typ: typ}
}
func (s *sliceValue) String() string {
	if s.vals == nil || *s.vals == nil { return "[]" }
	// CSV encode
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	// pflag stringSlice String() writes CSV without newline? csv writer adds newline turned? We'll emulate: join via csv encoding trimming trailing newline
	_ = w.Write(*s.vals)
	w.Flush()
	str := strings.TrimSuffix(buf.String(), "\n")
	str = strings.TrimSuffix(str, "\r\n")
	return "[" + str + "]"
}
func (s *sliceValue) Type() string { return s.typ }
func (s *sliceValue) Set(v string) error {
	// Called by pflag for non-slice? Actually SliceValue path uses Replace/Append; Set may be called in some paths - treat as Append if changed else Replace using CSV parse?
