		*s.vals = []string{v}
		s.changed = true
		return nil
	}
	*s.vals = append(*s.vals, v)
	return nil
}
func (s *sliceValue) Replace(vals []string) error {
	*s.vals = append([]string{}, vals...)
	s.changed = true
	return nil
}
func (s *sliceValue) Append(v string) error {
	*s.vals = append(*s.vals, v)
	s.changed = true
	return nil
}
func (s *sliceValue) GetSlice() []string { return append([]string{}, (*s.vals)...) }

type stringTypeValue struct {
	v *string
	typ string
}
func (s *stringTypeValue) String() string { if s.v == nil { return "" }; return *s.v }
func (s *stringTypeValue) Type() string { return s.typ }
func (s *stringTypeValue) Set(v string) error { *s.v = v; return nil }

// ---------- config handling ----------

type flagVals struct {
	datasources []string
	headers []string
	contexts []string
