}

func buildFlagSet(fv *flagVals) *pflag.FlagSet {
	fs := pflag.NewFlagSet("gomplate", pflag.ContinueOnError)
	fs.SortFlags = false
	fs.SetOutput(io.Discard)
	// defaults for usage generation: inputFiles/outputFiles etc storage initialized by sliceValue constructors
	// -d
	fs.VarP(newSliceValue(nil, &fv.datasources, "datasource"), "datasource", "d", "datasource in alias=URL form. Specify multiple times to add multiple sources.")
	fs.VarP(newSliceValue(nil, &fv.headers, "header"), "datasource-header", "H", "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
	fs.VarP(newSliceValue(nil, &fv.contexts, "context"), "context", "c", "pre-load a datasource into the context, in alias=URL form. Use the special alias `.` to set the root context.")
	fs.StringSliceVar(&fv.plugins, "plugin", nil, "plug in an external command as a function in name=path form. Can be specified multiple times")
	// -f
	// need default display [-] : sliceValue initial set
	fv.inputFiles = []string{"-"}
	// Register with a sliceValue with initial def [-]
	// Use VarP with custom value whose vals point to fv.inputFiles preinitialized
	fileVal := &sliceValue{vals: &fv.inputFiles, typ: "file"}
	fs.VarP(fileVal, "file", "f", "Template file to process. Omit to use standard input, or use --in or --input-dir")
	fs.StringVarP(&fv.in, "in", "i", "", "Template string to process (alternative to --file and --input-dir)")
	// input-dir directory type
	fv.inputDir = ""
	fs.Var(&stringTypeValue{v: &fv.inputDir, typ: "directory"}, "input-dir", "directory which is examined recursively for templates (alternative to --file and --in)")
	fs.StringSliceVar(&fv.excludes, "exclude", nil, "glob of files to not parse")
	fs.StringSliceVar(&fv.excludeProcessing, "exclude-processing", nil, "glob of files to be copied without parsing")
	fs.StringSliceVar(&fv.includes, "include", nil, "glob of files to parse")
	fv.outputFiles = []string{"-"}
	outVal := &sliceValue{vals: &fv.outputFiles, typ: "file"}
	fs.VarP(outVal, "out", "o", "output file name. Omit to use standard output.")
	fs.StringSliceVar(&fv.templates, "template", nil, "Additional template file(s)")
	// output-dir default "."
	fv.outputDir = "."
	fs.Var(&stringTypeValue{v: &fv.outputDir, typ: "directory"}, "output-dir", "directory to store the processed templates. Only used for --input-dir")
	fs.StringVar(&fv.outputMap, "output-map", "", "Template string to map the input file to an output path")
	fs.StringVar(&fv.chmod, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
	fs.BoolVar(&fv.execPipe, "exec-pipe", false, "pipe the output to the post-run exec command")
	// delimiters
	fv.leftDelim = "{{"
	fs.Var(&stringTypeValue{v: &fv.leftDelim, typ: "delimiter"}, "left-delim", "override the default left-delimiter [$GOMPLATE_LEFT_DELIM]")
	fv.rightDelim = "}}"
	fs.Var(&stringTypeValue{v: &fv.rightDelim, typ: "delimiter"}, "right-delim", "override the default right-delimiter [$GOMPLATE_RIGHT_DELIM]")
	fs.StringVar(&fv.missingKey, "missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")
	fs.BoolVar(&fv.experimental, "experimental", false, "enable experimental features [$GOMPLATE_EXPERIMENTAL]")
	fs.BoolVarP(&fv.verbose, "verbose", "V", false, "output extra information about what gomplate is doing")
	fs.StringVar(&fv.configPath, "config", ".gomplate.yaml", "config file (overridden by commandline flags)")
	fs.BoolVarP(&fv.help, "help", "h", false, "help for gomplate")
	fs.BoolVarP(&fv.version, "version", "v", false, "version for gomplate")

	// After definitions, capture usage
	usageText = "Usage:\n  gomplate [flags]\n\nFlags:\n" + fs.FlagUsagesWrapped(0)
	helpText = "Process text files with Go templates\n\n" + usageText
	return fs
}

func run(args []string) int {
	initLogger()
	fv := &flagVals{}
	fs := buildFlagSet(fv)
	// need reconstruct usage after fs defined (buildFlagSet sets)
	err := fs.Parse(args)
	if err != nil {
		// pflag may return ErrHelp? We defined help flag so not.
		return cobraError(err, true)
	}
	if fv.help {
		fmt.Fprint(os.Stdout, helpText)
		return 0
	}
	if fv.version {
		fmt.Fprintln(os.Stdout, "gomplate version "+versionStr)
		return 0
	}
	// positional args
	// ArgsLenAtDash: index in Args() where dash-terminated args start; if -1, no --
	dashIdx := fs.ArgsLenAtDash()
	allArgs := fs.Args()
	var preDash []string
	var postExec []string
	if dashIdx == -1 {
		preDash = allArgs
		postExec = nil
	} else {
		preDash = allArgs[:dashIdx]
		postExec = allArgs[dashIdx:]
	}
	if len(preDash) > 0 {
		err := fmt.Errorf("unknown command %q for %q", preDash[0], "gomplate")
		return cobraError(err, true)
	}
	verboseEnabled = fv.verbose

	// custom flag validations & parsing
	// Datasources + contexts first
	cliDatasources := make(map[string]configpkg.DataSource)
	cliContexts := make(map[string]configpkg.DataSource)
	// helper to parse datasource strings
	for _, rawArg := range fv.datasources {
		alias, ds, perr := parseDatasourceArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		if alias == "" && ds.URL == "" && rawArg == "" {
			continue
		}
		// Empty rawArg means --datasource= with empty value - skip (original)
		if rawArg == "" {
			continue
		}
		cliDatasources[alias] = ds
	}
	for _, rawArg := range fv.contexts {
		alias, ds, perr := parseDatasourceArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		if rawArg == "" { continue }
		cliContexts[alias] = ds
	}
	// headers
	type headerEntry struct { alias string; header http.Header }
	var cliHeaders []headerEntry
	for _, rawArg := range fv.headers {
		alias, hdr, perr := parseHeaderArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		cliHeaders = append(cliHeaders, headerEntry{alias, hdr})
	}
	// plugins
	cliPlugins := make(map[string]gomplatectx.PluginConfig)
	// Use ctx PluginConfig type
	for _, rawArg := range fv.plugins {
		if rawArg == "" { continue }
		name, pc, perr := parsePluginArg(rawArg)
		if perr != nil {
			return cobraError(perr, false)
		}
		cliPlugins[name] = pc
	}
	// templates parsing (store raw, normalized later) - no validation error except URL parse?
	cliTemplates := make(map[string]configpkg.DataSource)
	// maintain order of template args for deterministic nested loading - config map sorted by alias in marshal but nested templates order may matter for overrides definitions. Use slice too.
	type tmplEntry struct { alias string; ds configpkg.DataSource }
	var cliTemplateList []tmplEntry
	for _, rawArg := range fv.templates {
		if rawArg == "" { continue }
		alias, ds := parseTemplateArg(rawArg)
		cliTemplates[alias] = ds
		cliTemplateList = append(cliTemplateList, tmplEntry{alias, ds})
	}

	// environment config preliminary (plugin timeout invalid etc will be checked after config file? original cobra error category)
	// Determine config file path
	configPath := ""
	configExplicit := false
	if fs.Lookup("config").Changed {
		configPath = fv.configPath
		configExplicit = true
		if configPath == "" {
			configExplicit = false // disabled
		}
	} else if envCfg, present := os.LookupEnv("GOMPLATE_CONFIG"); present {
		if envCfg == "" {
			configPath = ""
			configExplicit = false
		} else {
			configPath = envCfg
			configExplicit = true
		}
	} else {
		// default
		if _, err := os.Stat(".gomplate.yaml"); err == nil {
			configPath = ".gomplate.yaml"
			configExplicit = false // but used
		} else {
			configPath = ""
		}
	}

	var fileCfg *configpkg.Config
	var cfgFileUsed string
	if configPath != "" {
		content, err := readFileForConfig(configPath)
		if err != nil {
			// config file requested, but couldn't be opened...
			// if default file exists but unreadable? Treat as requested if explicit or default present.
			msg := fmt.Sprintf("config file requested, but couldn't be opened: %v", err)
			return cobraError(fmt.Errorf("%s", msg), false)
		}
		cfgParsed, err := parseConfigFile(configPath, content)
		if err != nil {
			return cobraError(err, false)
		}
		fileCfg = cfgParsed
		cfgFileUsed = configPath
		_ = configExplicit
	}
	if cfgFileUsed != "" && verboseEnabled {
		logMsg("DEBUG", "using config file", logAttr{"cfgFile", cfgFileUsed})
	}

	// Build merged config
	cfg := configpkg.Config{}
	// env defaults first
	// GOMPLATE_LEFT_DELIM etc
	if v, present := os.LookupEnv("GOMPLATE_LEFT_DELIM"); present { cfg.LeftDelim = v }
	if v, present := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); present { cfg.RightDelim = v }
	if v, present := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); present {
		if b, err := strconv.ParseBool(v); err == nil { cfg.Experimental = b }
	}
	if v, present := os.LookupEnv("GOMPLATE_PLUGIN_TIMEOUT"); present {
		d, err := time.ParseDuration(v)
		if err != nil {
			msg := fmt.Sprintf("GOMPLATE_PLUGIN_TIMEOUT set to invalid value %q: %v", v, err)
			return cobraError(fmt.Errorf("%s", msg), false)
		}
		cfg.PluginTimeout = configpkg.Duration(d)
	}
	// config file overwrites env if keys present
	if fileCfg != nil {
		// detect present keys via yaml map
		present := presentKeys(cfgFileUsed)
		mergeConfigFile(&cfg, fileCfg, present)
	}
	// CLI overwrites
	// datasources etc merge
	if len(cliDatasources) > 0 {
		if cfg.Datasources == nil { cfg.Datasources = make(map[string]configpkg.DataSource) }
		for k, v := range cliDatasources { cfg.Datasources[k] = v }
	}
	if len(cliContexts) > 0 {
		if cfg.Context == nil { cfg.Context = make(map[string]configpkg.DataSource) }
		for k, v := range cliContexts { cfg.Context[k] = v }
	}
