	// We'll use package var cliHeaderMap
	if cliHeaderMap == nil { cliHeaderMap = make(map[string]http.Header) }
	// merge into global
	exist := cliHeaderMap[alias]
	if exist==nil { exist = make(http.Header) }
	for k, vals := range hdr { exist[k]=append(exist[k], vals...) }
	cliHeaderMap[alias]=exist

	applyTo := func(m map[string]configpkg.DataSource) {
		if m==nil { return }
		if ds, ok := m[alias]; ok {
			if ds.Header==nil { ds.Header=make(http.Header) }
			for k, vals:=range hdr { ds.Header[k]=append(ds.Header[k], vals...) }
			m[alias]=ds
		}
	}
	applyTo(cfg.Datasources); applyTo(cfg.Context); applyTo(cfg.Templates)
}

