func parseDatasourceArg(s string) (string, configpkg.DataSource, error) {
	if s == "" {
		return "", configpkg.DataSource{Header: make(http.Header)}, nil
	}
	// url parse for error detection on whole string if no "="? Original error for " merge:..." gave url.Parse error.
	// If s contains "=", left/right split
	if idx := strings.Index(s, "="); idx >= 0 {
		left := s[:idx]
		right := s[idx+1:]
		if left == "" && right == "" {
			return "", configpkg.DataSource{}, fmt.Errorf("invalid argument (%s): must provide an alias with files not in working directory", s)
		}
		if right == "" {
			// a= case
			alias := s
			urlStr := left
			return alias, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(urlStr)}, nil
		}
		alias := left
		urlStr := right
		// parse URL for validation/ normalization
		if _, err := url.Parse(urlStr); err != nil {
			return "", configpkg.DataSource{}, err
		}
		return alias, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(urlStr)}, nil
	}
	// no alias
	u, err := url.Parse(s)
	if err != nil {
		return "", configpkg.DataSource{}, err
	}
	// dir of path
	p := u.Path
	dir := gopath.Dir(p)
	// special opaque (merge:...) Path empty, Dir "."
	if u.Opaque != "" && p == "" {
		// alias is whole string
		return s, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(s)}, nil
	}
	if dir != "." {
		return "", configpkg.DataSource{}, fmt.Errorf("invalid argument (%s): must provide an alias with files not in working directory", s)
	}
	base := gopath.Base(p)
	ext := gopath.Ext(base)
	alias := strings.TrimSuffix(base, ext)
	if alias == "" || alias == "." {
		alias = s
	}
	return alias, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(s)}, nil
}

func parseTemplateArg(s string) (string, configpkg.DataSource) {
	if idx := strings.Index(s, "="); idx >= 0 {
		left := s[:idx]
		right := s[idx+1:]
		if right == "" {
			// = ? behaviour ignore
			return left, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(right)}
		}
		return left, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(right)}
	}
	return s, configpkg.DataSource{Header: make(http.Header), URL: configpkg.NormalizeURLString(s)}
}

func parseHeaderArg(s string) (string, http.Header, error) {
	idx := strings.Index(s, "=")
	if idx < 0 {
		return "", nil, fmt.Errorf("invalid datasource-header option '%s'", s)
	}
	alias := s[:idx]
	rest := s[idx+1:]
	// rest should be "Name: value"
	colon := strings.Index(rest, ":")
	if colon < 0 {
		return "", nil, fmt.Errorf("invalid HTTP Header format '%s'", rest)
	}
	name := strings.TrimSpace(rest[:colon])
	value := strings.TrimSpace(rest[colon+1:])
	if name == "" {
		return "", nil, fmt.Errorf("invalid HTTP Header format '%s'", rest)
	}
	h := make(http.Header)
	h.Add(http.CanonicalHeaderKey(name), value)
	// Original header canonicalization: http.Header keys are canonical MIME (Authorization, X-Custom... ) - textproto canonical.
	// For YAML dump, header keys are as canonical? If user gives "x", it becomes "X". Good.
	return alias, h, nil
}

func parsePluginArg(s string) (string, gomplatectx.PluginConfig, error) {
	idx := strings.Index(s, "=")
	if idx < 0 {
		return "", gomplatectx.PluginConfig{}, fmt.Errorf("plugin requires both name and path")
	}
	name := s[:idx]
	cmd := s[idx+1:]
	// a= case: name a, cmd "" - original returned success and config dump? Probe: --plugin a= gave config plugin a with cmd ""? Earlier it had no error. Keep.
	return name, gomplatectx.PluginConfig{Cmd: cmd}, nil
}
