func makeStdinFunc() func() ([]byte, error) {
	var cache []byte
	var err error
	var done bool
	return func() ([]byte, error) {
		if done { return cache, err }
		done = true
		// Only read if stdin is not? Reading from terminal would block if user ran -i without stdin datasource - but this func is only called lazily when stdin needed (template input '-' or stdin datasource). If it's terminal and needed, read would block until EOF - same as original.
