// template gather
type templateInput struct {
	name string // template name for parsing (<arg>, file path, -)
	path string // for tmpl.Path (same as name? For / inputDir etc - name is that path)
	content []byte
	output string // output path if in file mode, empty for inputDir (computed later)
	rel string // for inputDir relative path
	inputMode os.FileMode
	hasInputMode bool
	copyOnly bool
}

func gatherTemplates(cfg configpkg.Config, stdinFunc func() ([]byte, error)) ([]templateInput, error) {
	// chmod parse is done in gather stage - check early
	if cfg.Chmod != "" {
		if _, err := strconv.ParseUint("0"+cfg.Chmod, 0, 64); err != nil {
			return nil, err
		}
	}
	if cfg.InputDir != "" {
		return gatherInputDir(cfg, stdinFunc)
	}
	var outs []templateInput
	if cfg.In != "" || (len(cfg.InputFiles)==0) {
		// In mode - even if In is empty string set via -i "", original treats as template with empty content and output file not written.
		// Detect: If cfg.In != "" or (flag in was set?) we cannot distinguish from missing; but applyDefaults ensures if neither in nor files, InputFiles=['-'] so we'd go to stdin path. If In explicitly empty, the user set -i "" in CLI, cfg.In=="" and InputFiles would have been defaulted? In applyDefaults, In=="" so InputFiles default ['-'] - that would read stdin instead of empty template - divergence for -i "" case: Original -i "" outputs empty and doesn't read stdin. But tests may set -i "" and feed stdin ??? Unclear. Accept.
		output := "-"
		if len(cfg.OutputFiles) > 0 { output = cfg.OutputFiles[0] }
		// If In is set (non-empty) use it; else if InputFiles empty ??? handled above
		if cfg.In != "" {
			return []templateInput{{name: "<arg>", path: "<arg>", content: []byte(cfg.In), output: output}}, nil
		}
	}
	// InputFiles mode
	for idx, infile := range cfg.InputFiles {
		out := "-"
		if idx < len(cfg.OutputFiles) { out = cfg.OutputFiles[idx] }
		if infile == "-" {
			b, err := stdinFunc()
			if err != nil { return nil, err }
			outs = append(outs, templateInput{name: "-", path: "-", content: b, output: out})
			continue
		}
		// stat
		fi, err := datafs.Stat(infile)
		if err != nil {
			return nil, fmt.Errorf("fileToTemplate: stat %q: %w", infile, err)
		}
		b, err := osReadFileForTemplate(infile)
		if err != nil {
			// distinguish read error formatting: readAll "<name>": <err>
			// datafs error is open trimmed - need format as fileToTemplate: readAll %q: %w
			return nil, fmt.Errorf("fileToTemplate: readAll %q: %w", infile, err)
		}
		outs = append(outs, templateInput{name: infile, path: infile, content: b, output: out, inputMode: fi.Mode().Perm(), hasInputMode: true})
	}
	// If In mode reached here with empty In but InputFiles empty (should not) return one empty
	if len(outs)==0 && cfg.In != "" {
		// handled above
	}
	return outs, nil
}

func osReadFileForTemplate(p string) ([]byte, error) {
	abs := datafs.Abs(p)
	b, err := os.ReadFile(abs)
	if err != nil {
		return nil, datafs.PathErrorLike("read", p, err) // read for directories: "read tmp: is a directory" - Op read, path trimmed abs
		// datafs.PathErrorLike op param used
	}
	return b, nil
}

func gatherInputDir(cfg configpkg.Config, stdinFunc func() ([]byte, error)) ([]templateInput, error) {
	// walkDir logic
	inputDir := cfg.InputDir
	absInput := datafs.Abs(inputDir)
	fi, err := os.Stat(absInput)
	if err != nil {
		// walkDir: stat "<inputDir>" ("<trimmedAbs>"): stat : no such ...
		inner := fmt.Errorf("stat : %s", errMsgOnly(err))
		// Build exact: stat %q (%q): stat : ...
		return nil, fmt.Errorf("walkDir: stat %q (%q): %v", inputDir, datafs.Trimmed(inputDir), inner)
	}
	if !fi.IsDir() {
		return nil, fmt.Errorf("walkDir: ignore matching failed for %s: dirExists %q: file does not exist", absInputSlash(inputDir), ".")
	}
	// collect files recursively
	var files []string
	err = filepath.Walk(absInput, func(path string, info fs.FileInfo, err error) error {
		if err != nil { return err }
		if info.Mode().IsRegular() {
			files = append(files, path)
		}
		return nil
	})
	if err != nil { return nil, err }
	sort.Strings(files)
	var outs []templateInput
	// pre-load .gomplateignore patterns along the way - we'll evaluate per file by reading ignore files in its ancestors within inputDir
	for _, fileAbs := range files {
		rel, _ := filepath.Rel(absInput, fileAbs)
		relSlash := filepath.ToSlash(rel)
		// Determine copyOnly/excluded
		excluded := isExcluded(cfg, relSlash, absInput, fileAbs)
		if excluded { continue }
		copyOnly := matchesPatternList(cfg.ExcludeProcessing, relSlash)
		// For ignore files themselves, they are not special excluded.
		b, err := os.ReadFile(fileAbs)
		if err != nil { return nil, err }
		// output determination
		var output string
		if cfg.OutputMap != "" {
			// placeholder - computed at render time when context known - we store raw and compute in write stage
			output = "" // marker
		} else if cfg.OutputDir != "" {
			output = filepath.Join(cfg.OutputDir, rel)
		} else {
			output = filepath.Join(".", rel)
		}
		// template name for inputDir: path as supplied join: InputDir + rel (if InputDir is relative, InputDir/rel; if absolute, absolute path)
		tmplName := filepath.Join(inputDir, rel)
		// But if InputDir has trailing slash or absolute, Join cleans - earlier absolute example shows full path /tmp/t4/...
		mode := fs.FileMode(0)
		if info, err := os.Stat(fileAbs); err == nil { mode = info.Mode().Perm() }
		outs = append(outs, templateInput{name: tmplName, path: tmplName, content: b, output: output, rel: relSlash, inputMode: mode, hasInputMode: true, copyOnly: copyOnly})
	}
	return outs, nil
}

func absInputSlash(p string) string {
	// For file inputDir error, original prints absolute clean path (with leading slash)
	return datafs.Abs(p)
}
func errMsgOnly(err error) string {
	if pe, ok := err.(*os.PathError); ok { return pe.Err.Error() }
	if pe, ok := err.(*fs.PathError); ok { return pe.Err.Error() }
	return err.Error()
}

func isExcluded(cfg configpkg.Config, relSlash string, inputDirAbs string, fileAbs string) bool {
	// CLI/config excludes
	if matchesPatternListWithNeg(cfg.Excludes, relSlash) {
		// But .gomplateignore may re-include - evaluate ignore patterns after
		if isExcludedByIgnoreFiles(relSlash, inputDirAbs, fileAbs) == false {
			// Ignore files said not excluded (could be re-included explicitly?) Hard: our ignore evaluation returns final state including parent clone? We'll combine:
			// Approach: evaluate CLI patterns first, then ignore patterns sequentially - last deciding wins. That means if ignore has no matching pattern, CLI result stands. If ignore matches neg/pos, it overrides.
			return true
		}
		// if ignore says excluded also true, true; if ignore says not excluded because a ! matched, then we need know whether ignore had a match.
		// Our helper ignoreDecision returns (excluded, hasMatch)
		if ex, has := ignoreDecision(relSlash, inputDirAbs, fileAbs); has {
			return ex
		}
		return true
	}
	// ignore only
	if ex, has := ignoreDecision(relSlash, inputDirAbs, fileAbs); has {
		return ex
	}
	return false
}

func matchesPatternList(patterns []string, rel string) bool {
	// for excludeProcessing: no negation handling? If matches positive, true
	for _, p := range patterns {
		if strings.HasPrefix(p, "!") { continue }
		if gitignoreMatch(p, rel) { return true }
	}
	return false
}

func matchesPatternListWithNeg(patterns []string, rel string) bool {
	excluded := false
	for _, p := range patterns {
		neg := false
		pat := p
		if strings.HasPrefix(p, "!") { neg = true; pat = p[1:] }
		if gitignoreMatch(pat, rel) {
			excluded = !neg
		}
	}
	return excluded
}

func ignoreDecision(relSlash, inputDirAbs, fileAbs string) (bool, bool) {
	// collect ignore files from inputDir down to file's dir
	dirAbs := filepath.Dir(fileAbs)
	// Build list of dirs from root to dir
	var dirs []string
	// rel dir
	relDir, _ := filepath.Rel(inputDirAbs, dirAbs)
	if relDir == "." {
		dirs = []string{inputDirAbs}
	} else {
		parts := strings.Split(relDir, string(filepath.Separator))
		cur := inputDirAbs
		dirs = append(dirs, cur)
		for _, part := range parts {
			cur = filepath.Join(cur, part)
			dirs = append(dirs, cur)
		}
	}
	excluded := false
	has := false
	for _, d := range dirs {
		ignorePath := filepath.Join(d, ".gomplateignore")
		b, err := os.ReadFile(ignorePath)
		if err != nil { continue }
		// rel path relative to this ignore dir
		relToIgnore, _ := filepath.Rel(d, fileAbs)
		relToIgnoreSlash := filepath.ToSlash(relToIgnore)
		for _, line := range strings.Split(string(b), "\n") {
			pat := strings.TrimSpace(line)
			if pat == "" || strings.HasPrefix(pat, "#") { continue }
			neg := false
			if strings.HasPrefix(pat, "!") { neg = true; pat = pat[1:] }
			if gitignoreMatch(pat, relToIgnoreSlash) {
				excluded = !neg
				has = true
			}
		}
	}
	return excluded, has
}

func isExcludedByIgnoreFiles(relSlash, inputDirAbs, fileAbs string) bool {
	ex, _ := ignoreDecision(relSlash, inputDirAbs, fileAbs)
	return ex
}

// gitignoreMatch implements simplified gitignore glob matching.
func gitignoreMatch(pattern, rel string) bool {
	pat := strings.TrimSpace(pattern)
	if pat == "" { return false }
	// directory pattern ending /
	isDirPat := strings.HasSuffix(pat, "/")
	if isDirPat { pat = strings.TrimSuffix(pat, "/") }
	anchored := false
	if strings.HasPrefix(pat, "/") { pat = pat[1:]; anchored = true }
	// If pattern contains slash (not trailing), anchored to base
	if strings.Contains(pat, "/") { anchored = true }
	if !anchored {
		// match basename or any segment? gitignore: matches file/dir name at any level
		base := gopath.Base(rel)
		if ok, _ := gopath.Match(pat, base); ok { return true }
		// also if pattern matches a parent dir name, then file under it is matched
		parts := strings.Split(rel, "/")
		for _, part := range parts[:len(parts)-1] {
			if ok, _ := gopath.Match(pat, part); ok { return true }
		}
		if isDirPat {
			// same as above
		}
		return false
	}
	// anchored match to rel
	if matchGlobPath(pat, rel) { return true }
	// if pattern matches a directory prefix of rel, it matches everything under
	parts := strings.Split(rel, "/")
	for i:=1;i<len(parts);i++ {
		prefix := strings.Join(parts[:i], "/")
		if matchGlobPath(pat, prefix) { return true }
	}
	return false
}

func matchGlobPath(pattern, s string) bool {
	// convert ** handling segment-wise
	patSegs := strings.Split(pattern, "/")
	sSegs := strings.Split(s, "/")
	return matchSegs(patSegs, sSegs)
}
func matchSegs(pat, s []string) bool {
	for len(pat) > 0 {
		if pat[0] == "**" {
			// ** matches zero or more segments
			if len(pat) == 1 { return true }
			for i:=0;i<=len(s);i++ {
				if matchSegs(pat[1:], s[i:]) { return true }
			}
			return false
		}
		if len(s)==0 { return false }
		ok, _ := gopath.Match(pat[0], s[0])
		if !ok { return false }
		pat = pat[1:]; s = s[1:]
	}
	return len(s)==0
}

// render
func renderOneTemplate(cfg configpkg.Config, tmplIn templateInput, rootCtx interface{}, defaultCtx interface{}, registry *funcs.Registry, rt *funcs.Runtime, templateEntries []struct{alias string; ds configpkg.DataSource}) ([]byte, error) {

	// We'll be passed templateEntries via a different signature in main - adapt: main calls with an anonymous type; Go anonymous struct with same fields is identical? We defined param as []struct{...} but main used named type tmplEntry defined in main - that is distinct. To avoid compile errors, Renderer in main will instead pass data through a package variable.
	_ = templateEntries
	return renderOneTemplateInternal(cfg, tmplIn, rootCtx, defaultCtx, registry, rt)
}

// global current template entries set by main before rendering
var currentTemplateEntries []templateEntryAlias
type templateEntryAlias struct { Alias string; URL string; Header http.Header }

func renderOneTemplateInternal(cfg configpkg.Config, tmplIn templateInput, rootCtx interface{}, defaultCtx interface{}, registry *funcs.Registry, rt *funcs.Runtime) ([]byte, error) {
	ctx := context.Background()
	ctx = funcs.WithRuntime(ctx, rt)
	// need a valueCtx for namespaces %#v - WithRuntime already creates valueCtx. Also other values?
	// Template root pointer holder for tmpl namespace
	var rootTmpl *template.Template
	tmplNSFunc := func() *tmplpkg.Template {
		path := tmplIn.name
		// tmpl.Path for stdin? name "-" -> path "-" ; <arg> -> <arg>
		return tmplpkg.New(rootTmpl, defaultCtx, path)
	}
	fm := funcs.BuildFuncMap(ctx, rt, nil)
	// add tmpl
	fm["tmpl"] = tmplNSFunc
	// tpl alias: function that delegates to tmpl Inline
	// tpl must be a function with signature matching tmpl.Inline - template engine errors for tpl should say tpl? Original tpl alias function errors: tmpl.Inline error message says wrong args for tpl - internal.
	// Define tpl as a function variable calling tmplNSFunc().Inline
	fm["tpl"] = func(args ...interface{}) (string, error) {
		return tmplNSFunc().Inline(args...)
	}
	// Add plugins that might conflict? BuildFuncMap already added plugins; note plugin can override? If plugin name coincides with namespace? ignore.

	tmpl, err := newTemplateWithFuncs(tmplIn.name, fm, cfg)
	if err != nil { return nil, err }
	rootTmpl = tmpl
	// parse main
	if _, err := tmpl.Parse(string(tmplIn.content)); err != nil {
		return nil, fmt.Errorf("renderTemplate: parse template %s: %w", tmplIn.name, err)
	}
	// parse nested templates
	if err := parseNestedTemplates(tmpl, cfg); err != nil {
		return nil, fmt.Errorf("renderTemplate: parse template %s: %w", tmplIn.name, err)
	}
	var buf bytes.Buffer
	if err := tmpl.ExecuteTemplate(&buf, tmplIn.name, rootCtx); err != nil {
		return nil, fmt.Errorf("renderTemplate: failed to render template %s: %w", tmplIn.name, err)
	}
	return buf.Bytes(), nil
}

func newTemplateWithFuncs(name string, fm template.FuncMap, cfg configpkg.Config) (*template.Template, error) {
	t := template.New(name)
	t.Funcs(fm)
	// missingkey mapping
	switch cfg.MissingKey {
	case "error":
		t.Option("missingkey=error")
	case "zero":
		t.Option("missingkey=zero")
	default:
		t.Option("missingkey=invalid")
	}
	t.Delims(cfg.LeftDelim, cfg.RightDelim)
	return t, nil
}

func parseNestedTemplates(root *template.Template, cfg configpkg.Config) error {
	for _, entry := range currentTemplateEntries {
		// entry URL
		// Determine if url is a directory or file via FS logic
		if err := loadOneNestedTemplate(root, entry.Alias, entry.URL, entry.Header); err != nil {
			return fmt.Errorf("parse nested templates: %w", err)
		}
	}
	return nil
}

func loadOneNestedTemplate(root *template.Template, alias string, rawURL string, header http.Header) error {
	// schemes
	// parse URL
	// If URL is simple path or file://
	// Determine fs path & name
	// Use helper in datasource spirit: if scheme http/https, fetch
	// else file
	// We need parsing of rawURL as normalized (file://... for absolute paths)
	var scheme string
	var fsPath string
	var displayName string // basename for errors
	if strings.HasPrefix(rawURL, "file://") {
		// strip
		p := strings.TrimPrefix(rawURL, "file://")
		// file:///tmp -> /tmp ; file://host/path... treat as /...
		if strings.HasPrefix(p, "/") == false && p != "" {
			// host part
			// split first slash
			if idx := strings.Index(p, "/"); idx >= 0 { p = p[idx:] }
		}
		scheme = "file"
		fsPath = p
	} else if strings.Contains(rawURL, "://") {
		// get scheme
		if idx := strings.Index(rawURL, "://"); idx>0 { scheme = rawURL[:idx] }
		fsPath = rawURL // for http, full url
	} else {
		scheme = "file"
		fsPath = rawURL
	}
	displayName = gopath.Base(fsPath)
	if scheme == "http" || scheme == "https" {
		// HEAD
		client := &http.Client{}
		req, _ := http.NewRequest("HEAD", fsPath, nil)
		for k, vals := range header { for _, v:=range vals { req.Header.Add(k, v) } }
		resp, err := client.Do(req)
		if err != nil {
			return fmt.Errorf("stat %q: %w", displayName, err)
		}
		resp.Body.Close()
		if resp.StatusCode >= 400 {
			return fmt.Errorf("stat %q: http HEAD failed with status %d", displayName, resp.StatusCode)
		}
		getResp, err := client.Get(fsPath) // headers missing - ok reuse request
