package funcs

import (
	"crypto/subtle"
	"fmt"
	"strconv"
	"strings"
)

type blowfishCipher struct {
	p [18]uint32
	s [4][256]uint32
}

func newBlowfish() *blowfishCipher {
	c := &blowfishCipher{}
	copy(c.p[:], bfP[:])
	for i := 0; i < 4; i++ {
		copy(c.s[i][:], bfS[i][:])
	}
	return c
}

func (c *blowfishCipher) encryptBlock(l, r uint32) (uint32, uint32) {
	for i := 0; i < 16; i += 2 {
		l ^= c.p[i]
		// Feistel
		// Round i: r ^= F(l)
		r ^= bfF(c, l)
		l, r = r, l // we will do manual two rounds below instead - this swap approach complex. Use standard loop below alternative.
		_ = i
		break
	}
	// Standard implementation:
	// Reimplement cleanly starting from inputs is not possible after mutation, so encryptBlock is implemented in encryptPair below.
	return l, r
}

func bfF(c *blowfishCipher, x uint32) uint32 {
	return ((c.s[0][x>>24] + c.s[1][(x>>16)&0xff]) ^ c.s[2][(x>>8)&0xff]) + c.s[3][x&0xff]
}

func (c *blowfishCipher) encryptPair(l, r *uint32) {
	for i := 0; i < 16; i++ {
		*l ^= c.p[i]
		*r ^= bfF(c, *l)
		*l, *r = *r, *l
	}
	*l, *r = *r, *l
	*r ^= c.p[16]
	*l ^= c.p[17]
}

// expandKey performs EksBlowfish key expansion. If salt is nil, no salt xor.
func (c *blowfishCipher) expandKey(key, salt []byte) {
	// XOR P with key bytes cyclic big-endian
	j := 0
	for i := 0; i < 18; i++ {
		var d uint32
		for k := 0; k < 4; k++ {
			d = d<<8 | uint32(key[j])
			j++
			if j >= len(key) {
				j = 0
			}
		}
		c.p[i] ^= d
	}
	var l, r uint32
	saltPos := 0
	nextSaltWord := func() uint32 {
		if salt == nil || len(salt) == 0 {
			return 0
		}
		var d uint32
		for k := 0; k < 4; k++ {
			d = d<<8 | uint32(salt[saltPos])
			saltPos++
			if saltPos >= len(salt) {
				saltPos = 0
			}
		}
		return d
	}
	for i := 0; i < 18; i += 2 {
		if salt != nil {
			l ^= nextSaltWord()
			r ^= nextSaltWord()
		}
		c.encryptPair(&l, &r)
		c.p[i] = l
		c.p[i+1] = r
	}
	for box := 0; box < 4; box++ {
		for i := 0; i < 256; i += 2 {
			if salt != nil {
				l ^= nextSaltWord()
				r ^= nextSaltWord()
			}
			c.encryptPair(&l, &r)
			c.s[box][i] = l
			c.s[box][i+1] = r
		}
	}
}

func eksSetup(cost uint, key, salt []byte) *blowfishCipher {
	c := newBlowfish()
	c.expandKey(key, salt)
	rounds := 1
	// cost may be large - guard like bcrypt: 2^cost iterations; cost validated 4-31
	for i := uint(0); i < cost; i++ {
		rounds *= 2
	}
	for i := 0; i < rounds; i++ {
		c.expandKey(key, nil)
		c.expandKey(salt, nil)
	}
	return c
}

// bcrypt base64 ---------------------------------------------------------
const bcryptAlphabet = "./ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

var bcryptReverse = func() [256]int {
	var t [256]int
	for i := range t {
		t[i] = -1
	}
	for i, ch := range bcryptAlphabet {
		t[ch] = i
	}
	return t
}()

func bcryptBase64Encode(data []byte, resultLen int) string {
	var sb strings.Builder
	off := 0
	for {
		if off >= len(data) {
			break
		}
		c1 := uint32(data[off])
		off++
		sb.WriteByte(bcryptAlphabet[(c1>>2)&0x3f])
		c1 = (c1 & 0x03) << 4
		if off >= len(data) {
			sb.WriteByte(bcryptAlphabet[c1&0x3f])
			break
		}
		c2 := uint32(data[off])
		off++
		c1 |= (c2 >> 4) & 0x0f
		sb.WriteByte(bcryptAlphabet[c1&0x3f])
		c1 = (c2 & 0x0f) << 2
		if off >= len(data) {
			sb.WriteByte(bcryptAlphabet[c1&0x3f])
			break
		}
		c2 = uint32(data[off])
		off++
		c1 |= (c2 >> 6) & 0x03
		sb.WriteByte(bcryptAlphabet[c1&0x3f])
		sb.WriteByte(bcryptAlphabet[c2&0x3f])
		if resultLen > 0 && sb.Len() >= resultLen {
			break
		}
	}
	out := sb.String()
	if resultLen > 0 && len(out) > resultLen {
		out = out[:resultLen]
	}
	return out
}

func bcryptBase64Decode(s string) ([]byte, error) {
	var out []byte
	off := 0
	for off < len(s) {
		c1 := bcryptReverse[s[off]]
		off++
		if c1 < 0 || off >= len(s) {
			break
		}
		c2 := bcryptReverse[s[off]]
		off++
		if c2 < 0 {
			return nil, fmt.Errorf("bad bcrypt base64")
		}
		out = append(out, byte((c1<<2)|((c2&0x30)>>4)))
		if off >= len(s) {
			break
		}
		c3 := bcryptReverse[s[off]]
		off++
		if c3 < 0 {
			return nil, fmt.Errorf("bad bcrypt base64")
		}
		out = append(out, byte(((c2&0x0f)<<4)|((c3&0x3c)>>2)))
		if off >= len(s) {
			break
		}
		c4 := bcryptReverse[s[off]]
		off++
		if c4 < 0 {
			return nil, fmt.Errorf("bad bcrypt base64")
		}
		out = append(out, byte(((c3&0x03)<<6)|c4))
	}
	return out, nil
}

func bcryptHashWithSalt(password []byte, salt []byte, cost int) (string, error) {
	if cost < 4 || cost > 31 {
		return "", fmt.Errorf("crypto/bcrypt: cost %d is outside allowed range (4,31)", cost)
	}
	// $2a$ key includes NUL terminator
	key := make([]byte, len(password)+1)
	copy(key, password)
	// If password > 72 bytes, x/crypto would ... bcrypt algorithm limits key cycling anyway; our expandKey cycles key bytes repeatedly, but blowfish key expansion effectively uses first 72 bytes in P xor cycles? P xor processes 72 bytes (18*4). If key longer, first cycle is 72, then ... It cycles within 18 words exactly 72 bytes - subsequent bytes beyond 72 are never used because j wraps after len, but first 18 words consume 72 bytes before wrap; if len>72, bytes beyond 72 not visited in first P pass, but in subsequent ExpandKey(key) calls, same first 72 consumed. So fine.
	cipher := eksSetup(uint(cost), key, salt)
	ctext := []byte("OrpheanBeholderScryDoubt")
	// encrypt each 8-byte block 64 times
	for i := 0; i < 64; i++ {
		for block := 0; block < len(ctext); block += 8 {
			l := uint32(ctext[block])<<24 | uint32(ctext[block+1])<<16 | uint32(ctext[block+2])<<8 | uint32(ctext[block+3])
			r := uint32(ctext[block+4])<<24 | uint32(ctext[block+5])<<16 | uint32(ctext[block+6])<<8 | uint32(ctext[block+7])
			cipher.encryptPair(&l, &r)
			ctext[block] = byte(l >> 24)
			ctext[block+1] = byte(l >> 16)
			ctext[block+2] = byte(l >> 8)
			ctext[block+3] = byte(l)
			ctext[block+4] = byte(r >> 24)
			ctext[block+5] = byte(r >> 16)
			ctext[block+6] = byte(r >> 8)
			ctext[block+7] = byte(r)
		}
