	}
	sb.WriteString(strconv.Itoa(cost))
	sb.WriteString("$")
	sb.WriteString(bcryptBase64Encode(salt, 22))
	sb.WriteString(bcryptBase64Encode(hash, 31))
	return sb.String(), nil
}

func bcryptNative(args ...interface{}) (string, error) {
	if len(args) < 1 || len(args) > 2 {
		return "", fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}
	cost := 10
	input := args[len(args)-1]
	if len(args) == 2 {
		c, err := toInt(args[0])
		if err != nil {
