	// Detect trailing [ ... ] after a balanced base ending with ] or )
	if !strings.HasSuffix(expr, "]") { return false, nil, nil }
	// Find opening bracket for last segment using scan from end balancing
	depth := 0
	start := -1
	for i := len(expr)-1; i >= 0; i-- {
		if expr[i] == ']' { depth++ }
		if expr[i] == '[' {
			depth--
			if depth == 0 { start = i; break }
		}
	}
	if start <= 0 { return false, nil, nil }
	base := strings.TrimSpace(expr[:start])
	inner := strings.TrimSpace(expr[start+1 : len(expr)-1])
	// base must be compound (ends with ] or ) or be an array/object literal / function) - if base is simple path, let jqEvalPath handle
	if !(strings.HasSuffix(base, "]") || strings.HasSuffix(base, ")") || strings.HasSuffix(base, "}")) {
		return false, nil, nil
	}
