	if err != nil { return true, nil, err }
	var out []interface{}
	for _, v := range bres {
		if inner == "" {
			if s, err := toSlice(v); err == nil { out = append(out, s...); continue }
			return true, nil, fmt.Errorf("jq: cannot iterate")
		}
