		if err != nil { return false, nil, nil }
		if s, err := toSlice(v); err == nil {
			if idx < 0 { idx = len(s)+idx }
			if idx >=0 && idx < len(s) { out = append(out, s[idx]) } else { out = append(out, nil) }
			continue
		}
		out = append(out, nil)
	}
	return true, out, nil
}

func findTopOperator(expr string, ops []string) (int, string) {
	depthB, depthP, depthBr := 0,0,0
	inStr:=false; esc:=false
	for i:=0;i<len(expr);i++ {
		c:=expr[i]
		if inStr { if esc{esc=false;continue}; if c=='\\\\'{esc=true;continue}; if c=='"'{inStr=false}; continue }
		switch c {
		case '"': inStr=true
		case '[': depthB++
		case ']': depthB--
		case '(': depthP++
		case ')': depthP--
		case '{': depthBr++
		case '}': depthBr--
		default:
			if depthB==0 && depthP==0 && depthBr==0 && i>0 {
				for _, op := range ops {
					if strings.HasPrefix(expr[i:], op) {
						// avoid treating '-' in negative numbers? i>0 ensures left exists
						return i, op
					}
				}
			}
		}
	}
	return -1, ""
}

func jqBinary(expr string, in interface{}) (bool, []interface{}, error) {
	// comparisons handled later in caller (they already exist after this point?) jqEvalSingle's comparison block is after literal handling, which occurs after path - our binary insertion is before path, so handle comparisons here as well for operands like .a == 1 inside select/map contexts.
	for _, ops := range [][]string{{"==","!=",">=","<=" ,">","<"}, {"+"}, {"*","/","%"}, {"-"}} {
		if idx, op := findTopOperator(expr, ops); idx >= 0 {
			left := strings.TrimSpace(expr[:idx])
			right := strings.TrimSpace(expr[idx+len(op):])
			if right == "" { continue }
			lres, err := jqEvalStream(left, in); if err != nil { return true, nil, err }
			rres, err := jqEvalStream(right, in); if err != nil { return true, nil, err }
			var out []interface{}
			// combine pairwise (jq typically cartesian, but single values usual)
			for _, lv := range lres {
				for _, rv := range rres {
					val, err := jqApplyOp(lv, rv, op); if err != nil { return true, nil, err }
					out = append(out, val)
				}
			}
			if len(out)==0 { out = append(out, nil) }
			return true, out, nil
		}
	}
	return false, nil, nil
}

func jqApplyOp(l, r interface{}, op string) (interface{}, error) {
	switch op {
	case "==","!=",">","<",">=","<=":
		return compareFilter(l, r, op), nil
	case "+":
		if l == nil { return r, nil }
		if r == nil { return l, nil }
		if ls, ok := l.(string); ok {
			if rs, ok := r.(string); ok { return ls+rs, nil }
		}
		if ls, err := toSlice(l); err == nil {
			if rs, err := toSlice(r); err == nil { return append(append([]interface{}{}, ls...), rs...), nil }
		}
		if lm, err := toMap(l); err == nil && lm != nil {
			if rm, err := toMap(r); err == nil && rm != nil {
				out := make(map[string]interface{})
				for k, v := range lm { out[k]=v }
				for k, v := range rm { out[k]=v }
				return out, nil
			}
		}
		lf, lerr := toFloat64(l); rf, rerr := toFloat64(r)
		if lerr==nil && rerr==nil {
			if isFloatArg(l) || isFloatArg(r) { return lf+rf, nil }
			li,_:=toInt64(l); ri,_:=toInt64(r); return li+ri, nil
		}
		return nil, fmt.Errorf("jq: cannot add %T and %T", l, r)
	case "-","*","/","%":
		lf, lerr := toFloat64(l); rf, rerr := toFloat64(r)
		if lerr!=nil || rerr!=nil { return nil, fmt.Errorf("jq: cannot calculate") }
		isFloat := isFloatArg(l) || isFloatArg(r) || op=="/"
		var res float64
		switch op { case "-": res=lf-rf; case "*": res=lf*rf; case "/": res=lf/rf; case "%": res=float64(int64(lf)%int64(rf)) }
		if isFloat { return res, nil }
		return int64(res), nil
	}
	return nil, fmt.Errorf("jq: unknown op %s", op)
}

