type tomlWriter struct {
	sb strings.Builder
	wroteAny bool
}

func (w *tomlWriter) writeMap(m map[string]interface{}, prefix []string, depth int) {
	keys := sortedKeys(m)
	indent := strings.Repeat("  ", depth)
	// scalars first
	for _, k := range keys {
		val := m[k]
		if _, isM := val.(map[string]interface{}); isM { continue }
		if mm, _ := toMap(val); mm != nil { continue }
		if isTableArray(val) { continue }
		w.sb.WriteString(indent)
		w.sb.WriteString(tomlKey(k))
		w.sb.WriteString(" = ")
		w.sb.WriteString(tomlValue(val))
		w.sb.WriteString("\\n")
		w.wroteAny = true
	}
	// tables / table arrays
	for _, k := range keys {
		val := m[k]
		if isTableArray(val) {
			arr, _ := toSlice(val)
			for _, el := range arr {
				mm, _ := toMap(el)
				if mm == nil { continue }
				full := append(append([]string{}, prefix...), k)
				if w.wroteAny { w.sb.WriteString("\\n") }
				w.sb.WriteString(indent)
				w.sb.WriteString("[[")
				var quoted []string
				for _, pth := range full { quoted = append(quoted, tomlKey(pth)) }
				w.sb.WriteString(strings.Join(quoted, "."))
				w.sb.WriteString("]]\\n")
				w.wroteAny = true
