package funcs

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// minimal CUE parser for simple data documents
type cueParser struct {
	input string
	pos int
}

func parseCUE(in string) (interface{}, error) {
	p := &cueParser{input: in}
	v, err := p.parseTop()
	if err != nil { return nil, err }
	p.skipSpacesAndSeparators()
	if p.pos < len(p.input) {
		// trailing content ignored? return error like CUE?
		// ignore
	}
	return v, nil
}

func (p *cueParser) parseTop() (interface{}, error) {
	p.skipSpacesAndSeparators()
	if p.pos >= len(p.input) { return map[string]interface{}{}, nil }
	// If starts with { or [ or quote/number/bool, parse as value, unless it's struct field at top (ident :)
	// Look ahead: if identifier/string followed by colon at top, parse as struct without braces.
	save := p.pos
	// try parse a value if first char is { [ " digit - 
	c := p.input[p.pos]
	if c == '{' || c == '[' {
		return p.parseValue()
	}
	// check for field pattern
	if isCUEIdentStart(rune(c)) || c == '"' {
		// scan field name
		_, end, ok := p.scanFieldName()
		if ok {
			// check colon after name (skipping spaces)
			i := end
			for i < len(p.input) && (p.input[i]==' '||p.input[i]=='\t') { i++ }
			if i < len(p.input) && p.input[i]==':' {
				p.pos = save
				return p.parseStructBody(0)
			}
		}
	}
	p.pos = save
	return p.parseValue()
}

func (p *cueParser) scanFieldName() (string, int, bool) {
	i := p.pos
	if i>=len(p.input) { return "", i, false }
	if p.input[i]=='"' {
		// quoted
		j:=i+1
		for j<len(p.input) && p.input[j]!='"' { if p.input[j]=='\\' { j++ }; j++ }
		if j>=len(p.input) { return "", i, false }
		s, err:=strconv.Unquote(p.input[i:j+1]); if err!=nil { return "", i, false }
		return s, j+1, true
	}
	j:=i
	for j<len(p.input) && (unicode.IsLetter(rune(p.input[j]))||unicode.IsDigit(rune(p.input[j]))||p.input[j]=='_'||p.input[j]=='-'||p.input[j]=='$') { j++ }
	if j==i { return "", i, false }
	return p.input[i:j], j, true
}

func (p *cueParser) parseStructBody(end byte) (map[string]interface{}, error) {
	out := make(map[string]interface{})
	for {
		p.skipSpacesAndSeparators()
		if p.pos>=len(p.input) { break }
		if end!=0 && p.input[p.pos]==end { p.pos++; break }
		if end!=0 && p.input[p.pos]=='}' { p.pos++; break }
		name, endPos, ok := p.scanFieldName()
		if !ok { return nil, fmt.Errorf("CUE: expected field name at %d", p.pos) }
		p.pos = endPos
		p.skipSpaces()
		if p.pos>=len(p.input) || p.input[p.pos]!=':' { return nil, fmt.Errorf("CUE: expected ':'") }
		p.pos++
		v, err := p.parseValue()
		if err != nil { return nil, err }
		out[name]=v
		// separators handled at loop top
	}
	return out, nil
}

func (p *cueParser) parseValue() (interface{}, error) {
	p.skipSpaces()
	if p.pos>=len(p.input) { return nil, nil }
	c := p.input[p.pos]
	switch {
	case c=='{':
		p.pos++
		return p.parseStructBody('}')
	case c=='[':
		p.pos++
		var arr []interface{}
		arr = []interface{}{}
		for {
			p.skipSpacesAndSeparators()
			if p.pos>=len(p.input) { break }
			if p.input[p.pos]==']' { p.pos++; break }
			v, err:=p.parseValue(); if err!=nil {return nil,err}
			arr=append(arr,v)
			p.skipSpacesAndSeparators()
			if p.pos<len(p.input) && p.input[p.pos]==',' { p.pos++; continue }
			if p.pos<len(p.input) && p.input[p.pos]==']' { continue }
		}
		return arr, nil
	case c=='"':
		// JSON string
		start:=p.pos
		j:=start+1
		for j<len(p.input) {
			if p.input[j]=='\\' { j+=2; continue }
			if p.input[j]=='"' { j++; break }
			j++
		}
		s, err:=strconv.Unquote(p.input[start:j]); if err!=nil { return nil, err }
		p.pos=j
		return s, nil
	case c=='\'':
		// CUE single-quoted string?
		end:=strings.Index(p.input[p.pos+1:], "'")
		if end<0 { return nil, fmt.Errorf("unterminated string") }
		s:=p.input[p.pos+1:p.pos+1+end]; p.pos+=end+2; return s, nil
	default:
		// token until delimiter , \n } ] or space
		start:=p.pos
		for p.pos<len(p.input) {
			ch:=p.input[p.pos]
			if ch==','||ch=='\n'||ch=='\r'||ch=='}'||ch==']'||ch==' '||ch=='\t' { break }
			p.pos++
		}
		tok:=p.input[start:p.pos]
		if tok=="true" { return true,nil }
		if tok=="false" { return false,nil }
		if tok=="null" { return nil,nil }
		if i,err:=strconv.ParseInt(tok,10,64); err==nil { return int(i), nil } // cue numbers may be int type? maps printed as int in template
		// int as int64? Original CUE values are maybe cue.Value decoding to ... data.CUE "a:1" map[a:1] type unknown. If int64 prints same.
		if f,err:=strconv.ParseFloat(tok,64); err==nil { return f,nil }
		// identifier reference - return as string?
		return tok, nil
	}
}

func (p *cueParser) skipSpaces() {
	for p.pos<len(p.input) && (p.input[p.pos]==' '||p.input[p.pos]=='\t'||p.input[p.pos]=='\r') { p.pos++ }
	// comments // ...
	if p.pos+1<len(p.input) && p.input[p.pos]=='/' && p.input[p.pos+1]=='/' {
		for p.pos<len(p.input) && p.input[p.pos]!='\n' { p.pos++ }
	}
}
func (p *cueParser) skipSpacesAndSeparators() {
	for p.pos<len(p.input) {
		c:=p.input[p.pos]
		if c==' '||c=='\t'||c=='\r'||c=='\n'||c==',' { p.pos++; continue }
		if c=='/' && p.pos+1<len(p.input) && p.input[p.pos+1]=='/' { p.skipSpaces(); continue }
		break
	}
}

func isCUEIdentStart(r rune) bool { return unicode.IsLetter(r)||r=='_'||r=='$' }

// ToCUE formatter -------------------------------------------------------
func formatCUE(v interface{}, depth int) string {
	if v==nil { return "null" }
	if s, ok:=v.(string); ok { b,_:=json.Marshal(s); return string(b) }
	if b, ok:=v.(bool); ok { if b {return "true"}; return "false" }
	if m, err:=toMap(v); err==nil && m!=nil {
		if len(m)==0 { return "{}" }
		var sb strings.Builder
		sb.WriteString("{")
		keys:=sortedKeys(m)
		for _, k:=range keys {
			sb.WriteString("\n")
			sb.WriteString(strings.Repeat("\t", depth+1))
			sb.WriteString(k)
			sb.WriteString(": ")
			sb.WriteString(formatCUE(m[k], depth+1))
		}
		sb.WriteString("\n")
		sb.WriteString(strings.Repeat("\t", depth))
		sb.WriteString("}")
		return sb.String()
	}
	if arr, err:=toSlice(v); err==nil && arr!=nil {
		var parts []string
		for _, el:=range arr { parts=append(parts, formatCUE(el, depth)) }
		return "["+strings.Join(parts, ", ")+"]"
	}
	// numbers etc using JSON marshal
	b,_:=json.Marshal(normalizeForJSON(v)); return string(b)
}
