package funcs

import (
	"os"
	"strings"
	"time"
)

func init() {
	// Initialize time.Local based only on system zoneinfo sources (not GOROOT/embedded),
	// to match behaviour in minimal environments.
	tz := os.Getenv("TZ")
	if tz != "" {
		name := strings.TrimPrefix(tz, ":")
		if strings.HasPrefix(name, "/") {
			if data, err := os.ReadFile(name); err == nil {
				if loc, err := time.LoadLocationFromTZData(name, data); err == nil {
					time.Local = loc
					return
				}
			}
			time.Local = time.UTC
			return
		}
		if loc, err := loadLocationSystem(name); err == nil {
			time.Local = loc
		} else {
			time.Local = time.UTC
		}
		return
	}
	// no TZ: /etc/localtime
	if data, err := os.ReadFile("/etc/localtime"); err == nil {
		if loc, err := time.LoadLocationFromTZData("Local", data); err == nil {
			time.Local = loc
			return
		}
	}
	time.Local = time.UTC
}

func loadLocationSystem(name string) (*time.Location, error) {
	return loadLocationLikeOriginal(name)
}

func localZoneName() string {
	tz := os.Getenv("TZ")
	if tz != "" {
		return strings.TrimPrefix(tz, ":")
	}
	// derive from /etc/localtime symlink
	if link, err := os.Readlink("/etc/localtime"); err == nil {
		// .../zoneinfo/America/New_York
		idx := strings.Index(link, "zoneinfo/")
		if idx >= 0 {
			return link[idx+len("zoneinfo/"):]
		}
		return link
	}
	if b, err := os.ReadFile("/etc/timezone"); err == nil {
		return strings.TrimSpace(string(b))
	}
	return "UTC"
}
EOF
