package funcs

import (
	"fmt"
	"os"
	"path/filepath"

	"local/gomplate/datafs"
)

func (f *FileFuncs) Exists(pathI interface{}) bool { return datafs.Exists(toString(pathI)) }
func (f *FileFuncs) IsDir(pathI interface{}) bool  { return datafs.IsDir(toString(pathI)) }
func (f *FileFuncs) Read(pathI interface{}) (string, error) {
	b, err := datafs.ReadFile(toString(pathI))
	if err != nil {
		return "", err
	}
	return string(b), nil
}
func (f *FileFuncs) ReadDir(pathI interface{}) ([]string, error) { return datafs.ReadDir(toString(pathI)) }
func (f *FileFuncs) Stat(pathI interface{}) (os.FileInfo, error) { return datafs.Stat(toString(pathI)) }
func (f *FileFuncs) Walk(pathI interface{}) ([]string, error)    { return datafs.Walk(toString(pathI)) }
func (f *FileFuncs) Write(filenameI interface{}, data interface{}) (string, error) {
	filename := toString(filenameI)
	var content []byte
	switch d := data.(type) {
	case []byte:
		content = d
	case string:
		content = []byte(d)
	default:
		content = []byte(toString(data))
	}
	wd, _ := os.Getwd()
	abs := datafs.Abs(filename)
	rel, err := filepath.Rel(wd, abs)
	if err != nil || rel == ".." || (len(rel) >= 3 && rel[:3] == "../") || (len(rel) >= 3 && rel[:3] == `..\`) {
		if err == nil {
			return "", fmt.Errorf("failed to open %s: path %s not contained by working directory %s (rel: %s)", filename, filename, wd, rel)
		}
		return "", err
	}
	err = datafs.WriteFile(filename, content, 0o644)
	if err != nil {
		return "", err
	}
	return "", nil
}
